import { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ArrowLeft, Save } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import Input from '../../../components/ui/Input'
import LexicalEditor from '../../../components/ui/LexicalEditor'
import '../../../components/ui/LexicalEditor.css'
import { forumService } from '../services/forumService'
import { showSuccess, showError } from '../../../utils/sweetalert'

const ForumForm = () => {
  const { id } = useParams()
  const navigate = useNavigate()

  const [loading, setLoading] = useState(false)
  const [fetchingData, setFetchingData] = useState(true)
  const [isTopik, setIsTopik] = useState(false)

  const [formData, setFormData] = useState({
    judul: '',
    pesan: '',
    file_lampiran: ''
  })

  const [errors, setErrors] = useState({})

  useEffect(() => {
    if (!id) {
      navigate('/akademik/forum')
      return
    }
    fetchForum()
  }, [id])

  const fetchForum = async () => {
    setFetchingData(true)
    const { data, error } = await forumService.getById(id)
    if (data) {
      const forum = data.data
      setIsTopik(!!forum.is_topik)
      setFormData({
        judul: forum.judul || '',
        pesan: forum.pesan || '',
        file_lampiran: forum.file_lampiran || ''
      })
    } else {
      showError('Gagal mengambil data forum')
      navigate('/akademik/forum')
    }
    setFetchingData(false)
  }

  const handleChange = (e) => {
    const { name, value } = e.target
    setFormData(prev => ({ ...prev, [name]: value }))
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: null }))
    }
  }

  const validate = () => {
    const newErrors = {}
    if (!formData.pesan.trim() && !formData.pesan.replace(/<[^>]*>/g, '').trim()) {
      newErrors.pesan = 'Pesan wajib diisi'
    }
    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    if (!validate()) return

    setLoading(true)

    const submitData = {
      pesan: formData.pesan,
      file_lampiran: formData.file_lampiran || null
    }

    if (isTopik) {
      submitData.judul = formData.judul || null
    }

    const { error } = await forumService.update(id, submitData)

    if (!error) {
      showSuccess('Berhasil diperbarui!')
      navigate(-1)
    } else {
      if (error.errors) {
        setErrors(error.errors)
      } else {
        showError('Gagal memperbarui')
      }
    }
    setLoading(false)
  }

  return (
    <div className="space-y-6 max-w-3xl mx-auto">
      <div className="flex items-center gap-4">
        <Button variant="secondary" onClick={() => navigate(-1)}>
          <ArrowLeft size={18} className="mr-2" />
          Kembali
        </Button>
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
          Edit {isTopik ? 'Topik' : 'Balasan'}
        </h1>
      </div>

      <Card>
        {fetchingData ? (
          <div className="flex items-center justify-center h-64">
            <div className="animate-spin rounded-full h-10 w-10 border-b-2 border-primary-600"></div>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="p-6 space-y-6">
            {isTopik && (
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Judul
                </label>
                <Input
                  type="text"
                  name="judul"
                  value={formData.judul}
                  onChange={handleChange}
                  placeholder="Judul topik"
                  error={errors.judul}
                />
              </div>
            )}

            <div>
              <LexicalEditor
                label="Pesan"
                required
                value={formData.pesan}
                onChange={(html) => setFormData(prev => ({ ...prev, pesan: html }))}
                placeholder="Tulis pesan..."
                minHeight="150px"
              />
              {errors.pesan && (
                <p className="mt-1 text-sm text-red-500">{errors.pesan}</p>
              )}
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                File Lampiran
              </label>
              <Input
                type="text"
                name="file_lampiran"
                value={formData.file_lampiran}
                onChange={handleChange}
                placeholder="Path file lampiran (opsional)"
                error={errors.file_lampiran}
              />
            </div>

            <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
              <Button type="button" variant="secondary" onClick={() => navigate(-1)}>
                Batal
              </Button>
              <Button type="submit" disabled={loading}>
                <Save size={18} className="mr-2" />
                {loading ? 'Menyimpan...' : 'Simpan'}
              </Button>
            </div>
          </form>
        )}
      </Card>
    </div>
  )
}

export default ForumForm

import { useCallback, useEffect, useState } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ArrowLeft, Save } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import Input from '../../../components/ui/Input'
import SearchableSelect from '../../../components/ui/SearchableSelect'
import { jadwalPelajaranService } from '../services/jadwalPelajaranService'
import { kelasService } from '../../kelas/services/kelasService'
import { showSuccess, showError } from '../../../utils/sweetalert'

const HARI_OPTIONS = [
  { value: 'MON', label: 'Senin' },
  { value: 'TUE', label: 'Selasa' },
  { value: 'WED', label: 'Rabu' },
  { value: 'THU', label: 'Kamis' },
  { value: 'FRI', label: 'Jumat' },
  { value: 'SAT', label: 'Sabtu' },
]

const JadwalPelajaranForm = () => {
  const { id } = useParams()
  const navigate = useNavigate()
  const isEditMode = !!id

  const [loading, setLoading] = useState(false)
  const [fetchingData, setFetchingData] = useState(false)
  
  const [formData, setFormData] = useState({
    mst_kelas_id: '',
    mst_guru_mapel_id: '',
    hari: '',
    jam_mulai: '',
    jam_selesai: '',
    ruangan: ''
  })

  const [errors, setErrors] = useState({})
  const [kelasOptions, setKelasOptions] = useState([])
  const [selectedGuruMapelOption, setSelectedGuruMapelOption] = useState(null)

  useEffect(() => {
    fetchKelas()
    if (isEditMode) {
      fetchJadwal()
    }
  }, [id])

  const fetchKelas = async () => {
    const { data, error } = await kelasService.getAll({ per_page: 100 })
    if (data && data.data) {
      const options = data.data.map(kelas => ({
        value: String(kelas.id),
        label: `${kelas.nama_kelas} (Tingkat ${kelas.tingkat})`
      }))
      setKelasOptions(options)
    } else {
      console.error('Failed to fetch kelas:', error)
    }
  }

  const buildGuruMapelOption = useCallback((guruMapel) => {
    if (!guruMapel) return null

    const guruNama = guruMapel.guru?.nama || guruMapel.nama_guru || 'Guru'
    const mapelNama = guruMapel.mapel?.nama || guruMapel.mapel?.nama_mapel || guruMapel.nama_mapel || 'Mapel'
    const rawId = guruMapel.id ?? guruMapel.mst_guru_mapel_id

    if (!rawId) return null

    return {
      value: String(rawId),
      label: `${guruNama} - ${mapelNama}`
    }
  }, [])

  const searchGuruMapelOptions = useCallback(async (keyword = '') => {
    const normalizedKeyword = keyword.trim()

    const { data, error } = await jadwalPelajaranService.getAll({
      search: normalizedKeyword || undefined,
      per_page: 20
    })

    if (data?.data) {
      const seenIds = new Set()
      return data.data.reduce((options, jadwal) => {
        const option = buildGuruMapelOption(jadwal.guru_mapel)
        if (!option || seenIds.has(option.value)) return options

        const label = option.label.toLowerCase()
        if (normalizedKeyword && !label.includes(normalizedKeyword.toLowerCase())) {
          return options
        }

        seenIds.add(option.value)
        options.push(option)
        return options
      }, [])
    }

    console.error('Failed to fetch guru mapel options:', error)
    return []
  }, [buildGuruMapelOption])

  const hydrateSelectedGuruMapelOption = useCallback(async (guruMapelId) => {
    if (!guruMapelId) {
      setSelectedGuruMapelOption(null)
      return
    }

    const { data } = await jadwalPelajaranService.getAll({ per_page: 20 })
    const jadwalList = data?.data || []
    const matchedJadwal = jadwalList.find(
      (jadwal) => String(jadwal.guru_mapel?.id) === String(guruMapelId)
    )

    const option = buildGuruMapelOption(matchedJadwal?.guru_mapel)

    if (option) {
      setSelectedGuruMapelOption(option)
      return
    }

    setSelectedGuruMapelOption({
      value: String(guruMapelId),
      label: `Guru Mapel #${guruMapelId}`
    })
  }, [buildGuruMapelOption])

  const fetchJadwal = async () => {
    setFetchingData(true)
    const { data, error } = await jadwalPelajaranService.getById(id)
    if (data) {
      const jadwal = data.data
      const guruMapelId = jadwal.guru_mapel?.id ? String(jadwal.guru_mapel.id) : ''

      setFormData({
        mst_kelas_id: jadwal.kelas?.id ? String(jadwal.kelas.id) : '',
        mst_guru_mapel_id: guruMapelId,
        hari: jadwal.hari || '',
        jam_mulai: jadwal.jam_mulai || '',
        jam_selesai: jadwal.jam_selesai || '',
        ruangan: jadwal.ruangan || ''
      })

      if (jadwal.guru_mapel) {
        const option = buildGuruMapelOption(jadwal.guru_mapel)
        if (option) {
          setSelectedGuruMapelOption(option)
        }
      }
    } else {
      showError('Gagal mengambil data jadwal pelajaran')
      navigate('/jadwal-pelajaran')
    }
    setFetchingData(false)
  }

  useEffect(() => {
    if (formData.mst_guru_mapel_id) {
      hydrateSelectedGuruMapelOption(formData.mst_guru_mapel_id)
    } else {
      setSelectedGuruMapelOption(null)
    }
  }, [formData.mst_guru_mapel_id, hydrateSelectedGuruMapelOption])

  const handleChange = (e) => {
    const { name, value } = e.target
    setFormData(prev => ({ ...prev, [name]: value }))
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: null }))
    }
  }

  const validate = () => {
    const newErrors = {}
    if (!formData.mst_kelas_id) newErrors.mst_kelas_id = 'Kelas wajib dipilih'
    if (!formData.mst_guru_mapel_id) newErrors.mst_guru_mapel_id = 'Guru Mapel wajib dipilih'
    if (!formData.hari) newErrors.hari = 'Hari wajib dipilih'
    if (!formData.jam_mulai) newErrors.jam_mulai = 'Jam mulai wajib diisi'
    if (!formData.jam_selesai) newErrors.jam_selesai = 'Jam selesai wajib diisi'
    
    if (formData.jam_mulai && formData.jam_selesai && formData.jam_mulai >= formData.jam_selesai) {
      newErrors.jam_selesai = 'Jam selesai harus setelah jam mulai'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    
    if (!validate()) return

    setLoading(true)
    
    const submitData = {
      mst_kelas_id: parseInt(formData.mst_kelas_id),
      mst_guru_mapel_id: parseInt(formData.mst_guru_mapel_id),
      hari: formData.hari,
      jam_mulai: formData.jam_mulai,
      jam_selesai: formData.jam_selesai,
      ruangan: formData.ruangan || null
    }

    let result
    
    if (isEditMode) {
      result = await jadwalPelajaranService.update(id, submitData)
    } else {
      result = await jadwalPelajaranService.create(submitData)
    }

    const { error } = result

    if (!error) {
      showSuccess(`Jadwal pelajaran berhasil ${isEditMode ? 'diperbarui' : 'ditambahkan'}!`)
      navigate('/jadwal-pelajaran')
    } else {
      console.error(error)
      if (error.errors) {
        setErrors(error.errors)
      } else {
        showError(`Gagal ${isEditMode ? 'memperbarui' : 'menambahkan'} jadwal pelajaran`)
      }
    }
    setLoading(false)
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="secondary" onClick={() => navigate('/jadwal-pelajaran')}>
          <ArrowLeft size={18} className="mr-2" />
          Kembali
        </Button>
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
          {isEditMode ? 'Edit Jadwal Pelajaran' : 'Tambah Jadwal Pelajaran Baru'}
        </h1>
      </div>

      <Card>
        {fetchingData ? (
          <div className="flex items-center justify-center h-64">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="p-6 space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Kelas */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Kelas <span className="text-red-500">*</span>
                </label>
                <SearchableSelect
                  name="mst_kelas_id"
                  value={formData.mst_kelas_id}
                  onChange={handleChange}
                  options={kelasOptions}
                  placeholder="Pilih kelas"
                  error={errors.mst_kelas_id}
                />
              </div>

              {/* Hari */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Hari <span className="text-red-500">*</span>
                </label>
                <SearchableSelect
                  name="hari"
                  value={formData.hari}
                  onChange={handleChange}
                  options={HARI_OPTIONS}
                  placeholder="Pilih hari"
                  error={errors.hari}
                />
              </div>

              {/* Jam Mulai */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Jam Mulai <span className="text-red-500">*</span>
                </label>
                <Input
                  type="time"
                  name="jam_mulai"
                  value={formData.jam_mulai}
                  onChange={handleChange}
                  error={errors.jam_mulai}
                />
              </div>

              {/* Jam Selesai */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Jam Selesai <span className="text-red-500">*</span>
                </label>
                <Input
                  type="time"
                  name="jam_selesai"
                  value={formData.jam_selesai}
                  onChange={handleChange}
                  error={errors.jam_selesai}
                />
              </div>

              {/* Guru Mapel */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Guru & Mata Pelajaran <span className="text-red-500">*</span>
                </label>
                <SearchableSelect
                  name="mst_guru_mapel_id"
                  value={formData.mst_guru_mapel_id}
                  onChange={handleChange}
                  options={selectedGuruMapelOption ? [selectedGuruMapelOption] : []}
                  loadOptions={searchGuruMapelOptions}
                  placeholder="Pilih guru & mata pelajaran"
                  searchPlaceholder="Cari guru mapel berdasarkan guru atau mapel..."
                  noOptionsText="Tidak ada guru mapel yang cocok"
                  error={errors.mst_guru_mapel_id}
                />
              </div>

              {/* Ruangan */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Ruangan
                </label>
                <Input
                  type="text"
                  name="ruangan"
                  value={formData.ruangan}
                  onChange={handleChange}
                  placeholder="Masukkan ruangan (opsional)"
                  error={errors.ruangan}
                />
              </div>
            </div>

            <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
              <Button type="button" variant="secondary" onClick={() => navigate('/jadwal-pelajaran')}>
                Batal
              </Button>
              <Button type="submit" disabled={loading}>
                <Save size={18} className="mr-2" />
                {loading ? 'Menyimpan...' : 'Simpan'}
              </Button>
            </div>
          </form>
        )}
      </Card>
    </div>
  )
}

export default JadwalPelajaranForm

import { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ArrowLeft, Save } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import Input from '../../../components/ui/Input'
import SearchableSelect from '../../../components/ui/SearchableSelect'
import { kalenderAkademikService } from '../services/kalenderAkademikService'
import { tahunAjaranService } from '../../tahun-ajaran/services/tahunAjaranService'
import { semesterService } from '../../semester/services/semesterService'
import { showSuccess, showError } from '../../../utils/sweetalert'

const VISIBILITY_OPTIONS = [
  { value: 'GLOBAL', label: 'Global' },
  { value: 'ROLE', label: 'Role' },
  { value: 'KELAS', label: 'Kelas' },
  { value: 'JURUSAN', label: 'Jurusan' },
  { value: 'CUSTOM', label: 'Custom' },
]

const STATUS_OPTIONS = [
  { value: 'DRAFT', label: 'Draft' },
  { value: 'PENDING', label: 'Pending' },
  { value: 'APPROVED', label: 'Approved' },
  { value: 'REJECTED', label: 'Rejected' },
]

const KalenderAkademikForm = () => {
  const { id } = useParams()
  const navigate = useNavigate()
  const isEditMode = !!id

  const [loading, setLoading] = useState(false)
  const [fetchingData, setFetchingData] = useState(false)

  const [formData, setFormData] = useState({
    tahun_ajaran_id: '',
    semester_id: '',
    tipe_id: '',
    judul: '',
    deskripsi: '',
    tanggal_mulai: '',
    tanggal_selesai: '',
    is_all_day: true,
    is_recurring: false,
    recurring_rule: '',
    lokasi: '',
    visibility: 'GLOBAL',
    status: 'DRAFT',
  })

  const [errors, setErrors] = useState({})
  const [tahunAjaranOptions, setTahunAjaranOptions] = useState([])
  const [semesterOptions, setSemesterOptions] = useState([])
  const [tipeOptions, setTipeOptions] = useState([])

  useEffect(() => {
    fetchDropdownOptions()
    if (isEditMode) {
      fetchKalender()
    }
  }, [id])

  const fetchDropdownOptions = async () => {
    const [tahunResult, semesterResult, tipeResult] = await Promise.all([
      tahunAjaranService.getAll({ per_page: 100 }),
      semesterService.getAll({ per_page: 100 }),
      kalenderAkademikService.getAllTipe({ per_page: 100 })
    ])

    if (tahunResult.data) {
      const list = tahunResult.data?.data || []
      setTahunAjaranOptions(list.map(item => ({
        value: String(item.id),
        label: item.nama || item.tahun_ajaran || `Tahun Ajaran #${item.id}`
      })))
    }

    if (semesterResult.data) {
      const list = semesterResult.data?.data || []
      setSemesterOptions(list.map(item => ({
        value: String(item.id),
        label: item.nama || item.semester || `Semester #${item.id}`
      })))
    }

    if (tipeResult.data) {
      const list = tipeResult.data?.data || []
      setTipeOptions(list.map(item => ({
        value: String(item.id),
        label: item.nama || item.kode || `Tipe #${item.id}`
      })))
    }
  }

  const fetchKalender = async () => {
    setFetchingData(true)
    const { data, error } = await kalenderAkademikService.getById(id)
    if (data) {
      const kalender = data.data
      const formatDateForInput = (dateStr) => {
        if (!dateStr) return ''
        const date = new Date(dateStr)
        return date.toISOString().split('T')[0]
      }

      setFormData({
        tahun_ajaran_id: kalender.tahun_ajaran_id ? String(kalender.tahun_ajaran_id) : '',
        semester_id: kalender.semester_id ? String(kalender.semester_id) : '',
        tipe_id: kalender.tipe_id ? String(kalender.tipe_id) : '',
        judul: kalender.judul || '',
        deskripsi: kalender.deskripsi || '',
        tanggal_mulai: formatDateForInput(kalender.tanggal_mulai),
        tanggal_selesai: formatDateForInput(kalender.tanggal_selesai),
        is_all_day: kalender.is_all_day ?? true,
        is_recurring: kalender.is_recurring ?? false,
        recurring_rule: kalender.recurring_rule || '',
        lokasi: kalender.lokasi || '',
        visibility: kalender.visibility || 'GLOBAL',
        status: kalender.status || 'DRAFT',
      })
    } else {
      showError('Gagal mengambil data kalender akademik')
      navigate('/admin/kalender-akademik')
    }
    setFetchingData(false)
  }

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }))
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: null }))
    }
  }

  const validate = () => {
    const newErrors = {}
    if (!formData.judul.trim()) newErrors.judul = 'Judul wajib diisi'
    if (!formData.tahun_ajaran_id) newErrors.tahun_ajaran_id = 'Tahun Ajaran wajib dipilih'
    if (!formData.tipe_id) newErrors.tipe_id = 'Tipe wajib dipilih'
    if (!formData.tanggal_mulai) newErrors.tanggal_mulai = 'Tanggal mulai wajib diisi'
    if (!formData.tanggal_selesai) newErrors.tanggal_selesai = 'Tanggal selesai wajib diisi'
    if (formData.tanggal_mulai && formData.tanggal_selesai && formData.tanggal_selesai < formData.tanggal_mulai) {
      newErrors.tanggal_selesai = 'Tanggal selesai harus setelah tanggal mulai'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e) => {
    e.preventDefault()

    if (!validate()) return

    setLoading(true)

    const submitData = {
      tahun_ajaran_id: parseInt(formData.tahun_ajaran_id),
      semester_id: formData.semester_id ? parseInt(formData.semester_id) : null,
      tipe_id: parseInt(formData.tipe_id),
      judul: formData.judul,
      deskripsi: formData.deskripsi || null,
      tanggal_mulai: formData.tanggal_mulai,
      tanggal_selesai: formData.tanggal_selesai,
      is_all_day: formData.is_all_day,
      is_recurring: formData.is_recurring,
      recurring_rule: formData.recurring_rule || null,
      lokasi: formData.lokasi || null,
      visibility: formData.visibility,
    }

    // Include status only on update
    if (isEditMode) {
      submitData.status = formData.status
    }

    let result

    if (isEditMode) {
      result = await kalenderAkademikService.update(id, submitData)
    } else {
      result = await kalenderAkademikService.create(submitData)
    }

    const { error } = result

    if (!error) {
      showSuccess(`Kalender akademik berhasil ${isEditMode ? 'diperbarui' : 'ditambahkan'}!`)
      navigate('/admin/kalender-akademik')
    } else {
      console.error(error)
      if (error.errors) {
        setErrors(error.errors)
      } else {
        showError(`Gagal ${isEditMode ? 'memperbarui' : 'menambahkan'} kalender akademik`)
      }
    }
    setLoading(false)
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="secondary" onClick={() => navigate('/admin/kalender-akademik')}>
          <ArrowLeft size={18} className="mr-2" />
          Kembali
        </Button>
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
          {isEditMode ? 'Edit Kalender Akademik' : 'Tambah Event Baru'}
        </h1>
      </div>

      <Card>
        {fetchingData ? (
          <div className="flex items-center justify-center h-64">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="p-6 space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Judul */}
              <div className="md:col-span-2">
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Judul <span className="text-red-500">*</span>
                </label>
                <Input
                  type="text"
                  name="judul"
                  value={formData.judul}
                  onChange={handleChange}
                  placeholder="Masukkan judul event"
                  error={errors.judul}
                />
              </div>

              {/* Tahun Ajaran */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Tahun Ajaran <span className="text-red-500">*</span>
                </label>
                <SearchableSelect
                  name="tahun_ajaran_id"
                  value={formData.tahun_ajaran_id}
                  onChange={handleChange}
                  options={tahunAjaranOptions}
                  placeholder="Pilih tahun ajaran"
                  error={errors.tahun_ajaran_id}
                />
              </div>

              {/* Semester */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Semester
                </label>
                <SearchableSelect
                  name="semester_id"
                  value={formData.semester_id}
                  onChange={handleChange}
                  options={semesterOptions}
                  placeholder="Pilih semester (opsional)"
                  error={errors.semester_id}
                />
              </div>

              {/* Tipe */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Tipe <span className="text-red-500">*</span>
                </label>
                <SearchableSelect
                  name="tipe_id"
                  value={formData.tipe_id}
                  onChange={handleChange}
                  options={tipeOptions}
                  placeholder="Pilih tipe kalender"
                  error={errors.tipe_id}
                />
              </div>

              {/* Visibility */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Visibility
                </label>
                <SearchableSelect
                  name="visibility"
                  value={formData.visibility}
                  onChange={handleChange}
                  options={VISIBILITY_OPTIONS}
                  placeholder="Pilih visibility"
                  error={errors.visibility}
                />
              </div>

              {/* Tanggal Mulai */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Tanggal Mulai <span className="text-red-500">*</span>
                </label>
                <Input
                  type="date"
                  name="tanggal_mulai"
                  value={formData.tanggal_mulai}
                  onChange={handleChange}
                  error={errors.tanggal_mulai}
                />
              </div>

              {/* Tanggal Selesai */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Tanggal Selesai <span className="text-red-500">*</span>
                </label>
                <Input
                  type="date"
                  name="tanggal_selesai"
                  value={formData.tanggal_selesai}
                  onChange={handleChange}
                  error={errors.tanggal_selesai}
                />
              </div>

              {/* Lokasi */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Lokasi
                </label>
                <Input
                  type="text"
                  name="lokasi"
                  value={formData.lokasi}
                  onChange={handleChange}
                  placeholder="Lokasi event (opsional)"
                  error={errors.lokasi}
                />
              </div>

              {/* Status (only on edit) */}
              {isEditMode && (
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Status
                  </label>
                  <SearchableSelect
                    name="status"
                    value={formData.status}
                    onChange={handleChange}
                    options={STATUS_OPTIONS}
                    placeholder="Pilih status"
                    error={errors.status}
                  />
                </div>
              )}

              {/* Checkboxes */}
              <div className="flex items-center gap-6">
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="checkbox"
                    name="is_all_day"
                    checked={formData.is_all_day}
                    onChange={handleChange}
                    className="w-4 h-4 text-primary-600 border-gray-300 rounded focus:ring-primary-500"
                  />
                  <span className="text-sm text-gray-700 dark:text-gray-300">Sepanjang Hari</span>
                </label>
                <label className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="checkbox"
                    name="is_recurring"
                    checked={formData.is_recurring}
                    onChange={handleChange}
                    className="w-4 h-4 text-primary-600 border-gray-300 rounded focus:ring-primary-500"
                  />
                  <span className="text-sm text-gray-700 dark:text-gray-300">Berulang</span>
                </label>
              </div>

              {/* Recurring Rule (shown only if is_recurring) */}
              {formData.is_recurring && (
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Aturan Pengulangan
                  </label>
                  <Input
                    type="text"
                    name="recurring_rule"
                    value={formData.recurring_rule}
                    onChange={handleChange}
                    placeholder="Contoh: FREQ=WEEKLY;BYDAY=MO"
                    error={errors.recurring_rule}
                  />
                </div>
              )}

              {/* Deskripsi */}
              <div className="md:col-span-2">
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Deskripsi
                </label>
                <textarea
                  name="deskripsi"
                  value={formData.deskripsi}
                  onChange={handleChange}
                  placeholder="Masukkan deskripsi event"
                  rows={4}
                  className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white focus:ring-2 focus:ring-primary-500 focus:outline-none resize-y"
                />
                {errors.deskripsi && (
                  <p className="mt-1 text-sm text-red-500">{errors.deskripsi}</p>
                )}
              </div>
            </div>

            <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
              <Button type="button" variant="secondary" onClick={() => navigate('/admin/kalender-akademik')}>
                Batal
              </Button>
              <Button type="submit" disabled={loading}>
                <Save size={18} className="mr-2" />
                {loading ? 'Menyimpan...' : 'Simpan'}
              </Button>
            </div>
          </form>
        )}
      </Card>
    </div>
  )
}

export default KalenderAkademikForm

import { useState, useEffect } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import { Save, ArrowLeft } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import Input from '../../../components/ui/Input'
import { kalenderTipeService } from '../services/kalenderTipeService'
import { showSuccess, showError } from '../../../utils/sweetalert'

const KalenderTipeForm = () => {
  const navigate = useNavigate()
  const { id } = useParams()
  const isEdit = Boolean(id)

  const [formData, setFormData] = useState({
    kode: '',
    nama: '',
    warna: '#3b82f6',
    keterangan: '',
    is_libur: false,
    is_ujian: false,
    is_penting: false,
  })
  const [loading, setLoading] = useState(false)
  const [saving, setSaving] = useState(false)
  const [errors, setErrors] = useState({})

  useEffect(() => {
    if (isEdit) fetchData()
  }, [id])

  const fetchData = async () => {
    setLoading(true)
    // No show endpoint, fetch from list and find by id
    const { data, error } = await kalenderTipeService.getAll({ per_page: 999 })
    if (data?.data) {
      const item = data.data.find(t => String(t.id) === String(id))
      if (item) {
        setFormData({
          kode: item.kode || '',
          nama: item.nama || '',
          warna: item.warna || '#3b82f6',
          keterangan: item.keterangan || '',
          is_libur: Boolean(item.is_libur),
          is_ujian: Boolean(item.is_ujian),
          is_penting: Boolean(item.is_penting),
        })
      } else {
        showError('Data tidak ditemukan')
        navigate('/admin/kalender-tipe')
      }
    } else {
      showError('Gagal mengambil data')
      navigate('/admin/kalender-tipe')
    }
    setLoading(false)
  }

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target
    setFormData(prev => ({ ...prev, [name]: type === 'checkbox' ? checked : value }))
    if (errors[name]) setErrors(prev => ({ ...prev, [name]: null }))
  }

  const validate = () => {
    const errs = {}
    if (!formData.kode.trim()) errs.kode = 'Kode wajib diisi'
    if (!formData.nama.trim()) errs.nama = 'Nama wajib diisi'
    setErrors(errs)
    return Object.keys(errs).length === 0
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    if (!validate()) return
    setSaving(true)
    const payload = { ...formData }
    const { data, error } = isEdit
      ? await kalenderTipeService.update(id, payload)
      : await kalenderTipeService.create(payload)
    if (data) {
      showSuccess(`Tipe kalender berhasil ${isEdit ? 'diperbarui' : 'ditambahkan'}!`)
      navigate('/admin/kalender-tipe')
    } else {
      if (error?.errors) setErrors(error.errors)
      else showError(error?.message || 'Gagal menyimpan data')
    }
    setSaving(false)
  }

  if (loading) {
    return <div className="flex items-center justify-center h-64"><div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div></div>
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="secondary" onClick={() => navigate('/admin/kalender-tipe')}><ArrowLeft size={18} /></Button>
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">{isEdit ? 'Edit' : 'Tambah'} Tipe Kalender</h1>
      </div>
      <Card>
        <form onSubmit={handleSubmit} className="p-6 space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <Input label="Kode *" name="kode" value={formData.kode} onChange={handleChange} error={errors.kode} placeholder="Contoh: LIBUR" disabled={isEdit} />
            <Input label="Nama *" name="nama" value={formData.nama} onChange={handleChange} error={errors.nama} placeholder="Contoh: Hari Libur" />
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Warna</label>
              <div className="flex items-center gap-3">
                <input type="color" name="warna" value={formData.warna} onChange={handleChange}
                  className="w-12 h-10 rounded border border-gray-300 dark:border-gray-600 cursor-pointer" />
                <input type="text" name="warna" value={formData.warna} onChange={handleChange}
                  className="flex-1 px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-sm" placeholder="#3b82f6" />
              </div>
            </div>
            <Input label="Keterangan" name="keterangan" value={formData.keterangan} onChange={handleChange} placeholder="Keterangan tambahan" />
          </div>
          <div className="flex flex-wrap gap-6">
            <label className="flex items-center gap-2 cursor-pointer">
              <input type="checkbox" name="is_libur" checked={formData.is_libur} onChange={handleChange}
                className="w-4 h-4 text-primary-600 border-gray-300 rounded focus:ring-primary-500" />
              <span className="text-sm text-gray-700 dark:text-gray-300">Hari Libur</span>
            </label>
            <label className="flex items-center gap-2 cursor-pointer">
              <input type="checkbox" name="is_ujian" checked={formData.is_ujian} onChange={handleChange}
                className="w-4 h-4 text-primary-600 border-gray-300 rounded focus:ring-primary-500" />
              <span className="text-sm text-gray-700 dark:text-gray-300">Ujian</span>
            </label>
            <label className="flex items-center gap-2 cursor-pointer">
              <input type="checkbox" name="is_penting" checked={formData.is_penting} onChange={handleChange}
                className="w-4 h-4 text-primary-600 border-gray-300 rounded focus:ring-primary-500" />
              <span className="text-sm text-gray-700 dark:text-gray-300">Penting</span>
            </label>
          </div>
          <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
            <Button type="button" variant="secondary" onClick={() => navigate('/admin/kalender-tipe')}>Batal</Button>
            <Button type="submit" disabled={saving}><Save size={18} className="mr-2" />{saving ? 'Menyimpan...' : 'Simpan'}</Button>
          </div>
        </form>
      </Card>
    </div>
  )
}

export default KalenderTipeForm

import { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ArrowLeft, Edit, Trash2, Users, BookOpen, Calendar } from 'lucide-react'
import { AgGridReact } from 'ag-grid-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import { kelasService } from '../services/kelasService'
import { showDeleteConfirm, showSuccess, showError } from '../../../utils/sweetalert'

const KelasDetail = () => {
  const { id } = useParams()
  const navigate = useNavigate()

  const [loading, setLoading] = useState(false)
  const [kelas, setKelas] = useState(null)
  const [siswaList, setSiswaList] = useState([])
  const [loadingSiswa, setLoadingSiswa] = useState(false)
  const [siswaError, setSiswaError] = useState(null)

  useEffect(() => {
    fetchKelas()
  }, [id])

  const fetchKelas = async () => {
    setLoading(true)
    const { data, error } = await kelasService.getById(id)
    if (data) {
      // Handle nested response: data.kelas or data directly
      setKelas(data.data?.kelas || data.data)
      fetchSiswa()
    } else {
      showError('Gagal mengambil data kelas')
      navigate('/kelas')
    }
    setLoading(false)
  }

  const fetchSiswa = async () => {
    setLoadingSiswa(true)
    setSiswaError(null)
    const { data, error } = await kelasService.getSiswaByKelasId(id)
    if (error) {
      setSiswaError('Gagal mengambil data siswa')
      setSiswaList([])
    } else if (data) {
      // Handle nested response: data.data.siswa, data.siswa, or data.data array
      const siswaData = data.data?.siswa || data.siswa || data.data || []
      setSiswaList(Array.isArray(siswaData) ? siswaData : [])
    }
    setLoadingSiswa(false)
  }

  const handleDelete = async () => {
    const result = await showDeleteConfirm(kelas.nama_kelas)
    if (result.isConfirmed) {
      const { error } = await kelasService.delete(kelas.id)
      if (!error) {
        showSuccess(`${kelas.nama_kelas} berhasil dihapus!`)
        navigate('/kelas')
      } else {
        showError('Gagal menghapus kelas')
      }
    }
  }

  const getTingkatColor = (tingkat) => {
    switch (tingkat) {
      case 10: return 'bg-green-100 text-green-800'
      case 11: return 'bg-yellow-100 text-yellow-800'
      case 12: return 'bg-red-100 text-red-800'
      default: return 'bg-blue-100 text-blue-800'
    }
  }

  const siswaColumnDefs = [
    { field: 'nis', headerName: 'NIS', sortable: true, filter: true, width: 120 },
    { field: 'nama', headerName: 'Nama', sortable: true, filter: true, flex: 1 },
    {
      field: 'jenis_kelamin',
      headerName: 'Jenis Kelamin',
      sortable: true,
      filter: true,
      width: 140,
      cellRenderer: (params) => {
        const jk = params.value
        if (jk === 'L' || jk === 'laki-laki' || jk === 'Laki-laki') return 'Laki-laki'
        if (jk === 'P' || jk === 'perempuan' || jk === 'Perempuan') return 'Perempuan'
        return jk || '-'
      }
    },
    {
      field: 'status',
      headerName: 'Status',
      sortable: true,
      filter: true,
      width: 120,
      cellRenderer: (params) => {
        const rawStatus = params.value ?? params.data?.status_siswa
        let colorClass = 'bg-gray-100 text-gray-800'
        let displayStatus = 'Tidak diketahui'

        // Handle numeric status (1 = aktif, 0 = non-aktif/tidak aktif)
        if (rawStatus === 1 || rawStatus === '1' || rawStatus === 'aktif') {
          displayStatus = 'Aktif'
          colorClass = 'bg-green-100 text-green-800'
        } else if (rawStatus === 0 || rawStatus === '0' || rawStatus === 'non-aktif' || rawStatus === 'tidak aktif') {
          displayStatus = 'Tidak Aktif'
          colorClass = 'bg-red-100 text-red-800'
        } else if (rawStatus === 'lulus') {
          displayStatus = 'Lulus'
          colorClass = 'bg-blue-100 text-blue-800'
        } else if (rawStatus === 'keluar') {
          displayStatus = 'Keluar'
          colorClass = 'bg-red-100 text-red-800'
        } else if (rawStatus === 'pindah') {
          displayStatus = 'Pindah'
          colorClass = 'bg-yellow-100 text-yellow-800'
        } else if (rawStatus !== undefined && rawStatus !== null) {
          displayStatus = String(rawStatus)
        }

        return (
          <span className={`px-2 py-1 rounded-full text-xs font-medium ${colorClass}`}>
            {displayStatus}
          </span>
        )
      }
    }
  ]

  if (loading || !kelas) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
        <div className="flex items-center gap-4">
          <Button variant="secondary" onClick={() => navigate('/kelas')}>
            <ArrowLeft size={18} className="mr-2" />
            Kembali
          </Button>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Detail Kelas</h1>
        </div>
        <div className="flex gap-3">
          <Button variant="warning" onClick={() => navigate(`/kelas/${id}/edit`)}>
            <Edit size={18} className="mr-2" />
            Edit
          </Button>
          <Button variant="danger" onClick={handleDelete}>
            <Trash2 size={18} className="mr-2" />
            Hapus
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        {/* Info Card */}
        <div className="md:col-span-1">
          <Card>
            <div className="p-6">
              <div className="text-center mb-6">
                <div className="w-20 h-20 bg-primary-100 dark:bg-primary-900/30 rounded-full mx-auto mb-4 flex items-center justify-center">
                  <BookOpen size={40} className="text-primary-600" />
                </div>
                <h2 className="text-xl font-bold text-gray-900 dark:text-white">{kelas.nama_kelas}</h2>
                <span className={`inline-flex items-center px-3 py-1 rounded-full text-sm font-medium mt-2 ${getTingkatColor(kelas.tingkat)}`}>
                  Kelas {kelas.tingkat}
                </span>
              </div>

              <div className="border-t border-gray-200 dark:border-gray-700 pt-4 space-y-3">
                <div className="flex items-center gap-3">
                  <Calendar size={18} className="text-gray-400" />
                  <div>
                    <p className="text-xs text-gray-500 dark:text-gray-400">Tahun Ajaran</p>
                    <p className="font-medium text-gray-900 dark:text-white">{kelas.tahun_ajaran}</p>
                  </div>
                </div>
                <div className="flex items-center gap-3">
                  <Users size={18} className="text-gray-400" />
                  <div>
                    <p className="text-xs text-gray-500 dark:text-gray-400">Jumlah Siswa</p>
                    <p className="font-medium text-gray-900 dark:text-white">
                      {kelas.jumlah_siswa || 0}
                      {kelas.kapasitas && <span className="text-gray-400 text-sm"> / {kelas.kapasitas}</span>}
                    </p>
                  </div>
                </div>
                <div className="flex items-center gap-3">
                  <Users size={18} className="text-gray-400" />
                  <div>
                    <p className="text-xs text-gray-500 dark:text-gray-400">Wali Kelas</p>
                    <p className="font-medium text-gray-900 dark:text-white">
                      {kelas.wali_guru?.nama || '-'}
                    </p>
                  </div>
                </div>
              </div>
            </div>
          </Card>
        </div>

        {/* Siswa List */}
        <div className="md:col-span-3">
          <Card>
            <div className="p-4 border-b border-gray-200 dark:border-gray-700">
              <h3 className="text-lg font-semibold text-gray-900 dark:text-white flex items-center gap-2">
                <Users size={20} />
                Daftar Siswa
              </h3>
            </div>
            <div className="p-4">
              {loadingSiswa ? (
                <div className="flex items-center justify-center h-48">
                  <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary-600"></div>
                </div>
              ) : siswaError ? (
                <div className="text-center py-12">
                  <div className="text-red-500 mb-2">
                    <Users size={48} className="mx-auto text-red-300" />
                  </div>
                  <p className="text-red-600 font-medium">{siswaError}</p>
                  <Button
                    variant="secondary"
                    className="mt-4"
                    onClick={fetchSiswa}
                  >
                    Coba Lagi
                  </Button>
                </div>
              ) : siswaList.length > 0 ? (
                <div className="ag-theme-alpine dark:ag-theme-alpine-dark w-full" style={{ height: 400 }}>
                  <AgGridReact
                    rowData={siswaList}
                    columnDefs={siswaColumnDefs}
                    defaultColDef={{ resizable: true, sortable: true, filter: true }}
                    pagination={true}
                    paginationPageSize={10}
                    animateRows={true}
                   />
                </div>
              ) : (
                <div className="text-center py-12">
                  <Users size={48} className="mx-auto text-gray-300 mb-3" />
                  <p className="text-gray-500">Belum ada siswa di kelas ini</p>
                </div>
              )}
            </div>
          </Card>
        </div>
      </div>
    </div>
  )
}

export default KelasDetail

import { useState, useEffect, useRef } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ArrowLeft, Save, ChevronDown, X, Search } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import Input from '../../../components/ui/Input'
import { kelasService } from '../services/kelasService'
import { showSuccess, showError } from '../../../utils/sweetalert'
import api from '../../../utils/api'

const KelasForm = () => {
  const { id } = useParams()
  const navigate = useNavigate()
  const isEditMode = !!id

  const [loading, setLoading] = useState(false)
  const [fetchingData, setFetchingData] = useState(false)
  
  const [formData, setFormData] = useState({
    nama_kelas: '',
    tingkat: '',
    tahun_ajaran: '',
    kapasitas: '',
    wali_guru_id: ''
  })

  const [errors, setErrors] = useState({})

  // Searchable select state for Wali Guru
  const [guruOptions, setGuruOptions] = useState([])
  const [guruLoading, setGuruLoading] = useState(false)
  const [guruSearch, setGuruSearch] = useState('')
  const [isGuruOpen, setIsGuruOpen] = useState(false)
  const [selectedGuru, setSelectedGuru] = useState(null)
  const guruDropdownRef = useRef(null)
  const guruSearchTimeoutRef = useRef(null)

  // Options for tingkat
  const tingkatOptions = [
    { value: 10, label: 'Kelas 10' },
    { value: 11, label: 'Kelas 11' },
    { value: 12, label: 'Kelas 12' }
  ]

  // Options for tahun ajaran - generate current year and next 2 years
  const tahunAjaranOptions = (() => {
    const currentYear = new Date().getFullYear()
    return [
      { value: `${currentYear}/${currentYear + 1}`, label: `${currentYear}/${currentYear + 1}` },
      { value: `${currentYear - 1}/${currentYear}`, label: `${currentYear - 1}/${currentYear}` },
      { value: `${currentYear + 1}/${currentYear + 2}`, label: `${currentYear + 1}/${currentYear + 2}` }
    ]
  })()

  useEffect(() => {
    if (isEditMode) {
      fetchKelas()
    }
    // Fetch guru list on mount
    fetchGuruList()
  }, [id])

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (guruDropdownRef.current && !guruDropdownRef.current.contains(event.target)) {
        setIsGuruOpen(false)
      }
    }

    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [])

  // Update selected guru when formData.wali_guru_id changes and guruOptions are loaded
  useEffect(() => {
    if (formData.wali_guru_id && guruOptions.length > 0) {
      const guru = guruOptions.find(g => g.id === parseInt(formData.wali_guru_id))
      if (guru) {
        setSelectedGuru(guru)
      }
    }
  }, [formData.wali_guru_id, guruOptions])

  // Debounced search for guru
  useEffect(() => {
    if (guruSearchTimeoutRef.current) {
      clearTimeout(guruSearchTimeoutRef.current)
    }

    guruSearchTimeoutRef.current = setTimeout(() => {
      if (isGuruOpen) {
        fetchGuruList(guruSearch)
      }
    }, 300)

    return () => {
      if (guruSearchTimeoutRef.current) {
        clearTimeout(guruSearchTimeoutRef.current)
      }
    }
  }, [guruSearch, isGuruOpen])

  const fetchGuruList = async (search = '') => {
    setGuruLoading(true)
    try {
      const params = search ? { search } : {}
      const response = await api.get('/guru/', { params })
      
      if (response.data.success) {
        setGuruOptions(response.data.data || [])
      }
    } catch (error) {
      console.error('Error fetching guru list:', error)
      showError('Gagal mengambil data guru')
    } finally {
      setGuruLoading(false)
    }
  }

  const fetchKelas = async () => {
    setFetchingData(true)
    const { data, error } = await kelasService.getById(id)
    if (data) {
      const kelas = data.data
      const waliGuruId = kelas.wali_guru?.id || ''
      setFormData({
        nama_kelas: kelas.nama_kelas || '',
        tingkat: kelas.tingkat || '',
        tahun_ajaran: kelas.tahun_ajaran || '',
        kapasitas: kelas.kapasitas || '',
        wali_guru_id: waliGuruId
      })
      // Set selectedGuru for the searchable dropdown display
      if (kelas.wali_guru) {
        setSelectedGuru(kelas.wali_guru)
      }
    } else {
      showError('Gagal mengambil data kelas')
      navigate('/kelas')
    }
    setFetchingData(false)
  }

  const handleChange = (e) => {
    const { name, value } = e.target
    setFormData(prev => ({ ...prev, [name]: value }))
    // Clear error when user types
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: null }))
    }
  }

  const handleWaliGuruChange = (guru) => {
    setSelectedGuru(guru)
    setFormData(prev => ({ ...prev, wali_guru_id: guru ? guru.id : '' }))
    setIsGuruOpen(false)
    setGuruSearch('')
    
    // Clear error
    if (errors.wali_guru_id) {
      setErrors(prev => ({ ...prev, wali_guru_id: null }))
    }
  }

  const handleClearGuru = (e) => {
    e.stopPropagation()
    setSelectedGuru(null)
    setFormData(prev => ({ ...prev, wali_guru_id: '' }))
    setGuruSearch('')
  }

  const validate = () => {
    const newErrors = {}
    if (!formData.nama_kelas) newErrors.nama_kelas = 'Nama kelas wajib diisi'
    if (!formData.tingkat) newErrors.tingkat = 'Tingkat wajib dipilih'
    if (!formData.tahun_ajaran) newErrors.tahun_ajaran = 'Tahun ajaran wajib dipilih'
    
    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    
    if (!validate()) return

    setLoading(true)
    
    // Prepare data - convert empty strings to null
    const submitData = {
      nama_kelas: formData.nama_kelas,
      tingkat: parseInt(formData.tingkat),
      tahun_ajaran: formData.tahun_ajaran,
      kapasitas: formData.kapasitas ? parseInt(formData.kapasitas) : null,
      wali_guru_id: formData.wali_guru_id ? parseInt(formData.wali_guru_id) : null
    }

    let result
    
    if (isEditMode) {
      result = await kelasService.update(id, submitData)
    } else {
      result = await kelasService.create(submitData)
    }

    const { error } = result

    if (!error) {
      showSuccess(`Kelas berhasil ${isEditMode ? 'diperbarui' : 'ditambahkan'}!`)
      navigate('/kelas')
    } else {
      console.error(error)
      // Handle server-side validation errors
      if (error.errors) {
        setErrors(error.errors)
      } else {
        showError(`Gagal ${isEditMode ? 'memperbarui' : 'menambahkan'} kelas`)
      }
    }
    setLoading(false)
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="secondary" onClick={() => navigate('/kelas')}>
          <ArrowLeft size={18} className="mr-2" />
          Kembali
        </Button>
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
          {isEditMode ? 'Edit Kelas' : 'Tambah Kelas Baru'}
        </h1>
      </div>

      <Card>
        {fetchingData ? (
          <div className="flex items-center justify-center h-64">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
          </div>
        ) : (
        <form onSubmit={handleSubmit} className="p-6 space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Nama Kelas */}
            <div className="md:col-span-2">
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                Nama Kelas <span className="text-red-500">*</span>
              </label>
              <Input
                name="nama_kelas"
                value={formData.nama_kelas}
                onChange={handleChange}
                placeholder="Contoh: X IPA 1"
                error={errors.nama_kelas}
              />
            </div>

            {/* Tingkat */}
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                Tingkat <span className="text-red-500">*</span>
              </label>
              <select
                name="tingkat"
                value={formData.tingkat}
                onChange={handleChange}
                className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm focus:border-primary-500 focus:outline-none focus:ring-1 focus:ring-primary-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
              >
                <option value="">Pilih Tingkat</option>
                {tingkatOptions.map(option => (
                  <option key={option.value} value={option.value}>
                    {option.label}
                  </option>
                ))}
              </select>
              {errors.tingkat && <p className="mt-1 text-sm text-red-500">{errors.tingkat}</p>}
            </div>

            {/* Tahun Ajaran */}
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                Tahun Ajaran <span className="text-red-500">*</span>
              </label>
              <select
                name="tahun_ajaran"
                value={formData.tahun_ajaran}
                onChange={handleChange}
                className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm focus:border-primary-500 focus:outline-none focus:ring-1 focus:ring-primary-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
              >
                <option value="">Pilih Tahun Ajaran</option>
                {tahunAjaranOptions.map(option => (
                  <option key={option.value} value={option.value}>
                    {option.label}
                  </option>
                ))}
              </select>
              {errors.tahun_ajaran && <p className="mt-1 text-sm text-red-500">{errors.tahun_ajaran}</p>}
            </div>

            {/* Kapasitas */}
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                Kapasitas Maksimal Siswa
              </label>
              <Input
                type="number"
                name="kapasitas"
                value={formData.kapasitas}
                onChange={handleChange}
                placeholder="Contoh: 40"
                error={errors.kapasitas}
              />
            </div>

            {/* Wali Guru - Searchable Select */}
            <div ref={guruDropdownRef}>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                Wali Kelas
              </label>
              <div className="relative">
                <button
                  type="button"
                  onClick={() => setIsGuruOpen(!isGuruOpen)}
                  className={`w-full rounded-md border ${
                    errors.wali_guru_id 
                      ? 'border-red-500 focus:border-red-500 focus:ring-red-500' 
                      : 'border-gray-300 focus:border-primary-500 focus:ring-primary-500'
                  } bg-white px-3 py-2 text-sm text-left focus:outline-none focus:ring-1 dark:border-gray-600 dark:bg-gray-800 dark:text-white flex items-center justify-between`}
                >
                  <span className={selectedGuru ? 'text-gray-900 dark:text-white' : 'text-gray-500 dark:text-gray-400'}>
                    {selectedGuru ? `${selectedGuru.nama}${selectedGuru.nip ? ` (${selectedGuru.nip})` : ''}` : 'Pilih Wali Kelas'}
                  </span>
                  <div className="flex items-center gap-1">
                    {selectedGuru && (
                      <X
                        size={16}
                        className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
                        onClick={handleClearGuru}
                      />
                    )}
                    <ChevronDown
                      size={16}
                      className={`text-gray-400 transition-transform ${isGuruOpen ? 'rotate-180' : ''}`}
                    />
                  </div>
                </button>

                {/* Dropdown */}
                {isGuruOpen && (
                  <div className="absolute z-10 mt-1 w-full rounded-md border border-gray-300 bg-white shadow-lg dark:border-gray-600 dark:bg-gray-800 max-h-60 overflow-hidden">
                    {/* Search Input */}
                    <div className="p-2 border-b border-gray-200 dark:border-gray-700">
                      <div className="relative">
                        <Search size={16} className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
                        <input
                          type="text"
                          className="w-full pl-9 pr-3 py-2 text-sm rounded-md border border-gray-300 focus:border-primary-500 focus:outline-none focus:ring-1 focus:ring-primary-500 dark:border-gray-600 dark:bg-gray-700 dark:text-white"
                          placeholder="Cari guru..."
                          value={guruSearch}
                          onChange={(e) => setGuruSearch(e.target.value)}
                          onClick={(e) => e.stopPropagation()}
                        />
                      </div>
                    </div>

                    {/* Options List */}
                    <div className="max-h-48 overflow-y-auto">
                      {guruLoading ? (
                        <div className="px-3 py-2 text-sm text-gray-500 dark:text-gray-400 text-center">
                          Memuat data...
                        </div>
                      ) : guruOptions.length === 0 ? (
                        <div className="px-3 py-2 text-sm text-gray-500 dark:text-gray-400 text-center">
                          Tidak ada data guru
                        </div>
                      ) : (
                        guruOptions.map((guru) => (
                          <button
                            key={guru.id}
                            type="button"
                            onClick={() => handleWaliGuruChange(guru)}
                            className={`w-full px-3 py-2 text-left hover:bg-gray-100 dark:hover:bg-gray-700 flex flex-col ${
                              selectedGuru?.id === guru.id ? 'bg-primary-50 dark:bg-primary-900/20' : ''
                            }`}
                          >
                            <span className="text-sm font-medium text-gray-900 dark:text-white">
                              {guru.nama}
                            </span>
                            <span className="text-xs text-gray-500 dark:text-gray-400">
                              NIP: {guru.nip} {guru.nuptk && `| NUPTK: ${guru.nuptk}`}
                            </span>
                          </button>
                        ))
                      )}
                    </div>
                  </div>
                )}
              </div>
              {errors.wali_guru_id && <p className="mt-1 text-sm text-red-500">{errors.wali_guru_id}</p>}
            </div>
          </div>

          <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
            <Button type="button" variant="secondary" onClick={() => navigate('/kelas')}>
              Batal
            </Button>
            <Button type="submit" disabled={loading}>
              <Save size={18} className="mr-2" />
              {loading ? 'Menyimpan...' : 'Simpan'}
            </Button>
          </div>
        </form>
        )}
      </Card>
    </div>
  )
}

export default KelasForm

import { useState, useEffect } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import { ArrowLeft, FileText, Clock, Monitor, User, BookOpen } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import { logAksesMateriService } from '../services/logAksesMateriService'
import { showError } from '../../../utils/sweetalert'

const LogAksesMateriDetail = () => {
  const navigate = useNavigate()
  const { id } = useParams()
  const [data, setData] = useState(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => { fetchData() }, [id])

  const fetchData = async () => {
    setLoading(true)
    const { data: res, error } = await logAksesMateriService.getById(id)
    if (res?.data) setData(res.data)
    else { showError('Gagal mengambil data log'); navigate('/akademik/log-akses-materi') }
    setLoading(false)
  }

  const formatDurasi = (detik) => {
    if (!detik) return '-'
    const h = Math.floor(detik / 3600)
    const m = Math.floor((detik % 3600) / 60)
    const s = detik % 60
    const parts = []
    if (h > 0) parts.push(`${h} jam`)
    if (m > 0) parts.push(`${m} menit`)
    if (s > 0) parts.push(`${s} detik`)
    return parts.join(' ') || '0 detik'
  }

  if (loading) return <div className="flex items-center justify-center h-64"><div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div></div>
  if (!data) return null

  const InfoRow = ({ label, value, icon: Icon }) => (
    <div className="flex items-start gap-3 py-3 border-b border-gray-100 dark:border-gray-700 last:border-0">
      {Icon && <Icon size={18} className="text-gray-400 mt-0.5 shrink-0" />}
      <div><p className="text-sm text-gray-500 dark:text-gray-400">{label}</p><p className="text-sm font-medium text-gray-900 dark:text-white">{value || '-'}</p></div>
    </div>
  )

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="secondary" onClick={() => navigate('/akademik/log-akses-materi')}><ArrowLeft size={18} /></Button>
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Detail Log Akses #{data.id}</h1>
      </div>
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <Card>
          <div className="p-6">
            <h2 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">Informasi Akses</h2>
            <InfoRow label="ID" value={data.id} icon={FileText} />
            <InfoRow label="Materi" value={data.materi?.judul || data.mst_materi_id} icon={BookOpen} />
            <InfoRow label="Siswa" value={data.siswa?.nama || data.mst_siswa_id} icon={User} />
            <InfoRow label="Waktu Akses" value={data.waktu_akses ? new Date(data.waktu_akses).toLocaleString('id-ID') : '-'} icon={Clock} />
            <InfoRow label="Durasi" value={formatDurasi(data.durasi_detik)} icon={Clock} />
            <InfoRow label="Perangkat" value={data.perangkat} icon={Monitor} />
          </div>
        </Card>
        <Card>
          <div className="p-6">
            <h2 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">Metadata</h2>
            <InfoRow label="Materi ID" value={data.mst_materi_id} icon={FileText} />
            <InfoRow label="Siswa ID" value={data.mst_siswa_id} icon={FileText} />
            <InfoRow label="Dibuat" value={data.created_at ? new Date(data.created_at).toLocaleString('id-ID') : '-'} icon={Clock} />
            <InfoRow label="Diperbarui" value={data.updated_at ? new Date(data.updated_at).toLocaleString('id-ID') : '-'} icon={Clock} />
          </div>
        </Card>
      </div>
    </div>
  )
}

export default LogAksesMateriDetail

import { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ArrowLeft, Edit, Trash2, BookOpen, Hash } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import { mapelService } from '../services/mapelService'
import { showDeleteConfirm, showSuccess, showError } from '../../../utils/sweetalert'

const MapelDetail = () => {
  const { id } = useParams()
  const navigate = useNavigate()
  
  const [loading, setLoading] = useState(false)
  const [mapel, setMapel] = useState(null)

  useEffect(() => {
    fetchMapel()
  }, [id])

  const fetchMapel = async () => {
    setLoading(true)
    const { data, error } = await mapelService.getMapelById(id)
    if (data) {
      setMapel(data.data)
    } else {
      showError('Gagal mengambil data mata pelajaran')
      navigate('/mapel')
    }
    setLoading(false)
  }

  const handleDelete = async () => {
    const result = await showDeleteConfirm(mapel.nama)
    if (result.isConfirmed) {
      const { error } = await mapelService.deleteMapel(mapel.id)
      if (!error) {
        showSuccess(`${mapel.nama} berhasil dihapus!`)
        navigate('/mapel')
      } else {
        showError('Gagal menghapus mata pelajaran')
      }
    }
  }

  const formatDate = (dateString) => {
    if (!dateString) return '-'
    const date = new Date(dateString)
    return date.toLocaleDateString('id-ID', {
      day: 'numeric',
      month: 'long',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    })
  }

  if (loading || !mapel) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
        <div className="flex items-center gap-4">
          <Button variant="secondary" onClick={() => navigate('/mapel')}>
            <ArrowLeft size={18} className="mr-2" />
            Kembali
          </Button>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Detail Mata Pelajaran</h1>
        </div>
        <div className="flex gap-3">
          <Button variant="warning" onClick={() => navigate(`/mapel/${id}/edit`)}>
            <Edit size={18} className="mr-2" />
            Edit
          </Button>
          <Button variant="danger" onClick={handleDelete}>
            <Trash2 size={18} className="mr-2" />
            Hapus
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {/* Detail Info Card */}
        <div className="md:col-span-3">
          <Card>
            <div className="p-6">
              <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-6">Informasi Mata Pelajaran</h3>
              
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="flex items-start gap-3">
                  <div className="w-10 h-10 bg-blue-50 dark:bg-blue-900/20 rounded-lg flex items-center justify-center flex-shrink-0">
                    <Hash size={20} className="text-blue-600" />
                  </div>
                  <div>
                    <p className="text-xs text-gray-500 dark:text-gray-400">Kode Mata Pelajaran</p>
                    <p className="font-medium text-gray-900 dark:text-white">{mapel.kode || '-'}</p>
                  </div>
                </div>

                <div className="flex items-start gap-3">
                  <div className="w-10 h-10 bg-green-50 dark:bg-green-900/20 rounded-lg flex items-center justify-center flex-shrink-0">
                    <BookOpen size={20} className="text-green-600" />
                  </div>
                  <div>
                    <p className="text-xs text-gray-500 dark:text-gray-400">Nama Mata Pelajaran</p>
                    <p className="font-medium text-gray-900 dark:text-white">{mapel.nama || '-'}</p>
                  </div>
                </div>
              </div>

              {/* Timestamps */}
              <div className="mt-8 border-t border-gray-200 dark:border-gray-700 pt-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-sm">
                  <div>
                    <p className="text-xs text-gray-500 dark:text-gray-400">Dibuat pada</p>
                    <p className="text-gray-700 dark:text-gray-300">{formatDate(mapel.created_at)}</p>
                  </div>
                  <div>
                    <p className="text-xs text-gray-500 dark:text-gray-400">Terakhir diperbarui</p>
                    <p className="text-gray-700 dark:text-gray-300">{formatDate(mapel.updated_at)}</p>
                  </div>
                </div>
              </div>
            </div>
          </Card>
        </div>
      </div>
    </div>
  )
}

