    const newErrors = {}
    if (!formData.kode) newErrors.kode = 'Kode mata pelajaran wajib diisi'
    if (!formData.nama) newErrors.nama = 'Nama mata pelajaran wajib diisi'

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

