                {loading ? 'Menyimpan...' : 'Simpan'}
              </Button>
            </div>
          </form>
        )}
      </Card>
    </div>
  )
}

export default MapelForm

import { useCallback, useEffect, useState } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ArrowLeft, Save } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import Input from '../../../components/ui/Input'
import SearchableSelect from '../../../components/ui/SearchableSelect'
import LexicalEditor from '../../../components/ui/LexicalEditor'
import '../../../components/ui/LexicalEditor.css'
import { materiService } from '../services/materiService'
import { showSuccess, showError } from '../../../utils/sweetalert'

const TIPE_OPTIONS = [
  { value: 'dokumen', label: 'Dokumen' },
  { value: 'video', label: 'Video' },
  { value: 'link', label: 'Link' },
  { value: 'lainnya', label: 'Lainnya' },
]

const STATUS_OPTIONS = [
  { value: '1', label: 'Aktif' },
  { value: '0', label: 'Nonaktif' },
]

const MateriForm = () => {
  const { id } = useParams()
  const navigate = useNavigate()
  const isEditMode = !!id

  const [loading, setLoading] = useState(false)
  const [fetchingData, setFetchingData] = useState(false)
  
  const [formData, setFormData] = useState({
    mst_guru_mapel_id: '',
    judul: '',
    konten: '',
    tipe: '',
    file_path: '',
    url_external: '',
    status: '1',
    urutan: ''
  })

  const [errors, setErrors] = useState({})
  const [selectedGuruMapelOption, setSelectedGuruMapelOption] = useState(null)

  useEffect(() => {
    if (isEditMode) {
      fetchMateri()
    }
  }, [id])

  const buildGuruMapelOption = useCallback((guruMapel) => {
    if (!guruMapel) return null

    const guruNama = guruMapel.guru?.nama || guruMapel.nama_guru || 'Guru'
    const mapelNama = guruMapel.mapel?.nama || guruMapel.mapel?.nama_mapel || guruMapel.nama_mapel || 'Mapel'
    const rawId = guruMapel.id ?? guruMapel.mst_guru_mapel_id

    if (!rawId) return null

    return {
      value: String(rawId),
      label: `${guruNama} - ${mapelNama}`
    }
  }, [])

  const searchGuruMapelOptions = useCallback(async (keyword = '') => {
    const normalizedKeyword = keyword.trim()

    const { data, error } = await materiService.getAll({
      search: normalizedKeyword || undefined,
      per_page: 20
    })

    if (data?.data) {
      const seenIds = new Set()
      return data.data.reduce((options, materi) => {
        const option = buildGuruMapelOption(materi.guru_mapel)
        if (!option || seenIds.has(option.value)) return options

        const label = option.label.toLowerCase()
        if (normalizedKeyword && !label.includes(normalizedKeyword.toLowerCase())) {
          return options
        }

        seenIds.add(option.value)
        options.push(option)
        return options
      }, [])
    }

    console.error('Failed to fetch guru mapel options:', error)
    return []
  }, [buildGuruMapelOption])

  const hydrateSelectedGuruMapelOption = useCallback(async (guruMapelId) => {
    if (!guruMapelId) {
      setSelectedGuruMapelOption(null)
      return
    }

    const { data } = await materiService.getAll({ per_page: 20 })
    const materiList = data?.data || []
    const matchedMateri = materiList.find(
      (materi) => String(materi.guru_mapel?.id) === String(guruMapelId)
    )

    const option = buildGuruMapelOption(matchedMateri?.guru_mapel)

    if (option) {
      setSelectedGuruMapelOption(option)
      return
    }

    setSelectedGuruMapelOption({
      value: String(guruMapelId),
      label: `Guru Mapel #${guruMapelId}`
    })
  }, [buildGuruMapelOption])

  const fetchMateri = async () => {
    setFetchingData(true)
    const { data, error } = await materiService.getById(id)
    if (data) {
      const materi = data.data
      const guruMapelId = materi.guru_mapel?.id ? String(materi.guru_mapel.id) : (materi.mst_guru_mapel_id ? String(materi.mst_guru_mapel_id) : '')

      setFormData({
        mst_guru_mapel_id: guruMapelId,
        judul: materi.judul || '',
        konten: materi.konten || '',
        tipe: materi.tipe || '',
        file_path: materi.file_path || '',
        url_external: materi.url_external || '',
        status: materi.status !== null && materi.status !== undefined ? String(materi.status) : '1',
        urutan: materi.urutan !== null && materi.urutan !== undefined ? String(materi.urutan) : ''
      })

      if (materi.guru_mapel) {
        const option = buildGuruMapelOption(materi.guru_mapel)
        if (option) {
          setSelectedGuruMapelOption(option)
        }
      }
    } else {
      showError('Gagal mengambil data materi')
      navigate('/akademik/materi')
    }
    setFetchingData(false)
  }

  useEffect(() => {
    if (formData.mst_guru_mapel_id) {
      hydrateSelectedGuruMapelOption(formData.mst_guru_mapel_id)
    } else {
      setSelectedGuruMapelOption(null)
    }
  }, [formData.mst_guru_mapel_id, hydrateSelectedGuruMapelOption])

  const handleChange = (e) => {
    const { name, value } = e.target
    setFormData(prev => ({ ...prev, [name]: value }))
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: null }))
    }
  }

  const validate = () => {
    const newErrors = {}
    if (!formData.judul.trim()) newErrors.judul = 'Judul wajib diisi'
    if (!formData.mst_guru_mapel_id) newErrors.mst_guru_mapel_id = 'Guru Mapel wajib dipilih'

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    
    if (!validate()) return

    setLoading(true)
    
    const submitData = {
      mst_guru_mapel_id: parseInt(formData.mst_guru_mapel_id),
      judul: formData.judul,
      konten: formData.konten || null,
      tipe: formData.tipe || null,
      file_path: formData.file_path || null,
      url_external: formData.url_external || null,
      status: formData.status !== '' ? parseInt(formData.status) : null,
      urutan: formData.urutan !== '' ? parseInt(formData.urutan) : null
    }

    let result
    
    if (isEditMode) {
      result = await materiService.update(id, submitData)
    } else {
      result = await materiService.create(submitData)
    }

    const { error } = result

    if (!error) {
      showSuccess(`Materi berhasil ${isEditMode ? 'diperbarui' : 'ditambahkan'}!`)
      navigate('/akademik/materi')
    } else {
      console.error(error)
      if (error.errors) {
        setErrors(error.errors)
      } else {
        showError(`Gagal ${isEditMode ? 'memperbarui' : 'menambahkan'} materi`)
      }
    }
    setLoading(false)
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="secondary" onClick={() => navigate('/akademik/materi')}>
          <ArrowLeft size={18} className="mr-2" />
          Kembali
        </Button>
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
          {isEditMode ? 'Edit Materi' : 'Tambah Materi Baru'}
        </h1>
      </div>

      <Card>
        {fetchingData ? (
          <div className="flex items-center justify-center h-64">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="p-6 space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Judul */}
              <div className="md:col-span-2">
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Judul <span className="text-red-500">*</span>
                </label>
                <Input
                  type="text"
                  name="judul"
                  value={formData.judul}
                  onChange={handleChange}
                  placeholder="Masukkan judul materi"
                  error={errors.judul}
                />
              </div>

              {/* Guru Mapel */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Guru & Mata Pelajaran <span className="text-red-500">*</span>
                </label>
                <SearchableSelect
                  name="mst_guru_mapel_id"
                  value={formData.mst_guru_mapel_id}
                  onChange={handleChange}
                  options={selectedGuruMapelOption ? [selectedGuruMapelOption] : []}
                  loadOptions={searchGuruMapelOptions}
                  placeholder="Pilih guru & mata pelajaran"
                  searchPlaceholder="Cari guru mapel berdasarkan guru atau mapel..."
                  noOptionsText="Tidak ada guru mapel yang cocok"
                  error={errors.mst_guru_mapel_id}
                />
              </div>

              {/* Tipe */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Tipe
                </label>
                <SearchableSelect
                  name="tipe"
                  value={formData.tipe}
                  onChange={handleChange}
                  options={TIPE_OPTIONS}
                  placeholder="Pilih tipe materi"
                  error={errors.tipe}
                />
              </div>

              {/* Konten */}
              <div className="md:col-span-2">
                <LexicalEditor
                  label="Konten"
                  required
                  value={formData.konten}
                  onChange={(html) => setFormData(prev => ({ ...prev, konten: html }))}
                  placeholder="Tulis konten materi..."
                  minHeight="200px"
                />
                {errors.konten && (
                  <p className="mt-1 text-sm text-red-500">{errors.konten}</p>
                )}
              </div>

              {/* File Path */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  File Path
                </label>
                <Input
                  type="text"
                  name="file_path"
                  value={formData.file_path}
                  onChange={handleChange}
                  placeholder="Path file (opsional)"
                  error={errors.file_path}
                />
              </div>

              {/* URL External */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  URL External
                </label>
                <Input
                  type="text"
                  name="url_external"
                  value={formData.url_external}
                  onChange={handleChange}
                  placeholder="URL external (opsional)"
                  error={errors.url_external}
                />
              </div>

              {/* Status */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Status
                </label>
                <SearchableSelect
                  name="status"
                  value={formData.status}
                  onChange={handleChange}
                  options={STATUS_OPTIONS}
                  placeholder="Pilih status"
                  error={errors.status}
                />
              </div>

              {/* Urutan */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Urutan
                </label>
                <Input
                  type="number"
                  name="urutan"
                  value={formData.urutan}
                  onChange={handleChange}
                  placeholder="Urutan (opsional)"
                  error={errors.urutan}
                />
              </div>
            </div>

            <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
              <Button type="button" variant="secondary" onClick={() => navigate('/akademik/materi')}>
                Batal
              </Button>
              <Button type="submit" disabled={loading}>
                <Save size={18} className="mr-2" />
                {loading ? 'Menyimpan...' : 'Simpan'}
              </Button>
            </div>
          </form>
        )}
      </Card>
    </div>
  )
}

export default MateriForm

import { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ArrowLeft, Save } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import Input from '../../../components/ui/Input'
import { menuService } from '../services/menuService'
import { showSuccess, showError } from '../../../utils/sweetalert'

const MenuForm = () => {
  const { id } = useParams()
  const navigate = useNavigate()
  const isEditMode = !!id

  const [loading, setLoading] = useState(false)
  const [fetchingData, setFetchingData] = useState(false)
  const [parentMenus, setParentMenus] = useState([])

  const [formData, setFormData] = useState({
    parent_id: '',
    sys_permission_id: '',
    nama_menu: '',
    url: '',
    icon: '',
    urutan: '',
    is_active: 1
  })

  const [errors, setErrors] = useState({})

  useEffect(() => {
    fetchParentMenus()
    if (isEditMode) fetchMenu()
  }, [id])

  const fetchParentMenus = async () => {
    const { data } = await menuService.getAll({ per_page: 100 })
    if (data) {
      const menus = (data.data || []).filter(m => String(m.id) !== String(id))
      setParentMenus(menus)
    }
  }

  const fetchMenu = async () => {
    setFetchingData(true)
    const { data, error } = await menuService.getById(id)
    if (data) {
      const menu = data.data
      setFormData({
        parent_id: menu.parent_id || '',
        sys_permission_id: menu.sys_permission_id || '',
        nama_menu: menu.nama_menu || '',
        url: menu.url || '',
        icon: menu.icon || '',
        urutan: menu.urutan ?? '',
        is_active: menu.is_active !== undefined ? menu.is_active : 1
      })
    } else {
      showError('Gagal mengambil data menu')
      navigate('/admin/menus')
    }
    setFetchingData(false)
  }

  const handleChange = (e) => {
    const { name, value } = e.target
    setFormData(prev => ({ ...prev, [name]: value }))
    if (errors[name]) setErrors(prev => ({ ...prev, [name]: null }))
  }

  const validate = () => {
    const newErrors = {}
    if (!formData.nama_menu) newErrors.nama_menu = 'Nama menu wajib diisi'
    if (formData.nama_menu && formData.nama_menu.length > 100) newErrors.nama_menu = 'Nama menu maksimal 100 karakter'
    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    if (!validate()) return

    setLoading(true)

    const submitData = {
      ...formData,
      parent_id: formData.parent_id || null,
      sys_permission_id: formData.sys_permission_id || null,
      urutan: formData.urutan !== '' ? Number(formData.urutan) : null,
      is_active: Number(formData.is_active)
    }

    let result
    if (isEditMode) {
      result = await menuService.update(id, submitData)
    } else {
      result = await menuService.create(submitData)
    }

    const { error } = result
    if (!error) {
      showSuccess(`Menu berhasil ${isEditMode ? 'diperbarui' : 'ditambahkan'}!`)
      navigate('/admin/menus')
    } else {
      if (error.errors) {
        setErrors(error.errors)
      } else {
        showError(`Gagal ${isEditMode ? 'memperbarui' : 'menambahkan'} menu`)
      }
    }
    setLoading(false)
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="secondary" onClick={() => navigate('/admin/menus')}>
          <ArrowLeft size={18} className="mr-2" />
          Kembali
        </Button>
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
          {isEditMode ? 'Edit Menu' : 'Tambah Menu Baru'}
        </h1>
      </div>

      <Card>
        {fetchingData ? (
          <div className="flex items-center justify-center h-64">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="p-6 space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="md:col-span-2">
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Nama Menu <span className="text-red-500">*</span>
                </label>
                <Input
                  name="nama_menu"
                  value={formData.nama_menu}
                  onChange={handleChange}
                  placeholder="Nama Menu"
                  error={errors.nama_menu}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Parent Menu
                </label>
                <select
                  name="parent_id"
                  value={formData.parent_id}
                  onChange={handleChange}
                  className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm focus:border-primary-500 focus:outline-none focus:ring-1 focus:ring-primary-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
                >
                  <option value="">Tidak ada (Root Menu)</option>
                  {parentMenus.map(menu => (
                    <option key={menu.id} value={menu.id}>{menu.nama_menu}</option>
                  ))}
                </select>
                {errors.parent_id && (
                  <p className="mt-1 text-sm text-red-500">
                    {Array.isArray(errors.parent_id) ? errors.parent_id[0] : errors.parent_id}
                  </p>
                )}
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Permission ID
                </label>
                <Input
                  name="sys_permission_id"
                  type="number"
                  value={formData.sys_permission_id}
                  onChange={handleChange}
                  placeholder="ID Permission (opsional)"
                  error={errors.sys_permission_id}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  URL
                </label>
                <Input
                  name="url"
                  value={formData.url}
                  onChange={handleChange}
                  placeholder="/path/to/page"
                  error={errors.url}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Icon
                </label>
                <Input
                  name="icon"
                  value={formData.icon}
                  onChange={handleChange}
                  placeholder="Nama icon (misal: home, users)"
                  error={errors.icon}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Urutan
                </label>
                <Input
                  name="urutan"
                  type="number"
                  value={formData.urutan}
                  onChange={handleChange}
                  placeholder="Urutan tampil"
                  error={errors.urutan}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Status
                </label>
                <select
                  name="is_active"
                  value={formData.is_active}
                  onChange={handleChange}
                  className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm focus:border-primary-500 focus:outline-none focus:ring-1 focus:ring-primary-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
                >
                  <option value={1}>Aktif</option>
                  <option value={0}>Nonaktif</option>
                </select>
                {errors.is_active && (
                  <p className="mt-1 text-sm text-red-500">
                    {Array.isArray(errors.is_active) ? errors.is_active[0] : errors.is_active}
                  </p>
                )}
              </div>
            </div>

            <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
              <Button type="button" variant="secondary" onClick={() => navigate('/admin/menus')}>
                Batal
              </Button>
              <Button type="submit" disabled={loading}>
                <Save size={18} className="mr-2" />
                {loading ? 'Menyimpan...' : 'Simpan'}
              </Button>
            </div>
          </form>
        )}
      </Card>
    </div>
  )
}

export default MenuForm

import { useCallback, useEffect, useState } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ArrowLeft, Save } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import Input from '../../../components/ui/Input'
import SearchableSelect from '../../../components/ui/SearchableSelect'
import { nilaiService } from '../services/nilaiService'
import { siswaService } from '../../siswa/services/siswaService'
import { ujianService } from '../../ujian/services/ujianService'
import { showSuccess, showError } from '../../../utils/sweetalert'

const NilaiForm = () => {
  const { id } = useParams()
  const navigate = useNavigate()
  const isEditMode = !!id

  const [loading, setLoading] = useState(false)
  const [fetchingData, setFetchingData] = useState(false)
  
  const [formData, setFormData] = useState({
    mst_siswa_id: '',
    trx_ujian_id: '',
    nilai: '',
    keterangan: ''
  })

  const [errors, setErrors] = useState({})
  const [selectedSiswaOption, setSelectedSiswaOption] = useState(null)
  const [selectedUjianOption, setSelectedUjianOption] = useState(null)

  const buildSiswaOption = useCallback((siswa) => ({
    value: String(siswa.id),
    label: `${siswa.nis || '-'} - ${siswa.nama || `Siswa #${siswa.id}`}`
  }), [])

  const buildUjianOption = useCallback((ujian) => ({
    value: String(ujian.id),
    label: ujian.nama || `Ujian #${ujian.id}`
  }), [])

  const searchSiswaOptions = useCallback(async (keyword = '') => {
    const { data, error } = await siswaService.getAll({
      search: keyword || undefined,
      per_page: 20
    })

    if (data?.data) {
      return data.data.map(buildSiswaOption)
    }

    console.error('Failed to fetch siswa:', error)
    return []
  }, [buildSiswaOption])

  const searchUjianOptions = useCallback(async (keyword = '') => {
    const { data, error } = await ujianService.getAll({
      search: keyword || undefined,
      per_page: 20
    })

    if (data?.data) {
      return data.data.map(buildUjianOption)
    }

    console.error('Failed to fetch ujian:', error)
    return []
  }, [buildUjianOption])

  const hydrateSelectedSiswaOption = useCallback(async (siswaId) => {
    if (!siswaId) {
      setSelectedSiswaOption(null)
      return
    }

    const { data } = await siswaService.getById(siswaId)
    const siswa = data?.data

    if (siswa) {
      setSelectedSiswaOption(buildSiswaOption(siswa))
    }
  }, [buildSiswaOption])

  const hydrateSelectedUjianOption = useCallback(async (ujianId) => {
    if (!ujianId) {
      setSelectedUjianOption(null)
      return
    }

    const { data } = await ujianService.getById(ujianId)
    const ujian = data?.data

    if (ujian) {
      setSelectedUjianOption(buildUjianOption(ujian))
    }
  }, [buildUjianOption])

  useEffect(() => {
    if (isEditMode) {
      fetchNilai()
    }
  }, [id])

  useEffect(() => {
    if (formData.mst_siswa_id) {
      hydrateSelectedSiswaOption(formData.mst_siswa_id)
    } else {
      setSelectedSiswaOption(null)
    }
  }, [formData.mst_siswa_id, hydrateSelectedSiswaOption])

  useEffect(() => {
    if (formData.trx_ujian_id) {
      hydrateSelectedUjianOption(formData.trx_ujian_id)
    } else {
      setSelectedUjianOption(null)
    }
  }, [formData.trx_ujian_id, hydrateSelectedUjianOption])

  const fetchNilai = async () => {
    setFetchingData(true)
    const { data, error } = await nilaiService.getById(id)
    if (data) {
      const nilai = data.data
      setFormData({
        mst_siswa_id: String(nilai.mst_siswa_id) || '',
        trx_ujian_id: String(nilai.trx_ujian_id) || '',
        nilai: nilai.nilai !== null && nilai.nilai !== undefined ? String(nilai.nilai) : '',
        keterangan: nilai.keterangan || ''
      })
    } else {
      showError('Gagal mengambil data nilai')
      navigate('/akademik/nilai')
    }
    setFetchingData(false)
  }

  const handleChange = (e) => {
    const { name, value } = e.target
    setFormData(prev => ({ ...prev, [name]: value }))
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: null }))
    }
  }

  const validate = () => {
    const newErrors = {}
    if (!formData.mst_siswa_id) newErrors.mst_siswa_id = 'Siswa wajib dipilih'
    if (!formData.trx_ujian_id) newErrors.trx_ujian_id = 'Ujian wajib dipilih'
    if (!formData.nilai && formData.nilai !== '0') newErrors.nilai = 'Nilai wajib diisi'
    
    const nilaiNum = parseFloat(formData.nilai)
    if (formData.nilai && (isNaN(nilaiNum) || nilaiNum < 0 || nilaiNum > 100)) {
      newErrors.nilai = 'Nilai harus berupa angka antara 0 - 100'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    
    if (!validate()) return

    setLoading(true)
    
    const submitData = {
      mst_siswa_id: parseInt(formData.mst_siswa_id),
      trx_ujian_id: parseInt(formData.trx_ujian_id),
      nilai: parseFloat(formData.nilai),
      keterangan: formData.keterangan || null
    }

    let result
    
    if (isEditMode) {
      result = await nilaiService.update(id, submitData)
    } else {
      result = await nilaiService.create(submitData)
    }

    const { error } = result

    if (!error) {
      showSuccess(`Nilai berhasil ${isEditMode ? 'diperbarui' : 'ditambahkan'}!`)
      navigate('/akademik/nilai')
    } else {
      console.error(error)
      if (error.errors) {
        setErrors(error.errors)
      } else {
        showError(`Gagal ${isEditMode ? 'memperbarui' : 'menambahkan'} nilai`)
      }
    }
    setLoading(false)
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="secondary" onClick={() => navigate('/akademik/nilai')}>
          <ArrowLeft size={18} className="mr-2" />
          Kembali
        </Button>
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
          {isEditMode ? 'Edit Nilai' : 'Tambah Nilai Baru'}
        </h1>
      </div>

      <Card>
        {fetchingData ? (
          <div className="flex items-center justify-center h-64">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="p-6 space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Siswa */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Siswa <span className="text-red-500">*</span>
                </label>
                <SearchableSelect
                  name="mst_siswa_id"
                  value={formData.mst_siswa_id}
                  onChange={handleChange}
                  options={selectedSiswaOption ? [selectedSiswaOption] : []}
                  loadOptions={searchSiswaOptions}
                  placeholder="Pilih siswa"
                  searchPlaceholder="Cari siswa berdasarkan nama atau NIS..."
                  noOptionsText="Tidak ada siswa yang cocok"
                  error={errors.mst_siswa_id}
                />
              </div>

              {/* Ujian */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Ujian <span className="text-red-500">*</span>
                </label>
                <SearchableSelect
                  name="trx_ujian_id"
                  value={formData.trx_ujian_id}
                  onChange={handleChange}
                  options={selectedUjianOption ? [selectedUjianOption] : []}
                  loadOptions={searchUjianOptions}
                  placeholder="Pilih ujian"
                  searchPlaceholder="Cari ujian..."
                  noOptionsText="Tidak ada ujian yang cocok"
                  error={errors.trx_ujian_id}
                />
              </div>

              {/* Nilai */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Nilai <span className="text-red-500">*</span>
                </label>
                <Input
                  type="number"
                  name="nilai"
                  value={formData.nilai}
                  onChange={handleChange}
                  placeholder="Masukkan nilai (0-100)"
                  min="0"
                  max="100"
                  step="0.01"
                  error={errors.nilai}
                />
              </div>

              {/* Keterangan */}
              <div className="md:col-span-2">
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Keterangan
                </label>
                <textarea
                  name="keterangan"
                  value={formData.keterangan}
                  onChange={handleChange}
                  rows={3}
                  className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm focus:border-primary-500 focus:outline-none focus:ring-1 focus:ring-primary-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
                  placeholder="Keterangan tambahan (opsional)"
                />
                {errors.keterangan && (
                  <p className="mt-1 text-sm text-red-500">
                    {Array.isArray(errors.keterangan) ? errors.keterangan[0] : errors.keterangan}
                  </p>
                )}
              </div>
            </div>

            <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
              <Button type="button" variant="secondary" onClick={() => navigate('/akademik/nilai')}>
                Batal
              </Button>
              <Button type="submit" disabled={loading}>
                <Save size={18} className="mr-2" />
                {loading ? 'Menyimpan...' : 'Simpan'}
              </Button>
            </div>
          </form>
        )}
      </Card>
    </div>
  )
}

