    if (!formData.periode_mulai) newErrors.periode_mulai = 'Periode mulai wajib diisi'
    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    if (!validate()) return

    setLoading(true)

    const submitData = {
      kode: formData.kode,
      nama: formData.nama,
      deskripsi: formData.deskripsi || null,
