                  value={formData.nama}
                  onChange={handleChange}
                  placeholder="Masukkan nama organisasi"
                  error={errors.nama}
                />
              </div>

              <div className="md:col-span-2">
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Deskripsi
                </label>
                <textarea
