import { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ArrowLeft, Save, BookOpen } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import Input from '../../../components/ui/Input'
import { bukuService } from '../services/perpustakaanService'
import { showSuccess, showError } from '../../../utils/sweetalert'
import { usePageTitle } from '../../../hooks/usePageTitle'

const BukuForm = () => {
  const { id } = useParams()
  const navigate = useNavigate()
  const isEditMode = !!id

  usePageTitle(isEditMode ? 'Edit Buku' : 'Tambah Buku')

  const [loading, setLoading] = useState(false)
  const [fetchingData, setFetchingData] = useState(false)
  
  const [formData, setFormData] = useState({
  isbn: '',
  judul: '',
  penulis: '',
  penerbit: '',
  tahun: '',
  stok: '',
  })

  const [errors, setErrors] = useState({})

  useEffect(() => {
    if (isEditMode) {
      fetchBuku()
    }
  }, [id])

  const fetchBuku = async () => {
    setFetchingData(true)
    const { data, error } = await bukuService.getById(id)
    if (data) {
      const buku = data.data
      setFormData({
      isbn: buku.isbn || '',
      judul: buku.judul || '',
      penulis: buku.penulis || '',
      penerbit: buku.penerbit || '',
      tahun: buku.tahun || '',
      stok: buku.stok || '',
      })
    } else {
      showError('Gagal mengambil data buku')
      navigate('/perpustakaan/buku')
    }
    setFetchingData(false)
  }

  const handleChange = (e) => {
    const { name, value } = e.target
    setFormData(prev => ({ ...prev, [name]: value }))
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: null }))
    }
  }

  const validate = () => {
    const newErrors = {}
    
    // Required field validation
    if (!formData.judul.trim()) {
      newErrors.judul = 'Judul wajib diisi'
    } else if (formData.judul.length > 200) {
      newErrors.judul = 'Judul maksimal 200 karakter'
    }
    
    // ISBN validation (max 20 chars)
    if (formData.isbn && formData.isbn.length > 20) {
      newErrors.isbn = 'ISBN maksimal 20 karakter'
    }
    
    // Penulis validation (max 100 chars)
    if (formData.penulis && formData.penulis.length > 100) {
      newErrors.penulis = 'Penulis maksimal 100 karakter'
    }
    
    // Penerbit validation (max 100 chars)
    if (formData.penerbit && formData.penerbit.length > 100) {
      newErrors.penerbit = 'Penerbit maksimal 100 karakter'
    }
    
    // Tahun validation
    if (formData.tahun) {
    const year = parseInt(formData.tahun)
    const currentYear = new Date().getFullYear()
    if (isNaN(year) || year < 1900 || year > currentYear) {
    newErrors.tahun = `Tahun harus antara 1900 dan ${currentYear}`
    }
    }
   
    // Stok validation
    if (formData.stok) {
    const stok = parseInt(formData.stok)
    if (isNaN(stok) || stok < 0) {
    newErrors.stok = 'Stok minimal 0'
    }
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    
    if (!validate()) return

    setLoading(true)
    
    // Convert numeric fields
    const submitData = {
    ...formData,
    isbn: formData.isbn || null,
    penulis: formData.penulis || null,
    penerbit: formData.penerbit || null,
    tahun: formData.tahun ? parseInt(formData.tahun) : null,
    stok: formData.stok ? parseInt(formData.stok) : null,
    }

    let result
    
    if (isEditMode) {
      result = await bukuService.update(id, submitData)
    } else {
      result = await bukuService.create(submitData)
    }

    const { error } = result

    if (!error) {
      showSuccess(`Buku berhasil ${isEditMode ? 'diperbarui' : 'ditambahkan'}!`)
      navigate('/perpustakaan/buku')
    } else {
      console.error(error)
      if (error.errors) {
        setErrors(error.errors)
      } else {
        showError(`Gagal ${isEditMode ? 'memperbarui' : 'menambahkan'} buku`)
      }
    }
    setLoading(false)
  }

  const currentYear = new Date().getFullYear()

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="secondary" onClick={() => navigate('/perpustakaan/buku')}>
          <ArrowLeft size={18} className="mr-2" />
          Kembali
        </Button>
        <div className="flex items-center gap-3">
          <BookOpen size={24} className="text-primary-600" />
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
            {isEditMode ? 'Edit Buku' : 'Tambah Buku Baru'}
          </h1>
        </div>
      </div>

      <Card>
        {fetchingData ? (
          <div className="flex items-center justify-center h-64">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="p-6 space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* ISBN */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  ISBN
                </label>
                <Input
                  name="isbn"
                  value={formData.isbn}
                  onChange={handleChange}
                  placeholder="Nomor ISBN"
                  error={errors.isbn}
                />
              </div>

              {/* Judul */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Judul <span className="text-red-500">*</span>
                </label>
                <Input
                  name="judul"
                  value={formData.judul}
                  onChange={handleChange}
                  placeholder="Judul Buku"
                  error={errors.judul}
                />
              </div>

              {/* Penulis */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Penulis
                </label>
                <Input
                  name="penulis"
                  value={formData.penulis}
                  onChange={handleChange}
                  placeholder="Nama Penulis"
                  error={errors.penulis}
                />
              </div>

              {/* Penerbit */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Penerbit
                </label>
                <Input
                  name="penerbit"
                  value={formData.penerbit}
                  onChange={handleChange}
                  placeholder="Nama Penerbit"
                  error={errors.penerbit}
                />
              </div>

              {/* Tahun */}
              <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              Tahun
              </label>
              <input
              type="number"
              name="tahun"
              value={formData.tahun}
              onChange={handleChange}
              min="1900"
              max={currentYear}
              placeholder={`1900 - ${currentYear}`}
              className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm focus:border-primary-500 focus:outline-none focus:ring-1 focus:ring-primary-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
              />
              {errors.tahun && (
              <p className="mt-1 text-sm text-red-500">{errors.tahun}</p>
              )}
              </div>

              {/* Stok */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Stok
                </label>
                <input
                  type="number"
                  name="stok"
                  value={formData.stok}
                  onChange={handleChange}
                  min="0"
                  placeholder="Jumlah stok"
                  className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm focus:border-primary-500 focus:outline-none focus:ring-1 focus:ring-primary-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
                />
                {errors.stok && (
                  <p className="mt-1 text-sm text-red-500">{errors.stok}</p>
                )}
              </div>

            </div>

            <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
              <Button type="button" variant="secondary" onClick={() => navigate('/perpustakaan/buku')}>
                Batal
              </Button>
              <Button type="submit" disabled={loading}>
                <Save size={18} className="mr-2" />
                {loading ? 'Menyimpan...' : 'Simpan'}
              </Button>
            </div>
          </form>
        )}
      </Card>
    </div>
  )
}

export default BukuForm

import { useCallback, useEffect, useState } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ArrowLeft, Save } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import { peminjamanService, bukuService } from '../services/perpustakaanService'
import { siswaService } from '../../siswa/services/siswaService'
import SearchableSelect from '../../../components/ui/SearchableSelect'
import { showSuccess, showError } from '../../../utils/sweetalert'
import { usePageTitle } from '../../../hooks/usePageTitle'

const PeminjamanForm = () => {
  const { id } = useParams()
  const navigate = useNavigate()
  const isEditMode = !!id

  usePageTitle(isEditMode ? 'Edit Peminjaman' : 'Tambah Peminjaman')

  const [loading, setLoading] = useState(false)
  const [fetchingData, setFetchingData] = useState(false)
  
  const [selectedSiswaOption, setSelectedSiswaOption] = useState(null)
  const [selectedBukuOption, setSelectedBukuOption] = useState(null)
  
  const [formData, setFormData] = useState({
    mst_siswa_id: '',
    mst_buku_id: '',
    tanggal_pinjam: '',
    tanggal_jatuh_tempo: '',
    keterangan: ''
  })

  const [errors, setErrors] = useState({})

  // Fetch peminjaman data if in edit mode
  useEffect(() => {
    if (isEditMode) {
      fetchPeminjaman()
    }
  }, [id])

  const buildSiswaOption = useCallback((siswa) => ({
    value: String(siswa.id),
    label: `${siswa.nama || `Siswa #${siswa.id}`} (${siswa.nis || '-'})`
  }), [])

  const buildBukuOption = useCallback((buku) => ({
    value: String(buku.id),
    label: `${buku.judul || `Buku #${buku.id}`} (${buku.isbn || '-'})`
  }), [])

  const searchSiswaOptions = useCallback(async (keyword = '') => {
    const { data, error } = await siswaService.getAll({
      search: keyword || undefined,
      per_page: 20
    })

    if (data?.data) {
      return data.data.map(buildSiswaOption)
    }

    console.error('Error fetching siswa:', error)
    return []
  }, [buildSiswaOption])

  const searchBukuOptions = useCallback(async (keyword = '') => {
    const { data, error } = await bukuService.getAvailable({
      search: keyword || undefined,
      per_page: 20
    })

    if (data?.data) {
      return data.data.map(buildBukuOption)
    }

    console.error('Error fetching buku:', error)
    return []
  }, [buildBukuOption])

  const hydrateSelectedSiswaOption = useCallback(async (siswaId) => {
    if (!siswaId) {
      setSelectedSiswaOption(null)
      return
    }

    const { data } = await siswaService.getById(siswaId)
    const siswa = data?.data

    if (siswa) {
      setSelectedSiswaOption(buildSiswaOption(siswa))
    }
  }, [buildSiswaOption])

  const hydrateSelectedBukuOption = useCallback(async (bukuId) => {
    if (!bukuId) {
      setSelectedBukuOption(null)
      return
    }

    const { data } = await bukuService.getById(bukuId)
    const buku = data?.data

    if (buku) {
      setSelectedBukuOption(buildBukuOption(buku))
    }
  }, [buildBukuOption])

  const fetchPeminjaman = async () => {
    setFetchingData(true)
    const { data, error } = await peminjamanService.getById(id)
    if (data && data.data) {
      const peminjaman = data.data
      const siswaId = String(peminjaman.mst_siswa_id || peminjaman.siswa?.id || '')
      const bukuId = String(peminjaman.mst_buku_id || peminjaman.buku?.id || '')

      setFormData({
        mst_siswa_id: siswaId,
        mst_buku_id: bukuId,
        tanggal_pinjam: peminjaman.tanggal_pinjam || '',
        tanggal_jatuh_tempo: peminjaman.tanggal_jatuh_tempo || '',
        keterangan: peminjaman.keterangan || ''
      })

      if (peminjaman.siswa?.id) {
        setSelectedSiswaOption(buildSiswaOption(peminjaman.siswa))
      }

      if (peminjaman.buku?.id) {
        setSelectedBukuOption(buildBukuOption(peminjaman.buku))
      }
    } else {
      showError('Gagal mengambil data peminjaman')
      navigate('/perpustakaan/peminjaman')
    }
    setFetchingData(false)
  }

  useEffect(() => {
    if (formData.mst_siswa_id) {
      hydrateSelectedSiswaOption(formData.mst_siswa_id)
    } else {
      setSelectedSiswaOption(null)
    }
  }, [formData.mst_siswa_id, hydrateSelectedSiswaOption])

  useEffect(() => {
    if (formData.mst_buku_id) {
      hydrateSelectedBukuOption(formData.mst_buku_id)
    } else {
      setSelectedBukuOption(null)
    }
  }, [formData.mst_buku_id, hydrateSelectedBukuOption])

  const handleChange = (e) => {
    const { name, value } = e.target
    setFormData(prev => ({ ...prev, [name]: value }))
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: null }))
    }
  }

  const validate = () => {
    const newErrors = {}
    if (!formData.mst_siswa_id) newErrors.mst_siswa_id = 'Siswa wajib dipilih'
    if (!formData.mst_buku_id) newErrors.mst_buku_id = 'Buku wajib dipilih'
    if (!formData.tanggal_jatuh_tempo) newErrors.tanggal_jatuh_tempo = 'Tanggal jatuh tempo wajib diisi'
    
    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    
    if (!validate()) return

    setLoading(true)
    
    const submitData = {
      ...formData,
      mst_siswa_id: parseInt(formData.mst_siswa_id),
      mst_buku_id: parseInt(formData.mst_buku_id),
      tanggal_pinjam: formData.tanggal_pinjam || null,
      keterangan: formData.keterangan || null
    }

    let result
    
    if (isEditMode) {
      result = await peminjamanService.update(id, submitData)
    } else {
      result = await peminjamanService.create(submitData)
    }

    const { error } = result

    if (!error) {
      showSuccess(`Peminjaman berhasil ${isEditMode ? 'diperbarui' : 'ditambahkan'}!`)
      navigate('/perpustakaan/peminjaman')
    } else {
      console.error(error)
      if (error.errors) {
        setErrors(error.errors)
      } else {
        showError(`Gagal ${isEditMode ? 'memperbarui' : 'menambahkan'} peminjaman`)
      }
    }
    setLoading(false)
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="secondary" onClick={() => navigate('/perpustakaan/peminjaman')}>
          <ArrowLeft size={18} className="mr-2" />
          Kembali
        </Button>
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
          {isEditMode ? 'Edit Peminjaman' : 'Tambah Peminjaman Baru'}
        </h1>
      </div>

      <Card>
        {fetchingData ? (
          <div className="flex items-center justify-center h-64">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="p-6 space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Siswa Select */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Siswa <span className="text-red-500">*</span>
                </label>
                <SearchableSelect
                  name="mst_siswa_id"
                  value={formData.mst_siswa_id}
                  onChange={handleChange}
                  options={selectedSiswaOption ? [selectedSiswaOption] : []}
                  loadOptions={searchSiswaOptions}
                  placeholder="Pilih Siswa"
                  searchPlaceholder="Cari siswa berdasarkan nama atau NIS..."
                  noOptionsText="Tidak ada siswa yang cocok"
                  disabled={isEditMode}
                  error={errors.mst_siswa_id}
                />
                {isEditMode && (
                  <p className="mt-1 text-xs text-gray-500 dark:text-gray-400">
                    Siswa tidak dapat diubah saat edit
                  </p>
                )}
              </div>

              {/* Buku Select */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Buku <span className="text-red-500">*</span>
                </label>
                <SearchableSelect
                  name="mst_buku_id"
                  value={formData.mst_buku_id}
                  onChange={handleChange}
                  options={selectedBukuOption ? [selectedBukuOption] : []}
                  loadOptions={searchBukuOptions}
                  placeholder="Pilih Buku"
                  searchPlaceholder="Cari buku tersedia berdasarkan judul atau ISBN..."
                  noOptionsText="Tidak ada buku tersedia yang cocok"
                  disabled={isEditMode}
                  error={errors.mst_buku_id}
                />
                {isEditMode && (
                  <p className="mt-1 text-xs text-gray-500 dark:text-gray-400">
                    Buku tidak dapat diubah saat edit
                  </p>
                )}
              </div>

              {/* Tanggal Pinjam */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Tanggal Pinjam
                </label>
                <input
                  type="date"
                  name="tanggal_pinjam"
                  value={formData.tanggal_pinjam}
                  onChange={handleChange}
                  className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm focus:border-primary-500 focus:outline-none focus:ring-1 focus:ring-primary-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
                />
                {errors.tanggal_pinjam && (
                  <p className="mt-1 text-sm text-red-500">
                    {Array.isArray(errors.tanggal_pinjam) ? errors.tanggal_pinjam[0] : errors.tanggal_pinjam}
                  </p>
                )}
              </div>

              {/* Tanggal Jatuh Tempo */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Tanggal Jatuh Tempo <span className="text-red-500">*</span>
                </label>
                <input
                  type="date"
                  name="tanggal_jatuh_tempo"
                  value={formData.tanggal_jatuh_tempo}
                  onChange={handleChange}
                  className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm focus:border-primary-500 focus:outline-none focus:ring-1 focus:ring-primary-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
                />
                {errors.tanggal_jatuh_tempo && (
                  <p className="mt-1 text-sm text-red-500">
                    {Array.isArray(errors.tanggal_jatuh_tempo) ? errors.tanggal_jatuh_tempo[0] : errors.tanggal_jatuh_tempo}
                  </p>
                )}
              </div>

              {/* Keterangan */}
              <div className="md:col-span-2">
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Keterangan
                </label>
                <textarea
                  name="keterangan"
                  value={formData.keterangan}
                  onChange={handleChange}
                  rows={3}
                  className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm focus:border-primary-500 focus:outline-none focus:ring-1 focus:ring-primary-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
                  placeholder="Keterangan tambahan (opsional)"
                />
                {errors.keterangan && (
                  <p className="mt-1 text-sm text-red-500">
                    {Array.isArray(errors.keterangan) ? errors.keterangan[0] : errors.keterangan}
                  </p>
                )}
              </div>
            </div>

            <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
              <Button type="button" variant="secondary" onClick={() => navigate('/perpustakaan/peminjaman')}>
                Batal
              </Button>
              <Button type="submit" disabled={loading}>
                <Save size={18} className="mr-2" />
                {loading ? 'Menyimpan...' : 'Simpan'}
              </Button>
            </div>
          </form>
        )}
      </Card>
    </div>
  )
}

export default PeminjamanForm

import { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ArrowLeft, Save } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import Input from '../../../components/ui/Input'
import { dokumenService } from '../services/ppdbService'
import { showSuccess, showError } from '../../../utils/sweetalert'

const DokumenForm = () => {
  const { id } = useParams()
  const navigate = useNavigate()
  const isEdit = Boolean(id)
  const [loading, setLoading] = useState(false)
  const [saving, setSaving] = useState(false)
  const [formData, setFormData] = useState({
    ppdb_pendaftar_id: '',
    jenis_dokumen: '',
    file_name: '',
    mime_type: '',
    file_size: '',
    file_path: '',
    verifikasi_status: '',
    catatan_admin: '',
  })
  const [errors, setErrors] = useState({})

  useEffect(() => {
    if (isEdit) fetchDokumen()
  }, [id])

  const fetchDokumen = async () => {
    setLoading(true)
    const { data, error } = await dokumenService.getById(id)
    if (data) {
      const d = data.data || data
      setFormData({
        ppdb_pendaftar_id: d.ppdb_pendaftar_id || '',
        jenis_dokumen: d.jenis_dokumen || '',
        file_name: d.file_name || '',
        mime_type: d.mime_type || '',
        file_size: d.file_size || '',
        file_path: d.file_path || '',
        verifikasi_status: d.verifikasi_status || '',
        catatan_admin: d.catatan_admin || '',
      })
    } else {
      showError('Gagal mengambil data dokumen')
      navigate('/ppdb/dokumen')
    }
    setLoading(false)
  }

  const handleChange = (e) => {
    const { name, value } = e.target
    setFormData((prev) => ({ ...prev, [name]: value }))
    if (errors[name]) setErrors((prev) => ({ ...prev, [name]: '' }))
  }

  const validate = () => {
    const newErrors = {}
    if (!formData.ppdb_pendaftar_id) newErrors.ppdb_pendaftar_id = 'ID Pendaftar wajib diisi'
    if (!formData.jenis_dokumen) newErrors.jenis_dokumen = 'Jenis dokumen wajib diisi'
    if (!formData.file_name) newErrors.file_name = 'Nama file wajib diisi'
    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    if (!validate()) return

    setSaving(true)
    const payload = { ...formData }
    if (payload.file_size) payload.file_size = Number(payload.file_size)

    const { data, error } = isEdit
      ? await dokumenService.update(id, payload)
      : await dokumenService.create(payload)

    if (data) {
      showSuccess(`Dokumen berhasil ${isEdit ? 'diperbarui' : 'ditambahkan'}!`)
      navigate('/ppdb/dokumen')
    } else {
      if (error?.errors) {
        setErrors(error.errors)
      } else {
        showError(error?.message || 'Gagal menyimpan dokumen')
      }
    }
    setSaving(false)
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="secondary" onClick={() => navigate('/ppdb/dokumen')}>
          <ArrowLeft size={18} className="mr-2" />
          Kembali
        </Button>
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
          {isEdit ? 'Edit Dokumen' : 'Tambah Dokumen'}
        </h1>
      </div>

      <Card>
        <form onSubmit={handleSubmit} className="p-6 space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <Input
              label="ID Pendaftar *"
              name="ppdb_pendaftar_id"
              type="number"
              value={formData.ppdb_pendaftar_id}
              onChange={handleChange}
              error={errors.ppdb_pendaftar_id}
              placeholder="Masukkan ID pendaftar"
            />
            <Input
              label="Jenis Dokumen *"
              name="jenis_dokumen"
              value={formData.jenis_dokumen}
              onChange={handleChange}
              error={errors.jenis_dokumen}
              placeholder="cth: kartu_keluarga, akte, rapor, ijazah"
            />
            <Input
              label="Nama File *"
              name="file_name"
              value={formData.file_name}
              onChange={handleChange}
              error={errors.file_name}
              placeholder="Masukkan nama file"
            />
            <Input
              label="MIME Type"
              name="mime_type"
              value={formData.mime_type}
              onChange={handleChange}
              error={errors.mime_type}
              placeholder="cth: application/pdf"
            />
            <Input
              label="Ukuran File (bytes)"
              name="file_size"
              type="number"
              value={formData.file_size}
              onChange={handleChange}
              error={errors.file_size}
              placeholder="Masukkan ukuran file"
            />
            <Input
              label="Path File"
              name="file_path"
              value={formData.file_path}
              onChange={handleChange}
              error={errors.file_path}
              placeholder="Masukkan path file"
            />
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Status Verifikasi</label>
              <select
                name="verifikasi_status"
                value={formData.verifikasi_status}
                onChange={handleChange}
                className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white focus:ring-2 focus:ring-primary-500"
              >
                <option value="">-- Pilih Status --</option>
                <option value="pending">Pending</option>
                <option value="verified">Terverifikasi</option>
                <option value="rejected">Ditolak</option>
              </select>
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Catatan Admin</label>
            <textarea
              name="catatan_admin"
              value={formData.catatan_admin}
              onChange={handleChange}
              rows={3}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white focus:ring-2 focus:ring-primary-500"
              placeholder="Catatan admin (opsional)"
            />
          </div>

          <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
            <Button variant="secondary" type="button" onClick={() => navigate('/ppdb/dokumen')}>
              Batal
            </Button>
            <Button type="submit" disabled={saving}>
              <Save size={18} className="mr-2" />
              {saving ? 'Menyimpan...' : 'Simpan'}
            </Button>
          </div>
        </form>
      </Card>
    </div>
  )
}

export default DokumenForm

import { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ArrowLeft, Save } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import Input from '../../../components/ui/Input'
import SearchableSelect from '../../../components/ui/SearchableSelect'
import { gelombangService } from '../services/ppdbService'
import { tahunAjaranService } from '../../tahun-ajaran/services/tahunAjaranService'
import { showSuccess, showError } from '../../../utils/sweetalert'

const STATUS_OPTIONS = [
  { value: '1', label: 'Aktif' },
  { value: '0', label: 'Nonaktif' },
]

const GelombangForm = () => {
  const { id } = useParams()
  const navigate = useNavigate()
  const isEditMode = !!id

  const [loading, setLoading] = useState(false)
  const [fetchingData, setFetchingData] = useState(false)
  const [tahunAjaranOptions, setTahunAjaranOptions] = useState([])

  const [formData, setFormData] = useState({
    mst_sekolah_id: '',
    nama_gelombang: '',
    tahun_ajaran_id: '',
    tgl_mulai: '',
    tgl_selesai: '',
    biaya_pendaftaran: '',
    is_active: '1',
  })

  const [errors, setErrors] = useState({})

  useEffect(() => {
    fetchTahunAjaranOptions()
    if (isEditMode) {
      fetchGelombang()
    }
  }, [id])

  const fetchTahunAjaranOptions = async () => {
    const { data } = await tahunAjaranService.getAll({ per_page: 100 })
    if (data?.data) {
      setTahunAjaranOptions(data.data.map(ta => ({
        value: String(ta.id),
        label: ta.nama || `${ta.tahun_mulai}/${ta.tahun_selesai}`
      })))
    }
  }

  const fetchGelombang = async () => {
    setFetchingData(true)
    const { data, error } = await gelombangService.getById(id)
    if (data) {
      const g = data.data
      setFormData({
        mst_sekolah_id: g.mst_sekolah_id ? String(g.mst_sekolah_id) : '',
        nama_gelombang: g.nama_gelombang || '',
        tahun_ajaran_id: g.tahun_ajaran_id ? String(g.tahun_ajaran_id) : '',
        tgl_mulai: g.tgl_mulai || '',
        tgl_selesai: g.tgl_selesai || '',
        biaya_pendaftaran: g.biaya_pendaftaran !== null && g.biaya_pendaftaran !== undefined ? String(g.biaya_pendaftaran) : '',
        is_active: g.is_active !== null && g.is_active !== undefined ? String(Number(g.is_active)) : '1',
      })
    } else {
      showError('Gagal mengambil data gelombang')
      navigate('/ppdb/gelombang')
    }
    setFetchingData(false)
  }

  const handleChange = (e) => {
    const { name, value } = e.target
    setFormData(prev => ({ ...prev, [name]: value }))
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: null }))
    }
  }

  const validate = () => {
    const newErrors = {}
    if (!formData.nama_gelombang.trim()) newErrors.nama_gelombang = 'Nama gelombang wajib diisi'
    if (!formData.tahun_ajaran_id) newErrors.tahun_ajaran_id = 'Tahun ajaran wajib dipilih'
    if (!formData.tgl_mulai) newErrors.tgl_mulai = 'Tanggal mulai wajib diisi'
    if (!formData.tgl_selesai) newErrors.tgl_selesai = 'Tanggal selesai wajib diisi'
    if (!isEditMode && !formData.mst_sekolah_id) newErrors.mst_sekolah_id = 'Sekolah ID wajib diisi'
    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    if (!validate()) return

    setLoading(true)
    const submitData = {
      mst_sekolah_id: parseInt(formData.mst_sekolah_id),
      nama_gelombang: formData.nama_gelombang,
      tahun_ajaran_id: parseInt(formData.tahun_ajaran_id),
      tgl_mulai: formData.tgl_mulai,
      tgl_selesai: formData.tgl_selesai,
      biaya_pendaftaran: formData.biaya_pendaftaran ? parseFloat(formData.biaya_pendaftaran) : null,
      is_active: formData.is_active !== '' ? parseInt(formData.is_active) : null,
    }

    let result
    if (isEditMode) {
      result = await gelombangService.update(id, submitData)
    } else {
      result = await gelombangService.create(submitData)
    }

    const { error } = result
    if (!error) {
      showSuccess(`Gelombang berhasil ${isEditMode ? 'diperbarui' : 'ditambahkan'}!`)
      navigate('/ppdb/gelombang')
    } else {
      if (error.errors) {
        setErrors(error.errors)
      } else {
        showError(`Gagal ${isEditMode ? 'memperbarui' : 'menambahkan'} gelombang`)
      }
    }
    setLoading(false)
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="secondary" onClick={() => navigate('/ppdb/gelombang')}>
          <ArrowLeft size={18} className="mr-2" />
          Kembali
        </Button>
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
          {isEditMode ? 'Edit Gelombang' : 'Tambah Gelombang Baru'}
        </h1>
      </div>

      <Card>
        {fetchingData ? (
          <div className="flex items-center justify-center h-64">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="p-6 space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="md:col-span-2">
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Nama Gelombang <span className="text-red-500">*</span>
                </label>
                <Input
                  type="text"
                  name="nama_gelombang"
                  value={formData.nama_gelombang}
                  onChange={handleChange}
                  placeholder="Masukkan nama gelombang"
                  error={errors.nama_gelombang}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Sekolah ID <span className="text-red-500">*</span>
                </label>
                <Input
                  type="number"
                  name="mst_sekolah_id"
                  value={formData.mst_sekolah_id}
                  onChange={handleChange}
                  placeholder="ID Sekolah"
                  error={errors.mst_sekolah_id}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Tahun Ajaran <span className="text-red-500">*</span>
                </label>
                <SearchableSelect
                  name="tahun_ajaran_id"
                  value={formData.tahun_ajaran_id}
                  onChange={handleChange}
                  options={tahunAjaranOptions}
                  placeholder="Pilih tahun ajaran"
                  error={errors.tahun_ajaran_id}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Tanggal Mulai <span className="text-red-500">*</span>
                </label>
                <Input
                  type="date"
                  name="tgl_mulai"
                  value={formData.tgl_mulai}
                  onChange={handleChange}
                  error={errors.tgl_mulai}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Tanggal Selesai <span className="text-red-500">*</span>
                </label>
                <Input
                  type="date"
                  name="tgl_selesai"
                  value={formData.tgl_selesai}
                  onChange={handleChange}
                  error={errors.tgl_selesai}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Biaya Pendaftaran
                </label>
                <Input
                  type="number"
                  name="biaya_pendaftaran"
                  value={formData.biaya_pendaftaran}
                  onChange={handleChange}
                  placeholder="0"
                  error={errors.biaya_pendaftaran}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Status
                </label>
                <SearchableSelect
                  name="is_active"
                  value={formData.is_active}
                  onChange={handleChange}
                  options={STATUS_OPTIONS}
                  placeholder="Pilih status"
                  error={errors.is_active}
                />
              </div>
            </div>

            <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
              <Button type="button" variant="secondary" onClick={() => navigate('/ppdb/gelombang')}>
                Batal
              </Button>
              <Button type="submit" disabled={loading}>
                <Save size={18} className="mr-2" />
                {loading ? 'Menyimpan...' : 'Simpan'}
              </Button>
            </div>
          </form>
        )}
      </Card>
    </div>
  )
}

export default GelombangForm

import { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ArrowLeft, Save } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import Input from '../../../components/ui/Input'
import SearchableSelect from '../../../components/ui/SearchableSelect'
import { pendaftarService, gelombangService } from '../services/ppdbService'
import { showSuccess, showError } from '../../../utils/sweetalert'
import { useReferenceOptions } from '../../../hooks/useReferenceOptions'

const STATUS_OPTIONS = [
  { value: 'draft', label: 'Draft' },
  { value: 'terverifikasi', label: 'Terverifikasi' },
  { value: 'seleksi', label: 'Seleksi' },
  { value: 'diterima', label: 'Diterima' },
  { value: 'cadangan', label: 'Cadangan' },
  { value: 'ditolak', label: 'Ditolak' },
]

const PendaftarForm = () => {
  const { options: jenisKelaminOptions } = useReferenceOptions('jenis_kelamin', [
    { value: 'L', label: 'Laki-laki' },
    { value: 'P', label: 'Perempuan' },
  ])
  const { id } = useParams()
  const navigate = useNavigate()
  const isEditMode = !!id

  const [loading, setLoading] = useState(false)
  const [fetchingData, setFetchingData] = useState(false)
  const [gelombangOptions, setGelombangOptions] = useState([])

  const [formData, setFormData] = useState({
    mst_sekolah_id: '',
    ppdb_gelombang_id: '',
    nama_lengkap: '',
    email: '',
    password: '',
    nisn: '',
    jenis_kelamin: '',
    telp_hp: '',
    asal_sekolah: '',
    pilihan_jurusan_id: '',
    status_pendaftaran: 'draft',
  })

  const [errors, setErrors] = useState({})

  useEffect(() => {
    fetchGelombangOptions()
    if (isEditMode) {
      fetchPendaftar()
    }
  }, [id])

  const fetchGelombangOptions = async () => {
    const { data } = await gelombangService.getAll({ per_page: 100 })
    if (data?.data) {
      setGelombangOptions(data.data.map(g => ({
        value: String(g.id),
        label: g.nama_gelombang || `Gelombang #${g.id}`
      })))
    }
  }

  const fetchPendaftar = async () => {
    setFetchingData(true)
    const { data, error } = await pendaftarService.getById(id)
    if (data) {
      const p = data.data
      setFormData({
        mst_sekolah_id: p.mst_sekolah_id ? String(p.mst_sekolah_id) : '',
        ppdb_gelombang_id: p.ppdb_gelombang_id ? String(p.ppdb_gelombang_id) : '',
        nama_lengkap: p.nama_lengkap || '',
        email: p.email || '',
        password: '',
        nisn: p.nisn || '',
        jenis_kelamin: p.jenis_kelamin || '',
        telp_hp: p.telp_hp || '',
        asal_sekolah: p.asal_sekolah || '',
        pilihan_jurusan_id: p.pilihan_jurusan_id ? String(p.pilihan_jurusan_id) : '',
        status_pendaftaran: p.status_pendaftaran || 'draft',
      })
    } else {
      showError('Gagal mengambil data pendaftar')
      navigate('/ppdb/pendaftar')
    }
    setFetchingData(false)
  }

  const handleChange = (e) => {
    const { name, value } = e.target
    setFormData(prev => ({ ...prev, [name]: value }))
    if (errors[name]) setErrors(prev => ({ ...prev, [name]: null }))
  }

  const validate = () => {
    const newErrors = {}
    if (!formData.nama_lengkap.trim()) newErrors.nama_lengkap = 'Nama lengkap wajib diisi'
    if (!formData.email.trim()) newErrors.email = 'Email wajib diisi'
    if (!formData.jenis_kelamin) newErrors.jenis_kelamin = 'Jenis kelamin wajib dipilih'
    if (!isEditMode) {
      if (!formData.ppdb_gelombang_id) newErrors.ppdb_gelombang_id = 'Gelombang wajib dipilih'
      if (!formData.mst_sekolah_id) newErrors.mst_sekolah_id = 'Sekolah ID wajib diisi'
    }
    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    if (!validate()) return

    setLoading(true)
    const submitData = {
      nama_lengkap: formData.nama_lengkap,
      email: formData.email,
      jenis_kelamin: formData.jenis_kelamin,
      nisn: formData.nisn || null,
      telp_hp: formData.telp_hp || null,
      asal_sekolah: formData.asal_sekolah || null,
      pilihan_jurusan_id: formData.pilihan_jurusan_id ? parseInt(formData.pilihan_jurusan_id) : null,
    }

    if (!isEditMode) {
      submitData.mst_sekolah_id = parseInt(formData.mst_sekolah_id)
      submitData.ppdb_gelombang_id = parseInt(formData.ppdb_gelombang_id)
      if (formData.password) submitData.password = formData.password
    } else {
      if (formData.status_pendaftaran) submitData.status_pendaftaran = formData.status_pendaftaran
      if (formData.password) submitData.password = formData.password
    }

    let result
    if (isEditMode) {
      result = await pendaftarService.update(id, submitData)
    } else {
      result = await pendaftarService.create(submitData)
    }

    const { error } = result
    if (!error) {
      showSuccess(`Pendaftar berhasil ${isEditMode ? 'diperbarui' : 'ditambahkan'}!`)
      navigate('/ppdb/pendaftar')
    } else {
      if (error.errors) setErrors(error.errors)
      else showError(`Gagal ${isEditMode ? 'memperbarui' : 'menambahkan'} pendaftar`)
    }
    setLoading(false)
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="secondary" onClick={() => navigate('/ppdb/pendaftar')}>
          <ArrowLeft size={18} className="mr-2" />
          Kembali
        </Button>
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
          {isEditMode ? 'Edit Pendaftar' : 'Tambah Pendaftar Baru'}
        </h1>
      </div>

      <Card>
        {fetchingData ? (
          <div className="flex items-center justify-center h-64">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="p-6 space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="md:col-span-2">
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Nama Lengkap <span className="text-red-500">*</span>
                </label>
                <Input type="text" name="nama_lengkap" value={formData.nama_lengkap} onChange={handleChange} placeholder="Masukkan nama lengkap" error={errors.nama_lengkap} />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Email <span className="text-red-500">*</span>
                </label>
                <Input type="email" name="email" value={formData.email} onChange={handleChange} placeholder="email@example.com" error={errors.email} />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Password {!isEditMode && <span className="text-gray-400">(opsional)</span>}
                </label>
                <Input type="password" name="password" value={formData.password} onChange={handleChange} placeholder={isEditMode ? 'Kosongkan jika tidak diubah' : 'Password'} error={errors.password} />
              </div>

              {!isEditMode && (
                <>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                      Sekolah ID <span className="text-red-500">*</span>
                    </label>
                    <Input type="number" name="mst_sekolah_id" value={formData.mst_sekolah_id} onChange={handleChange} placeholder="ID Sekolah" error={errors.mst_sekolah_id} />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                      Gelombang PPDB <span className="text-red-500">*</span>
                    </label>
                    <SearchableSelect name="ppdb_gelombang_id" value={formData.ppdb_gelombang_id} onChange={handleChange} options={gelombangOptions} placeholder="Pilih gelombang" error={errors.ppdb_gelombang_id} />
                  </div>
                </>
              )}

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Jenis Kelamin <span className="text-red-500">*</span>
                </label>
                <SearchableSelect name="jenis_kelamin" value={formData.jenis_kelamin} onChange={handleChange} options={jenisKelaminOptions} placeholder="Pilih jenis kelamin" error={errors.jenis_kelamin} />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">NISN</label>
                <Input type="text" name="nisn" value={formData.nisn} onChange={handleChange} placeholder="NISN (opsional)" error={errors.nisn} />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">No. Telp/HP</label>
                <Input type="text" name="telp_hp" value={formData.telp_hp} onChange={handleChange} placeholder="No. telepon (opsional)" error={errors.telp_hp} />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Asal Sekolah</label>
                <Input type="text" name="asal_sekolah" value={formData.asal_sekolah} onChange={handleChange} placeholder="Asal sekolah (opsional)" error={errors.asal_sekolah} />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Pilihan Jurusan ID</label>
                <Input type="number" name="pilihan_jurusan_id" value={formData.pilihan_jurusan_id} onChange={handleChange} placeholder="ID Jurusan (opsional)" error={errors.pilihan_jurusan_id} />
              </div>

              {isEditMode && (
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Status Pendaftaran</label>
                  <SearchableSelect name="status_pendaftaran" value={formData.status_pendaftaran} onChange={handleChange} options={STATUS_OPTIONS} placeholder="Pilih status" error={errors.status_pendaftaran} />
                </div>
              )}
            </div>

            <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
              <Button type="button" variant="secondary" onClick={() => navigate('/ppdb/pendaftar')}>Batal</Button>
              <Button type="submit" disabled={loading}>
                <Save size={18} className="mr-2" />
                {loading ? 'Menyimpan...' : 'Simpan'}
              </Button>
            </div>
          </form>
        )}
      </Card>
    </div>
  )
}

export default PendaftarForm

import { useCallback, useEffect, useState } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ArrowLeft, Save } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import SearchableSelect from '../../../components/ui/SearchableSelect'
import { presensiService } from '../services/presensiService'
import { siswaService } from '../../siswa/services/siswaService'
import { referenceService } from '../../../services/referenceService'
import { showSuccess, showError } from '../../../utils/sweetalert'
import { usePageTitle } from '../../../hooks/usePageTitle'

const PresensiForm = () => {
  usePageTitle()
  const { id } = useParams()
  const navigate = useNavigate()
  const isEditMode = !!id

  const [loading, setLoading] = useState(false)
  const [fetchingData, setFetchingData] = useState(false)
  const [selectedSiswaOption, setSelectedSiswaOption] = useState(null)
  const [statusOptions, setStatusOptions] = useState([])
  const [fetchingStatus, setFetchingStatus] = useState(true)
  const [rawPresensiStatus, setRawPresensiStatus] = useState(null)
  
  const [formData, setFormData] = useState({
    mst_siswa_id: '',
    mst_guru_mapel_id: '',
    tanggal: '',
    jam_masuk: '',
    status: '',
    keterangan: ''
  })

  const [errors, setErrors] = useState({})

  useEffect(() => {
    fetchStatusOptions()
    if (isEditMode) {
      fetchPresensi()
    }
  }, [id])

  useEffect(() => {
    if (rawPresensiStatus !== null && statusOptions.length > 0) {
      const matched = statusOptions.find(
        opt => String(opt.value) === String(rawPresensiStatus)
      )
      if (matched) {
        setFormData(prev => ({ ...prev, status: matched.value }))
      }
      setRawPresensiStatus(null)
    }
  }, [rawPresensiStatus, statusOptions])

  const fetchStatusOptions = async () => {
    setFetchingStatus(true)
    const { data, error } = await referenceService.getReferencesByCategory('status_presensi')
    if (data && !error) {
      const options = (data.data || []).map(item => ({
        value: item.kode,
        label: item.nama.charAt(0).toUpperCase() + item.nama.slice(1)
      }))
      setStatusOptions(options)
    } else {
      console.error('Error fetching status options:', error)
      showError('Gagal mengambil data status presensi')
    }
    setFetchingStatus(false)
  }

  const buildSiswaOption = useCallback((siswa) => ({
    value: String(siswa.id),
    label: `${siswa.nis || '-'} - ${siswa.nama || `Siswa #${siswa.id}`}`
  }), [])

  const searchSiswaOptions = useCallback(async (keyword = '') => {
    const { data, error } = await siswaService.getAll({
      search: keyword || undefined,
      per_page: 20
    })

    if (data?.data) {
      return data.data.map(buildSiswaOption)
    }

    console.error('Error fetching siswa:', error)
    return []
  }, [buildSiswaOption])

  const hydrateSelectedSiswaOption = useCallback(async (siswaId) => {
    if (!siswaId) {
      setSelectedSiswaOption(null)
      return
    }

    const { data } = await siswaService.getById(siswaId)
    const siswa = data?.data

    if (siswa) {
      setSelectedSiswaOption(buildSiswaOption(siswa))
    }
  }, [buildSiswaOption])

  const fetchPresensi = async () => {
    setFetchingData(true)
    const { data, error } = await presensiService.getPresensiById(id)
    if (data) {
      const presensi = data.data
      const siswaId = String(presensi.mst_siswa_id || presensi.siswa?.id || '')

      setFormData({
        mst_siswa_id: siswaId,
        mst_guru_mapel_id: presensi.mst_guru_mapel_id || presensi.guru_mapel?.id || '',
        tanggal: presensi.tanggal || '',
        jam_masuk: presensi.jam_masuk || '',
        status: '',
        keterangan: presensi.keterangan || ''
      })
      setRawPresensiStatus(presensi.status)

      if (presensi.siswa?.id) {
        setSelectedSiswaOption(buildSiswaOption(presensi.siswa))
      }
    } else {
      showError('Gagal mengambil data presensi')
      navigate('/akademik/presensi')
    }
    setFetchingData(false)
  }

  useEffect(() => {
    if (formData.mst_siswa_id) {
      hydrateSelectedSiswaOption(formData.mst_siswa_id)
    } else {
      setSelectedSiswaOption(null)
    }
  }, [formData.mst_siswa_id, hydrateSelectedSiswaOption])

  const handleChange = (e) => {
    const { name, value } = e.target
    setFormData(prev => ({ ...prev, [name]: value }))
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: null }))
    }
  }

  const validate = () => {
    const newErrors = {}
    if (!formData.mst_siswa_id) newErrors.mst_siswa_id = 'Siswa wajib dipilih'
    if (!formData.mst_guru_mapel_id) newErrors.mst_guru_mapel_id = 'Guru Mapel ID wajib diisi'
    if (!formData.tanggal) newErrors.tanggal = 'Tanggal wajib diisi'
    if (!formData.status) newErrors.status = 'Status wajib dipilih'

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    
    if (!validate()) return

    setLoading(true)
    
    const submitData = {
      mst_siswa_id: parseInt(formData.mst_siswa_id),
      mst_guru_mapel_id: parseInt(formData.mst_guru_mapel_id),
      tanggal: formData.tanggal,
      jam_masuk: formData.jam_masuk || null,
      status: formData.status,
      keterangan: formData.keterangan || null
    }

    let result
    
    if (isEditMode) {
      result = await presensiService.updatePresensi(id, submitData)
    } else {
      result = await presensiService.createPresensi(submitData)
    }

    const { error } = result

    if (!error) {
      showSuccess(`Presensi berhasil ${isEditMode ? 'diperbarui' : 'ditambahkan'}!`)
      navigate('/akademik/presensi')
    } else {
      console.error(error)
      if (error.errors) {
        setErrors(error.errors)
      } else {
        showError(`Gagal ${isEditMode ? 'memperbarui' : 'menambahkan'} presensi`)
      }
    }
    setLoading(false)
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="secondary" onClick={() => navigate('/akademik/presensi')}>
          <ArrowLeft size={18} className="mr-2" />
          Kembali
        </Button>
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
          {isEditMode ? 'Edit Presensi' : 'Tambah Presensi Baru'}
        </h1>
      </div>

      <Card>
        {fetchingData || fetchingStatus ? (
          <div className="flex items-center justify-center h-64">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="p-6 space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Siswa */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Siswa <span className="text-red-500">*</span>
                </label>
                <SearchableSelect
                  name="mst_siswa_id"
                  value={formData.mst_siswa_id}
                  onChange={handleChange}
                  disabled={isEditMode}
                  placeholder="Cari dan pilih siswa..."
                  options={selectedSiswaOption ? [selectedSiswaOption] : []}
                  loadOptions={searchSiswaOptions}
                  searchPlaceholder="Cari siswa berdasarkan nama atau NIS..."
                  noOptionsText="Tidak ada siswa yang cocok"
                  error={errors.mst_siswa_id ? (Array.isArray(errors.mst_siswa_id) ? errors.mst_siswa_id[0] : errors.mst_siswa_id) : null}
                />
              </div>

              {/* Guru Mapel ID */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Guru Mapel ID <span className="text-red-500">*</span>
                </label>
                <input
                  type="number"
                  name="mst_guru_mapel_id"
                  value={formData.mst_guru_mapel_id}
                  onChange={handleChange}
                  placeholder="Masukkan ID Guru Mapel"
                  className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm focus:border-primary-500 focus:outline-none focus:ring-1 focus:ring-primary-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
                />
                {errors.mst_guru_mapel_id && (
                  <p className="mt-1 text-sm text-red-500">
                    {Array.isArray(errors.mst_guru_mapel_id) ? errors.mst_guru_mapel_id[0] : errors.mst_guru_mapel_id}
                  </p>
                )}
              </div>

              {/* Tanggal */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Tanggal <span className="text-red-500">*</span>
                </label>
                <input
                  type="date"
                  name="tanggal"
                  value={formData.tanggal}
                  onChange={handleChange}
                  onClick={(e) => e.target.showPicker?.()}
                  className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm focus:border-primary-500 focus:outline-none focus:ring-1 focus:ring-primary-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
                />
                {errors.tanggal && (
                  <p className="mt-1 text-sm text-red-500">
                    {Array.isArray(errors.tanggal) ? errors.tanggal[0] : errors.tanggal}
                  </p>
                )}
              </div>

              {/* Status */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Status <span className="text-red-500">*</span>
                </label>
                <select
                  name="status"
                  value={formData.status}
                  onChange={handleChange}
                  className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm focus:border-primary-500 focus:outline-none focus:ring-1 focus:ring-primary-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
                >
                  <option value="">Pilih Status</option>
                  {statusOptions.map(option => (
                    <option key={option.value} value={option.value}>
                      {option.label}
                    </option>
                  ))}
                </select>
                {errors.status && (
                  <p className="mt-1 text-sm text-red-500">
                    {Array.isArray(errors.status) ? errors.status[0] : errors.status}
                  </p>
                )}
              </div>

              {/* Jam Masuk */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Jam Masuk
                </label>
                <input
                  type="time"
                  name="jam_masuk"
                  value={formData.jam_masuk}
                  onChange={handleChange}
                  onClick={(e) => e.target.showPicker?.()}
                  className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm focus:border-primary-500 focus:outline-none focus:ring-1 focus:ring-primary-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
                />
                {errors.jam_masuk && (
                  <p className="mt-1 text-sm text-red-500">
                    {Array.isArray(errors.jam_masuk) ? errors.jam_masuk[0] : errors.jam_masuk}
                  </p>
                )}
              </div>

              {/* Keterangan */}
              <div className="md:col-span-2">
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Keterangan
                </label>
                <textarea
                  name="keterangan"
                  value={formData.keterangan}
                  onChange={handleChange}
                  rows={3}
                  className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm focus:border-primary-500 focus:outline-none focus:ring-1 focus:ring-primary-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
                  placeholder="Keterangan opsional"
                />
                {errors.keterangan && (
                  <p className="mt-1 text-sm text-red-500">
                    {Array.isArray(errors.keterangan) ? errors.keterangan[0] : errors.keterangan}
                  </p>
                )}
              </div>
            </div>

            <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
              <Button type="button" variant="secondary" onClick={() => navigate('/akademik/presensi')}>
                Batal
              </Button>
              <Button type="submit" disabled={loading}>
                <Save size={18} className="mr-2" />
                {loading ? 'Menyimpan...' : 'Simpan'}
              </Button>
            </div>
          </form>
        )}
      </Card>
    </div>
  )
}

export default PresensiForm

import { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ArrowLeft, Save } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import Input from '../../../components/ui/Input'
import SearchableSelect from '../../../components/ui/SearchableSelect'
import { rankingService } from '../services/rankingService'
import { siswaService } from '../../siswa/services/siswaService'
import { kelasService } from '../../kelas/services/kelasService'
import { referenceService } from '../../../services/referenceService'
import { showSuccess, showError } from '../../../utils/sweetalert'

const RankingForm = () => {
  const { id } = useParams()
  const navigate = useNavigate()
  const isEditMode = !!id

  const [loading, setLoading] = useState(false)
  const [fetchingData, setFetchingData] = useState(false)

  const [formData, setFormData] = useState({
    mst_siswa_id: '',
    mst_kelas_id: '',
    semester: '',
    tahun_ajaran: '',
    rata_rata_nilai: '',
    peringkat: ''
  })

  const [errors, setErrors] = useState({})
  const [siswaOptions, setSiswaOptions] = useState([])
  const [kelasOptions, setKelasOptions] = useState([])
  const [semesterOptions, setSemesterOptions] = useState([])

  useEffect(() => {
    fetchOptions()
    if (isEditMode) {
      fetchRanking()
    }
  }, [id])

  const fetchOptions = async () => {
    const [siswaResult, kelasResult] = await Promise.all([
      siswaService.getAll({ per_page: 100 }),
      kelasService.getAll({ per_page: 100 })
    ])

    if (siswaResult.data?.data) {
      setSiswaOptions(siswaResult.data.data.map(s => ({
        value: String(s.id),
        label: `${s.nama} (${s.nis || '-'})`
      })))
    }

    if (kelasResult.data?.data) {
      setKelasOptions(kelasResult.data.data.map(k => ({
        value: String(k.id),
        label: k.nama_kelas
      })))
    }

    // Try to fetch semester options from reference service
    try {
      const semesterResult = await referenceService.getReferencesByCategory('kategori_semester')
      if (semesterResult.data?.data) {
        setSemesterOptions(semesterResult.data.data.map(s => ({
          value: String(s.kode),
          label: s.nama
        })))
      }
    } catch {
      setSemesterOptions([
        { value: '1', label: 'Semester 1' },
        { value: '2', label: 'Semester 2' }
      ])
    }
  }

  const fetchRanking = async () => {
    setFetchingData(true)
    const { data, error } = await rankingService.getById(id)
    if (data) {
      const ranking = data.data
      setFormData({
        mst_siswa_id: ranking.siswa?.id ? String(ranking.siswa.id) : (ranking.mst_siswa_id ? String(ranking.mst_siswa_id) : ''),
        mst_kelas_id: ranking.kelas?.id ? String(ranking.kelas.id) : (ranking.mst_kelas_id ? String(ranking.mst_kelas_id) : ''),
        semester: ranking.semester ? String(ranking.semester) : '',
        tahun_ajaran: ranking.tahun_ajaran || '',
        rata_rata_nilai: ranking.rata_rata_nilai !== null && ranking.rata_rata_nilai !== undefined ? String(ranking.rata_rata_nilai) : '',
        peringkat: ranking.peringkat !== null && ranking.peringkat !== undefined ? String(ranking.peringkat) : ''
      })
    } else {
      showError('Gagal mengambil data ranking')
      navigate('/akademik/ranking')
    }
    setFetchingData(false)
  }

  const handleChange = (e) => {
    const { name, value } = e.target
    setFormData(prev => ({ ...prev, [name]: value }))
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: null }))
    }
  }

  const validate = () => {
    const newErrors = {}
    if (!formData.mst_siswa_id) newErrors.mst_siswa_id = 'Siswa wajib dipilih'
    if (!formData.mst_kelas_id) newErrors.mst_kelas_id = 'Kelas wajib dipilih'
    if (!formData.semester) newErrors.semester = 'Semester wajib diisi'
    if (!formData.tahun_ajaran.trim()) newErrors.tahun_ajaran = 'Tahun ajaran wajib diisi'
    if (!formData.rata_rata_nilai) newErrors.rata_rata_nilai = 'Rata-rata nilai wajib diisi'
    if (!formData.peringkat) newErrors.peringkat = 'Peringkat wajib diisi'

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e) => {
    e.preventDefault()

    if (!validate()) return

    setLoading(true)

    const submitData = {
      mst_siswa_id: parseInt(formData.mst_siswa_id),
      mst_kelas_id: parseInt(formData.mst_kelas_id),
      semester: formData.semester,
      tahun_ajaran: formData.tahun_ajaran,
      rata_rata_nilai: parseFloat(formData.rata_rata_nilai),
      peringkat: parseInt(formData.peringkat)
    }

    let result

    if (isEditMode) {
      result = await rankingService.update(id, submitData)
    } else {
      result = await rankingService.create(submitData)
    }

    const { error } = result

    if (!error) {
      showSuccess(`Ranking berhasil ${isEditMode ? 'diperbarui' : 'ditambahkan'}!`)
      navigate('/akademik/ranking')
    } else {
      console.error(error)
      if (error.errors) {
        setErrors(error.errors)
      } else {
        showError(`Gagal ${isEditMode ? 'memperbarui' : 'menambahkan'} ranking`)
      }
    }
    setLoading(false)
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="secondary" onClick={() => navigate('/akademik/ranking')}>
          <ArrowLeft size={18} className="mr-2" />
          Kembali
        </Button>
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
          {isEditMode ? 'Edit Ranking' : 'Tambah Ranking Baru'}
        </h1>
      </div>

      <Card>
        {fetchingData ? (
          <div className="flex items-center justify-center h-64">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="p-6 space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Siswa */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Siswa <span className="text-red-500">*</span>
                </label>
                <SearchableSelect
                  name="mst_siswa_id"
                  value={formData.mst_siswa_id}
                  onChange={handleChange}
                  options={siswaOptions}
                  placeholder="Pilih siswa"
                  error={errors.mst_siswa_id}
                />
              </div>

              {/* Kelas */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Kelas <span className="text-red-500">*</span>
                </label>
                <SearchableSelect
                  name="mst_kelas_id"
                  value={formData.mst_kelas_id}
                  onChange={handleChange}
                  options={kelasOptions}
                  placeholder="Pilih kelas"
                  error={errors.mst_kelas_id}
                />
              </div>

              {/* Semester */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Semester <span className="text-red-500">*</span>
                </label>
                <SearchableSelect
                  name="semester"
                  value={formData.semester}
                  onChange={handleChange}
                  options={semesterOptions}
                  placeholder="Pilih semester"
                  error={errors.semester}
                />
              </div>

              {/* Tahun Ajaran */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Tahun Ajaran <span className="text-red-500">*</span>
                </label>
                <Input
                  type="text"
                  name="tahun_ajaran"
                  value={formData.tahun_ajaran}
                  onChange={handleChange}
                  placeholder="Contoh: 2024/2025"
                  error={errors.tahun_ajaran}
                />
              </div>

              {/* Rata-rata Nilai */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Rata-rata Nilai <span className="text-red-500">*</span>
                </label>
                <Input
                  type="number"
                  name="rata_rata_nilai"
                  value={formData.rata_rata_nilai}
                  onChange={handleChange}
                  placeholder="0 - 100"
                  error={errors.rata_rata_nilai}
                  step="0.01"
                  min="0"
                  max="100"
                />
              </div>

              {/* Peringkat */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Peringkat <span className="text-red-500">*</span>
                </label>
                <Input
                  type="number"
                  name="peringkat"
                  value={formData.peringkat}
                  onChange={handleChange}
                  placeholder="Masukkan peringkat"
                  error={errors.peringkat}
                  min="1"
                />
              </div>
            </div>

            <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
              <Button type="button" variant="secondary" onClick={() => navigate('/akademik/ranking')}>
                Batal
              </Button>
              <Button type="submit" disabled={loading}>
                <Save size={18} className="mr-2" />
                {loading ? 'Menyimpan...' : 'Simpan'}
              </Button>
            </div>
          </form>
        )}
      </Card>
    </div>
  )
}

export default RankingForm

import { useCallback, useEffect, useState } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ArrowLeft, Save, Plus, Trash2 } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import Input from '../../../components/ui/Input'
import SearchableSelect from '../../../components/ui/SearchableSelect'
import { raporService } from '../services/raporService'
import { siswaService } from '../../siswa/services/siswaService'
import { mapelService } from '../../mapel/services/mapelService'
import { useReferenceOptions } from '../../../hooks/useReferenceOptions'
import { showSuccess, showError } from '../../../utils/sweetalert'
import { apiService } from '../../../utils/api'

const RaporForm = () => {
  const { id } = useParams()
  const navigate = useNavigate()
  const isEditMode = !!id

  const { options: semesterOptions } = useReferenceOptions('kategori_semester', [
    { value: '1', label: 'Ganjil' },
    { value: '2', label: 'Genap' },
  ])

  const [loading, setLoading] = useState(false)
  const [fetchingData, setFetchingData] = useState(false)

  const [formData, setFormData] = useState({
    mst_siswa_id: '',
    semester: '',
    tahun_ajaran_id: '',
    catatan_wali: '',
    sakit: '',
    izin: '',
    tanpa_keterangan: '',
  })

  const [details, setDetails] = useState([])
  const [errors, setErrors] = useState({})
  const [selectedSiswaOption, setSelectedSiswaOption] = useState(null)
  const [tahunAjaranOptions, setTahunAjaranOptions] = useState([])
  const [selectedMapelOptions, setSelectedMapelOptions] = useState([])

  useEffect(() => {
    fetchDropdownOptions()
    if (isEditMode) {
      fetchRapor()
    }
  }, [id])

  const buildSiswaOption = useCallback((siswa) => ({
    value: String(siswa.id),
    label: `${siswa.nis || '-'} - ${siswa.nama || `Siswa #${siswa.id}`}`
  }), [])

  const buildMapelOption = useCallback((mapel) => ({
    value: String(mapel.id),
    label: `${mapel.kode || '-'} - ${mapel.nama || mapel.nama_mapel || `Mapel #${mapel.id}`}`
  }), [])

  const fetchDropdownOptions = async () => {
    const tahunResult = await apiService.get('/admin/tahun-ajaran/')
    const tahunList = tahunResult.data?.data || []
    setTahunAjaranOptions(tahunList.map(t => ({
      value: String(t.id),
      label: t.nama || t.tahun_ajaran || `${t.id}`
    })))
  }

  const searchSiswaOptions = useCallback(async (keyword = '') => {
    const { data, error } = await siswaService.getAll({
      search: keyword || undefined,
      per_page: 20
    })

    if (data?.data) {
      return data.data.map(buildSiswaOption)
    }

    console.error('Failed to fetch siswa options:', error)
    return []
  }, [buildSiswaOption])

  const searchMapelOptions = useCallback(async (keyword = '') => {
    const { data, error } = await mapelService.getMapel({
      search: keyword || undefined,
      per_page: 20
    })

    if (data?.data) {
      return data.data.map(buildMapelOption)
    }

    console.error('Failed to fetch mapel options:', error)
    return []
  }, [buildMapelOption])

  const hydrateSelectedSiswaOption = useCallback(async (siswaId) => {
    if (!siswaId) {
      setSelectedSiswaOption(null)
      return
    }

    const { data } = await siswaService.getById(siswaId)
    const siswa = data?.data

    if (siswa) {
      setSelectedSiswaOption(buildSiswaOption(siswa))
      return
    }

    setSelectedSiswaOption({
      value: String(siswaId),
      label: `Siswa #${siswaId}`
    })
  }, [buildSiswaOption])

  const fetchRapor = async () => {
    setFetchingData(true)
    const { data, error } = await raporService.getById(id)
    if (data) {
      const rapor = data.data
      const siswaId = rapor.siswa?.id ? String(rapor.siswa.id) : ''

      setFormData({
        mst_siswa_id: siswaId,
        semester: rapor.semester ? String(rapor.semester) : '',
        tahun_ajaran_id: rapor.tahun_ajaran_id ? String(rapor.tahun_ajaran_id) : '',
        catatan_wali: rapor.catatan_wali || '',
        sakit: rapor.kehadiran?.sakit !== null && rapor.kehadiran?.sakit !== undefined ? String(rapor.kehadiran.sakit) : '',
        izin: rapor.kehadiran?.izin !== null && rapor.kehadiran?.izin !== undefined ? String(rapor.kehadiran.izin) : '',
        tanpa_keterangan: rapor.kehadiran?.tanpa_keterangan !== null && rapor.kehadiran?.tanpa_keterangan !== undefined ? String(rapor.kehadiran.tanpa_keterangan) : '',
      })

      if (rapor.siswa?.id) {
        setSelectedSiswaOption(buildSiswaOption(rapor.siswa))
      }

      if (rapor.detail && Array.isArray(rapor.detail)) {
        setDetails(rapor.detail.map(d => ({
          mst_mapel_id: d.mapel?.id ? String(d.mapel.id) : '',
          nilai_pengetahuan: d.nilai_pengetahuan !== null && d.nilai_pengetahuan !== undefined ? String(d.nilai_pengetahuan) : '',
          nilai_keterampilan: d.nilai_keterampilan !== null && d.nilai_keterampilan !== undefined ? String(d.nilai_keterampilan) : '',
          nilai_akhir: d.nilai_akhir !== null && d.nilai_akhir !== undefined ? String(d.nilai_akhir) : '',
          predikat: d.predikat || '',
          deskripsi: d.deskripsi || '',
        })))
        setSelectedMapelOptions(rapor.detail.map(d => (
          d.mapel?.id ? buildMapelOption(d.mapel) : null
        )))
      }
    } else {
      showError('Gagal mengambil data rapor')
      navigate('/akademik/rapor')
    }
    setFetchingData(false)
  }

  const handleChange = (e) => {
    const { name, value } = e.target
    setFormData(prev => ({ ...prev, [name]: value }))
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: null }))
    }
  }

  const handleDetailChange = (index, field, value) => {
    setDetails(prev => {
      const updated = [...prev]
      updated[index] = { ...updated[index], [field]: value }
      return updated
    })

    if (field === 'mst_mapel_id') {
      setSelectedMapelOptions(prev => {
        const updated = [...prev]
        if (!value) {
          updated[index] = null
        }
        return updated
      })
    }
  }

  const addDetail = () => {
    setDetails(prev => [...prev, {
      mst_mapel_id: '',
      nilai_pengetahuan: '',
      nilai_keterampilan: '',
      nilai_akhir: '',
      predikat: '',
      deskripsi: '',
    }])
    setSelectedMapelOptions(prev => [...prev, null])
  }

  const removeDetail = (index) => {
    setDetails(prev => prev.filter((_, i) => i !== index))
    setSelectedMapelOptions(prev => prev.filter((_, i) => i !== index))
  }

  useEffect(() => {
    if (formData.mst_siswa_id) {
      hydrateSelectedSiswaOption(formData.mst_siswa_id)
    } else {
      setSelectedSiswaOption(null)
    }
  }, [formData.mst_siswa_id, hydrateSelectedSiswaOption])

  const validate = () => {
    const newErrors = {}
    if (!formData.mst_siswa_id) newErrors.mst_siswa_id = 'Siswa wajib dipilih'
    if (!formData.semester) newErrors.semester = 'Semester wajib dipilih'
    if (!formData.tahun_ajaran_id) newErrors.tahun_ajaran_id = 'Tahun ajaran wajib dipilih'

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    if (!validate()) return

    setLoading(true)

    const submitData = {
      mst_siswa_id: parseInt(formData.mst_siswa_id),
      semester: formData.semester,
      tahun_ajaran_id: parseInt(formData.tahun_ajaran_id),
      catatan_wali: formData.catatan_wali || null,
      sakit: formData.sakit !== '' ? parseInt(formData.sakit) : null,
      izin: formData.izin !== '' ? parseInt(formData.izin) : null,
      tanpa_keterangan: formData.tanpa_keterangan !== '' ? parseInt(formData.tanpa_keterangan) : null,
    }

    // Only include details on create
    if (!isEditMode && details.length > 0) {
      submitData.details = details
        .filter(d => d.mst_mapel_id)
        .map(d => ({
          mst_mapel_id: parseInt(d.mst_mapel_id),
          nilai_pengetahuan: d.nilai_pengetahuan !== '' ? parseFloat(d.nilai_pengetahuan) : 0,
          nilai_keterampilan: d.nilai_keterampilan !== '' ? parseFloat(d.nilai_keterampilan) : null,
          nilai_akhir: d.nilai_akhir !== '' ? parseFloat(d.nilai_akhir) : null,
          predikat: d.predikat || null,
          deskripsi: d.deskripsi || null,
        }))
    }

    let result
    if (isEditMode) {
      result = await raporService.update(id, submitData)
    } else {
      result = await raporService.create(submitData)
    }

    const { error } = result

    if (!error) {
      showSuccess(`Rapor berhasil ${isEditMode ? 'diperbarui' : 'ditambahkan'}!`)
      navigate('/akademik/rapor')
    } else {
      console.error(error)
      if (error.errors) {
        setErrors(error.errors)
      } else {
        showError(`Gagal ${isEditMode ? 'memperbarui' : 'menambahkan'} rapor`)
      }
    }
    setLoading(false)
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="secondary" onClick={() => navigate('/akademik/rapor')}>
          <ArrowLeft size={18} className="mr-2" />
          Kembali
        </Button>
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
          {isEditMode ? 'Edit Rapor' : 'Tambah Rapor Baru'}
        </h1>
      </div>

      <Card>
        {fetchingData ? (
          <div className="flex items-center justify-center h-64">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="p-6 space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Siswa */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Siswa <span className="text-red-500">*</span>
                </label>
                <SearchableSelect
                  name="mst_siswa_id"
                  value={formData.mst_siswa_id}
                  onChange={handleChange}
                  options={selectedSiswaOption ? [selectedSiswaOption] : []}
                  loadOptions={searchSiswaOptions}
                  placeholder="Pilih siswa"
                  searchPlaceholder="Cari siswa berdasarkan nama atau NIS..."
                  noOptionsText="Tidak ada siswa yang cocok"
                  error={errors.mst_siswa_id}
                />
              </div>

              {/* Semester */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Semester <span className="text-red-500">*</span>
                </label>
                <SearchableSelect
                  name="semester"
                  value={formData.semester}
                  onChange={handleChange}
                  options={semesterOptions}
                  placeholder="Pilih semester"
                  error={errors.semester}
                />
              </div>

              {/* Tahun Ajaran */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Tahun Ajaran <span className="text-red-500">*</span>
                </label>
                <SearchableSelect
                  name="tahun_ajaran_id"
                  value={formData.tahun_ajaran_id}
                  onChange={handleChange}
                  options={tahunAjaranOptions}
                  placeholder="Pilih tahun ajaran"
                  error={errors.tahun_ajaran_id}
                />
              </div>

              {/* Catatan Wali */}
              <div className="md:col-span-2">
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Catatan Wali Kelas
                </label>
                <textarea
                  name="catatan_wali"
                  value={formData.catatan_wali}
                  onChange={handleChange}
                  placeholder="Masukkan catatan wali kelas"
                  rows={3}
                  className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white focus:ring-2 focus:ring-primary-500 focus:outline-none resize-y"
                />
                {errors.catatan_wali && (
                  <p className="mt-1 text-sm text-red-500">{errors.catatan_wali}</p>
                )}
              </div>

              {/* Kehadiran */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Sakit (hari)
                </label>
                <Input
                  type="number"
                  name="sakit"
                  value={formData.sakit}
                  onChange={handleChange}
                  placeholder="0"
                  min="0"
                  error={errors.sakit}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Izin (hari)
                </label>
                <Input
                  type="number"
                  name="izin"
                  value={formData.izin}
                  onChange={handleChange}
                  placeholder="0"
                  min="0"
                  error={errors.izin}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Tanpa Keterangan (hari)
                </label>
                <Input
                  type="number"
                  name="tanpa_keterangan"
                  value={formData.tanpa_keterangan}
                  onChange={handleChange}
                  placeholder="0"
                  min="0"
                  error={errors.tanpa_keterangan}
                />
              </div>
            </div>

            {/* Detail Nilai (only on create) */}
            {!isEditMode && (
              <div className="border-t border-gray-200 dark:border-gray-700 pt-6">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="text-lg font-semibold text-gray-900 dark:text-white">Detail Nilai per Mapel</h3>
                  <Button type="button" variant="secondary" onClick={addDetail}>
                    <Plus size={16} className="mr-1" />
                    Tambah Mapel
                  </Button>
                </div>

                {details.length === 0 ? (
                  <p className="text-sm text-gray-500 dark:text-gray-400">Belum ada detail nilai. Klik "Tambah Mapel" untuk menambahkan.</p>
                ) : (
                  <div className="space-y-4">
                    {details.map((detail, index) => (
                      <div key={index} className="p-4 border border-gray-200 dark:border-gray-700 rounded-lg">
                        <div className="flex items-center justify-between mb-3">
                          <span className="text-sm font-medium text-gray-700 dark:text-gray-300">Mapel #{index + 1}</span>
                          <button
                            type="button"
                            onClick={() => removeDetail(index)}
                            className="text-red-500 hover:text-red-700"
                          >
                            <Trash2 size={16} />
                          </button>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                          <div>
                            <label className="block text-xs text-gray-500 dark:text-gray-400 mb-1">Mata Pelajaran</label>
                            <SearchableSelect
                              name={`detail_mapel_${index}`}
                              value={detail.mst_mapel_id}
                              onChange={(e) => handleDetailChange(index, 'mst_mapel_id', e.target.value)}
                              options={selectedMapelOptions[index] ? [selectedMapelOptions[index]] : []}
                              loadOptions={async (keyword) => {
                                const options = await searchMapelOptions(keyword)
                                const selectedOption = options.find(
                                  (option) => String(option.value) === String(detail.mst_mapel_id)
                                )

                                if (selectedOption) {
                                  setSelectedMapelOptions(prev => {
                                    const updated = [...prev]
                                    updated[index] = selectedOption
                                    return updated
                                  })
                                }

                                return options
                              }}
                              placeholder="Pilih mapel"
                              searchPlaceholder="Cari mapel berdasarkan kode atau nama..."
                              noOptionsText="Tidak ada mapel yang cocok"
                            />
                          </div>
                          <div>
                            <label className="block text-xs text-gray-500 dark:text-gray-400 mb-1">Nilai Pengetahuan</label>
                            <Input
                              type="number"
                              value={detail.nilai_pengetahuan}
                              onChange={(e) => handleDetailChange(index, 'nilai_pengetahuan', e.target.value)}
                              placeholder="0-100"
                              min="0"
                              max="100"
                            />
                          </div>
                          <div>
                            <label className="block text-xs text-gray-500 dark:text-gray-400 mb-1">Nilai Keterampilan</label>
                            <Input
                              type="number"
                              value={detail.nilai_keterampilan}
                              onChange={(e) => handleDetailChange(index, 'nilai_keterampilan', e.target.value)}
                              placeholder="0-100"
                              min="0"
                              max="100"
                            />
                          </div>
                          <div>
                            <label className="block text-xs text-gray-500 dark:text-gray-400 mb-1">Nilai Akhir</label>
                            <Input
                              type="number"
                              value={detail.nilai_akhir}
                              onChange={(e) => handleDetailChange(index, 'nilai_akhir', e.target.value)}
                              placeholder="0-100"
                              min="0"
                              max="100"
                            />
                          </div>
                          <div>
                            <label className="block text-xs text-gray-500 dark:text-gray-400 mb-1">Predikat</label>
                            <Input
                              type="text"
                              value={detail.predikat}
                              onChange={(e) => handleDetailChange(index, 'predikat', e.target.value)}
                              placeholder="A/B/C/D"
                              maxLength={2}
                            />
                          </div>
                          <div>
                            <label className="block text-xs text-gray-500 dark:text-gray-400 mb-1">Deskripsi</label>
                            <Input
                              type="text"
                              value={detail.deskripsi}
                              onChange={(e) => handleDetailChange(index, 'deskripsi', e.target.value)}
                              placeholder="Deskripsi nilai"
                            />
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}

            <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
              <Button type="button" variant="secondary" onClick={() => navigate('/akademik/rapor')}>
                Batal
              </Button>
              <Button type="submit" disabled={loading}>
                <Save size={18} className="mr-2" />
                {loading ? 'Menyimpan...' : 'Simpan'}
              </Button>
            </div>
          </form>
        )}
      </Card>
    </div>
  )
}

export default RaporForm

import { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ArrowLeft, Save } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import Input from '../../../components/ui/Input'
import { referenceAdminService } from '../services/referenceAdminService'
import { showSuccess, showError } from '../../../utils/sweetalert'

const ReferenceForm = () => {
  const { id } = useParams()
  const navigate = useNavigate()
  const isEditMode = !!id

  const [loading, setLoading] = useState(false)
  const [fetchingData, setFetchingData] = useState(false)
  const [formData, setFormData] = useState({
    kategori: '',
    kode: '',
    nama: '',
    urutan: 0,
  })
  const [errors, setErrors] = useState({})

  useEffect(() => {
    if (isEditMode) fetchReference()
  }, [id])

  const fetchReference = async () => {
    setFetchingData(true)
    const { data, error } = await referenceAdminService.getById(id)
    if (data) {
      const ref = data.data
      setFormData({
        kategori: ref.kategori || '',
        kode: ref.kode || '',
        nama: ref.nama || '',
        urutan: ref.urutan || 0,
      })
    } else {
      showError('Gagal mengambil data referensi')
      navigate('/admin/references')
    }
    setFetchingData(false)
  }

  const handleChange = (e) => {
    const { name, value } = e.target
    setFormData(prev => ({ ...prev, [name]: name === 'urutan' ? parseInt(value) || 0 : value }))
    if (errors[name]) setErrors(prev => ({ ...prev, [name]: null }))
  }

  const validate = () => {
    const newErrors = {}
    if (!formData.kategori) newErrors.kategori = 'Kategori wajib diisi'
    if (!formData.kode) newErrors.kode = 'Kode wajib diisi'
    if (!formData.nama) newErrors.nama = 'Nama wajib diisi'
    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    if (!validate()) return
    setLoading(true)

    const result = isEditMode
      ? await referenceAdminService.update(id, formData)
      : await referenceAdminService.create(formData)

    const { error } = result
    if (!error) {
      showSuccess(`Referensi berhasil ${isEditMode ? 'diperbarui' : 'ditambahkan'}!`)
      navigate('/admin/references')
    } else {
      if (error.errors) setErrors(error.errors)
      else showError(`Gagal ${isEditMode ? 'memperbarui' : 'menambahkan'} referensi`)
    }
    setLoading(false)
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="secondary" onClick={() => navigate('/admin/references')}>
          <ArrowLeft size={18} className="mr-2" /> Kembali
        </Button>
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
          {isEditMode ? 'Edit Referensi' : 'Tambah Referensi Baru'}
        </h1>
      </div>

      <Card>
        {fetchingData ? (
          <div className="flex items-center justify-center h-64">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="p-6 space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Kategori <span className="text-red-500">*</span>
                </label>
                <Input name="kategori" value={formData.kategori} onChange={handleChange} placeholder="Contoh: jenis_kelamin" error={errors.kategori} />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Kode <span className="text-red-500">*</span>
                </label>
                <Input name="kode" value={formData.kode} onChange={handleChange} placeholder="Contoh: L" error={errors.kode} />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Nama <span className="text-red-500">*</span>
                </label>
                <Input name="nama" value={formData.nama} onChange={handleChange} placeholder="Contoh: Laki-Laki" error={errors.nama} />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Urutan</label>
                <Input type="number" name="urutan" value={formData.urutan} onChange={handleChange} placeholder="0" error={errors.urutan} />
              </div>
            </div>

            <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
              <Button type="button" variant="secondary" onClick={() => navigate('/admin/references')}>Batal</Button>
              <Button type="submit" disabled={loading}>
                <Save size={18} className="mr-2" /> {loading ? 'Menyimpan...' : 'Simpan'}
              </Button>
            </div>
          </form>
        )}
      </Card>
    </div>
  )
}

export default ReferenceForm

import { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ArrowLeft, Edit, Trash2, Key, Shield } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import { permissionService } from '../services/rolesService'
import { showDeleteConfirm, showSuccess, showError } from '../../../utils/sweetalert'

const PermissionsDetail = () => {
  const { id } = useParams()
  const navigate = useNavigate()

  const [loading, setLoading] = useState(false)
  const [permission, setPermission] = useState(null)

  useEffect(() => {
    fetchPermission()
  }, [id])

  const fetchPermission = async () => {
    setLoading(true)
    const { data, error } = await permissionService.getById(id)
    if (data) {
      setPermission(data.data)
    } else {
      showError('Gagal mengambil data permission')
      navigate('/admin/permissions')
    }
    setLoading(false)
  }

  const handleDelete = async () => {
    const label = `Permission "${permission.name || ''}"`
    const result = await showDeleteConfirm(label)
    if (result.isConfirmed) {
      const { error } = await permissionService.delete(permission.id)
      if (!error) {
        showSuccess(`${label} berhasil dihapus!`)
        navigate('/admin/permissions')
      } else {
        showError('Gagal menghapus permission')
      }
    }
  }

  const formatDate = (dateString) => {
    if (!dateString) return '-'
    const date = new Date(dateString)
    return date.toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' })
  }

  if (loading || !permission) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
        <div className="flex items-center gap-4">
          <Button variant="secondary" onClick={() => navigate('/admin/permissions')}>
            <ArrowLeft size={18} className="mr-2" />
            Kembali
          </Button>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Detail Permission</h1>
        </div>
        <div className="flex gap-3">
          <Button variant="warning" onClick={() => navigate(`/admin/permissions/${id}/edit`)}>
            <Edit size={18} className="mr-2" />
            Edit
          </Button>
          <Button variant="danger" onClick={handleDelete}>
            <Trash2 size={18} className="mr-2" />
            Hapus
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {/* Summary Card */}
        <div className="md:col-span-1">
          <Card>
            <div className="p-6 text-center">
              <div className="w-24 h-24 bg-gray-200 dark:bg-gray-700 rounded-full mx-auto mb-4 flex items-center justify-center">
                <Key size={48} className="text-gray-400" />
              </div>
              <h2 className="text-lg font-bold text-gray-900 dark:text-white mb-2">
                {permission.name || '-'}
              </h2>

              <div className="mt-6 border-t border-gray-200 dark:border-gray-700 pt-4 text-left space-y-3">
                <div className="flex justify-between">
                  <span className="text-gray-500 dark:text-gray-400">ID</span>
                  <span className="font-medium text-gray-900 dark:text-white">{permission.id}</span>
