export default SemesterForm

import { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ArrowLeft, Save } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import Input from '../../../components/ui/Input'
import FileUpload from '../../../components/ui/FileUpload'
import { siswaService } from '../services/siswaService'
import { kelasService } from '../../kelas/services/kelasService'
import { showSuccess, showError } from '../../../utils/sweetalert'
import { useReferenceOptions } from '../../../hooks/useReferenceOptions'
import { normalizeReferenceCode, safeParseInt } from '../../../utils/referenceUtils'

const GOLONGAN_DARAH_OPTIONS = [
  { value: 'A', label: 'A' },
  { value: 'B', label: 'B' },
  { value: 'AB', label: 'AB' },
  { value: 'O', label: 'O' }
]

const STATUS_OPTIONS = [
  { value: 'Aktif', label: 'Aktif' },
  { value: 'Lulus', label: 'Lulus' },
  { value: 'Keluar', label: 'Keluar' },
  { value: 'Pindah', label: 'Pindah' }
]

const SiswaForm = () => {
  const { id } = useParams()
  const navigate = useNavigate()
  const isEditMode = !!id

  const { options: jenisKelaminOptions } = useReferenceOptions('jenis_kelamin', [
    { value: '1', label: 'Laki-Laki' },
    { value: '2', label: 'Perempuan' },
  ])
  const { options: agamaOptions } = useReferenceOptions('agama', [
    { value: '1', label: 'Islam' },
    { value: '2', label: 'Kristen' },
    { value: '3', label: 'Katholik' },
    { value: '4', label: 'Hindu' },
    { value: '5', label: 'Budha' },
    { value: '6', label: 'Konghucu' },
    { value: '7', label: 'Kepercayaan' },
  ])

  const [loading, setLoading] = useState(false)
  const [fetchingData, setFetchingData] = useState(false)
  const [kelasOptions, setKelasOptions] = useState([])
  
  const [formData, setFormData] = useState({
    nis: '',
    nisn: '',
    nik: '',
    nama: '',
    jenis_kelamin: '1',
    tempat_lahir: '',
    tanggal_lahir: '',
    agama: '',
    alamat: '',
    email: '',
    no_hp: '',
    golongan_darah: '',
    tinggi_badan: '',
    berat_badan: '',
    tanggal_masuk: '',
    asal_sekolah: '',
    anak_ke: '',
    mst_kelas_id: '',
    status: 'Aktif',
    foto: ''
  })

  const [errors, setErrors] = useState({})

  useEffect(() => {
    let mounted = true
    const controller = new AbortController()

    const init = async () => {
      const { data: kelasData } = await kelasService.getAll({ signal: controller.signal })
      if (mounted && kelasData) setKelasOptions(kelasData.data || [])

      if (!isEditMode) return
      if (mounted) setFetchingData(true)
      const { data } = await siswaService.getById(id, { signal: controller.signal })
      if (!mounted) return
      if (data) {
        const siswa = data.data
        setFormData({
          nis: siswa.nis || '',
          nisn: siswa.nisn || '',
          nik: siswa.nik || '',
          nama: siswa.nama || '',
          // API kadang mengembalikan label; select memakai kode dari sys_references.
          jenis_kelamin: normalizeReferenceCode(siswa.jenis_kelamin, jenisKelaminOptions),
          tempat_lahir: siswa.tempat_lahir || '',
          tanggal_lahir: siswa.tanggal_lahir || '',
          agama: normalizeReferenceCode(siswa.agama, agamaOptions),
          alamat: siswa.alamat || '',
          email: siswa.email || '',
          no_hp: siswa.no_hp || '',
          golongan_darah: siswa.golongan_darah || '',
          tinggi_badan: siswa.tinggi_badan || '',
          berat_badan: siswa.berat_badan || '',
          tanggal_masuk: siswa.tanggal_masuk || '',
          asal_sekolah: siswa.asal_sekolah || '',
          anak_ke: siswa.anak_ke || '',
          mst_kelas_id: siswa.kelas?.id || '',
          status: siswa.status || 'Aktif',
          foto: siswa.foto || ''
        })
      } else {
        showError('Gagal mengambil data siswa')
        navigate('/siswa')
      }
      if (mounted) setFetchingData(false)
    }

    init().catch((err) => {
      if (err?.name !== 'CanceledError' && err?.name !== 'AbortError' && mounted) {
        showError('Gagal memuat data')
      }
    })

    return () => {
      mounted = false
      controller.abort()
    }
  }, [id, isEditMode, navigate])

  const handleChange = (e) => {
    const { name, value } = e.target
    setFormData(prev => ({ ...prev, [name]: value }))
    // Clear error when user types
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: null }))
    }
  }

  const validate = () => {
    const newErrors = {}
    if (!formData.nis) newErrors.nis = 'NIS wajib diisi'
    if (!formData.nama) newErrors.nama = 'Nama wajib diisi'
    if (!formData.mst_kelas_id) newErrors.mst_kelas_id = 'Kelas wajib dipilih'
    if (!formData.jenis_kelamin) newErrors.jenis_kelamin = 'Jenis kelamin wajib dipilih'
    
    if (formData.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
      newErrors.email = 'Format email tidak valid'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    
    if (!validate()) return

    setLoading(true)

    // Build submit data, converting empty strings to null for optional fields
    const submitData = {
      ...formData,
      // kirim sebagai kode numerik agar konsisten dengan sys_references
      jenis_kelamin: safeParseInt(formData.jenis_kelamin),
      agama: formData.agama ? safeParseInt(formData.agama) : null,
    
      nisn: formData.nisn || null,
      nik: formData.nik || null,
      tempat_lahir: formData.tempat_lahir || null,
      alamat: formData.alamat || null,
      email: formData.email || null,
      no_hp: formData.no_hp || null,
      golongan_darah: formData.golongan_darah || null,
      tinggi_badan: formData.tinggi_badan ? Number(formData.tinggi_badan) : null,
      berat_badan: formData.berat_badan ? Number(formData.berat_badan) : null,
      tanggal_masuk: formData.tanggal_masuk || null,
      asal_sekolah: formData.asal_sekolah || null,
      anak_ke: formData.anak_ke ? Number(formData.anak_ke) : null,
    }

    // Remove foto if empty
    if (!submitData.foto) {
      delete submitData.foto
    }

    let result
    
    if (isEditMode) {
      result = await siswaService.update(id, submitData)
    } else {
      result = await siswaService.create(submitData)
    }

    const { error } = result

    if (!error) {
      showSuccess(`Siswa berhasil ${isEditMode ? 'diperbarui' : 'ditambahkan'}!`)
      navigate('/siswa')
    } else {
      console.error(error)
      // Handle server-side validation errors
      if (error.errors) {
        setErrors(error.errors)
      } else {
        showError(`Gagal ${isEditMode ? 'memperbarui' : 'menambahkan'} siswa`)
      }
    }
    setLoading(false)
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="secondary" onClick={() => navigate('/siswa')}>
          <ArrowLeft size={18} className="mr-2" />
          Kembali
        </Button>
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
          {isEditMode ? 'Edit Siswa' : 'Tambah Siswa Baru'}
        </h1>
      </div>

      <Card>
        {fetchingData ? (
          <div className="flex items-center justify-center h-64">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="p-6 space-y-8">
            {/* Foto Profil */}
            <div>
              <FileUpload
                label="Foto Profil"
                onUpload={(path) => setFormData(prev => ({ ...prev, foto: path }))}
                accept="image/*"
                previewUrl={formData.foto}
              />
            </div>

            {/* Identitas */}
            <div>
              <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4 pb-2 border-b border-gray-200 dark:border-gray-700">
                Identitas Siswa
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {/* NIS */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    NIS <span className="text-red-500">*</span>
                  </label>
                  <Input
                    name="nis"
                    value={formData.nis}
                    onChange={handleChange}
                    placeholder="Nomor Induk Siswa"
                    error={errors.nis}
                  />
                </div>

                {/* NISN */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    NISN
                  </label>
                  <Input
                    name="nisn"
                    value={formData.nisn}
                    onChange={handleChange}
                    placeholder="Nomor Induk Siswa Nasional"
                    error={errors.nisn}
                  />
                </div>

                {/* NIK */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    NIK
                  </label>
                  <Input
                    name="nik"
                    value={formData.nik}
                    onChange={handleChange}
                    placeholder="Nomor Induk Kependudukan"
                    error={errors.nik}
                  />
                </div>
              </div>
            </div>

            {/* Data Pribadi */}
            <div>
              <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4 pb-2 border-b border-gray-200 dark:border-gray-700">
                Data Pribadi
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* Nama */}
                <div className="md:col-span-2">
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Nama Lengkap <span className="text-red-500">*</span>
                  </label>
                  <Input
                    name="nama"
                    value={formData.nama}
                    onChange={handleChange}
                    placeholder="Nama Lengkap Siswa"
                    error={errors.nama}
                  />
                </div>

                {/* Jenis Kelamin */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
