                {/* Berat Badan */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Berat Badan (kg)
                  </label>
                  <Input
                    type="number"
                    name="berat_badan"
                    value={formData.berat_badan}
                    onChange={handleChange}
                    placeholder="Contoh: 55"
                    min="0"
                    error={errors.berat_badan}
                  />
                </div>
              </div>
            </div>

            {/* Informasi Sekolah */}
            <div>
              <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4 pb-2 border-b border-gray-200 dark:border-gray-700">
                Informasi Sekolah
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* Kelas */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Kelas <span className="text-red-500">*</span>
                  </label>
                  <select
                    name="mst_kelas_id"
                    value={formData.mst_kelas_id}
                    onChange={handleChange}
                    className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm focus:border-primary-500 focus:outline-none focus:ring-1 focus:ring-primary-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
                  >
                    <option value="">Pilih Kelas</option>
                    {kelasOptions.map(kelas => (
                      <option key={kelas.id} value={kelas.id}>
                        {kelas.nama_kelas} - {kelas.tahun_ajaran}
                      </option>
                    ))}
                  </select>
                  {errors.mst_kelas_id && (
                    <p className="mt-1 text-sm text-red-500">
                      {Array.isArray(errors.mst_kelas_id) ? errors.mst_kelas_id[0] : errors.mst_kelas_id}
                    </p>
                  )}
                </div>

                {/* Status */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Status Siswa
                  </label>
                  <select
                    name="status"
                    value={formData.status}
                    onChange={handleChange}
                    className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm focus:border-primary-500 focus:outline-none focus:ring-1 focus:ring-primary-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
                  >
                    {STATUS_OPTIONS.map(option => (
                      <option key={option.value} value={option.value}>
                        {option.label}
                      </option>
                    ))}
                  </select>
                </div>

                {/* Tanggal Masuk */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Tanggal Masuk
                  </label>
                  <Input
                    type="date"
                    name="tanggal_masuk"
                    value={formData.tanggal_masuk}
                    onChange={handleChange}
                    error={errors.tanggal_masuk}
                  />
                </div>

                {/* Asal Sekolah */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Asal Sekolah
                  </label>
                  <Input
                    name="asal_sekolah"
                    value={formData.asal_sekolah}
                    onChange={handleChange}
                    placeholder="Nama Sekolah Asal"
                    error={errors.asal_sekolah}
                  />
                </div>
              </div>
            </div>

            <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
              <Button type="button" variant="secondary" onClick={() => navigate('/siswa')}>
                Batal
              </Button>
              <Button type="submit" disabled={loading}>
                <Save size={18} className="mr-2" />
                {loading ? 'Menyimpan...' : 'Simpan'}
              </Button>
            </div>
          </form>
        )}
      </Card>
    </div>
  )
}

export default SiswaForm

import { memo, useState, useMemo, useCallback, useRef, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import InfiniteGrid from '../../../components/ui/InfiniteGrid'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import { showDeleteConfirm, showSuccess, showError } from '../../../utils/sweetalert'
import { siswaService } from '../services/siswaService'

// Actions Menu Component
const ActionsMenu = memo(({ data, onDetail, onEdit, onDelete }) => {
  const [isOpen, setIsOpen] = useState(false)
  const [position, setPosition] = useState({ top: 0, left: 0 })
  const buttonRef = useRef(null)
  const menuRef = useRef(null)

  const handleAction = (action) => {
    setIsOpen(false)
    action()
  }

  const handleButtonClick = (e) => {
    e.stopPropagation()
    
    if (buttonRef.current) {
      const rect = buttonRef.current.getBoundingClientRect()
      setPosition({
        top: rect.bottom + window.scrollY,
        left: rect.right + window.scrollX - 192
      })
    }
    
    setIsOpen(!isOpen)
  }

  const handleClickOutside = (e) => {
    const isOutsideButton = buttonRef.current && !buttonRef.current.contains(e.target)
    const isOutsideMenu = !menuRef.current || !menuRef.current.contains(e.target)
    
    if (isOutsideButton && isOutsideMenu) {
      setIsOpen(false)
    }
  }

  // Handle click outside
  useEffect(() => {
    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside)
      return () => document.removeEventListener('mousedown', handleClickOutside)
    }
  }, [isOpen])

  return (
    <div className="relative">
      <button
        ref={buttonRef}
        onClick={handleButtonClick}
        className="p-1 hover:bg-gray-100 dark:hover:bg-gray-700 rounded"
        title="Actions"
      >
        <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="text-gray-600 dark:text-gray-400">
          <circle cx="12" cy="12" r="1"/><circle cx="12" cy="5" r="1"/><circle cx="12" cy="19" r="1"/>
        </svg>
      </button>
      
      {isOpen && (
        <div
          ref={menuRef}
          className="fixed w-48 bg-white dark:bg-gray-800 rounded-lg shadow-lg border border-gray-200 dark:border-gray-700 z-[10000]"
          style={{
            top: `${position.top}px`,
            left: `${position.left}px`
          }}
        >
          <div className="py-1">
            <button
              onClick={() => handleAction(onDetail)}
              className="w-full px-4 py-2 text-left text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center gap-2"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="text-blue-600">
                <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/>
              </svg>
              Detail
            </button>
            <button
              onClick={() => handleAction(onEdit)}
              className="w-full px-4 py-2 text-left text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center gap-2"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="text-yellow-600">
                <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/>
              </svg>
              Edit
            </button>
            <div className="border-t border-gray-200 dark:border-gray-700 my-1" />
            <button
              onClick={() => handleAction(onDelete)}
              className="w-full px-4 py-2 text-left text-sm text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 flex items-center gap-2"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/>
              </svg>
              Hapus
            </button>
          </div>
        </div>
      )}
    </div>
  )
})

const SiswaList = () => {
  const navigate = useNavigate()
  const gridRef = useRef(null)
  
  // Column definitions
  const columnDefs = useMemo(() => [
    { 
      field: 'nis', 
      headerName: 'NIS',
      sortable: true,
      filter: 'agTextColumnFilter',
      width: 120,
      minWidth: 100
    },
    { 
      field: 'nisn', 
      headerName: 'NISN',
      sortable: true,
      filter: 'agTextColumnFilter',
      width: 120,
      minWidth: 100,
      valueFormatter: (params) => params.value || '-'
    },
    { 
      field: 'nama', 
      headerName: 'Nama Lengkap',
      sortable: true,
      filter: 'agTextColumnFilter',
      flex: 1,
      minWidth: 180
    },
    {
      field: 'jenis_kelamin',
      headerName: 'Jenis Kelamin',
      sortable: true,
      filter: 'agTextColumnFilter',
      width: 140,
      minWidth: 120,
      cellRenderer: (params) => {
        const jk = params.value
        if (!jk) return '-'
        const isLaki = (jk === 'Laki-Laki' || jk === 'Laki-laki')
        const colorClass = isLaki
          ? 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400'
          : 'bg-pink-100 text-pink-800 dark:bg-pink-900/30 dark:text-pink-400'

        return (
          <span className={`px-2 py-1 rounded-full text-xs font-medium ${colorClass}`}>
            {jk}
          </span>
        )
      }
    },
    { 
      field: 'kelas', 
      headerName: 'Kelas',
      sortable: true,
      filter: 'agTextColumnFilter',
      width: 130,
      minWidth: 110,
      valueGetter: (params) => params.data?.kelas?.nama_kelas || '-',
      valueFormatter: (params) => params.value || '-'
    },
    { 
      field: 'status', 
      headerName: 'Status',
      sortable: true,
      filter: 'agTextColumnFilter',
      width: 120,
      minWidth: 100,
      cellRenderer: (params) => {
        const status = params.value
        if (!status) return '-'
        let colorClass = 'bg-gray-100 text-gray-800 dark:bg-gray-900/30 dark:text-gray-400'
        
        const statusLower = status.toLowerCase()
        if (statusLower === 'aktif') colorClass = 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400'
        else if (statusLower === 'lulus') colorClass = 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400'
        else if (statusLower === 'keluar') colorClass = 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400'
        else if (statusLower === 'pindah') colorClass = 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-400'

        return (
          <span className={`px-2 py-1 rounded-full text-xs font-medium ${colorClass}`}>
            {status}
          </span>
        )
      }
    },
    {
      headerName: 'Aksi',
      width: 80,
      minWidth: 80,
      maxWidth: 80,
      suppressSizeToFit: true,
      sortable: false,
      filter: false,
      cellRenderer: (params) => {
        return (
          <div className="h-full flex items-center justify-center">
            <ActionsMenu
              data={params.data}
              onDetail={() => navigate(`/siswa/${params.data.id}`)}
              onEdit={() => navigate(`/siswa/${params.data.id}/edit`)}
              onDelete={() => handleDelete(params.data)}
            />
          </div>
        )
      }
    }
  ], [navigate])

  // Default column definition
  const defaultColDef = useMemo(() => ({
    resizable: true,
  }), [])

  // Handle row click for navigation
  const handleRowClicked = useCallback((event) => {
    // Optional: navigate to detail on row click
    // navigate(`/siswa/${event.data.id}`)
  }, [navigate])

  // Handle delete
  const handleDelete = async (data) => {
    const result = await showDeleteConfirm(data.nama)
    if (result.isConfirmed) {
      const { error } = await siswaService.delete(data.id)
      if (!error) {
        showSuccess(`${data.nama} berhasil dihapus!`)
        // Refresh the grid
        if (gridRef.current?.refreshGrid) {
          gridRef.current.refreshGrid()
        }
      } else {
        showError('Gagal menghapus siswa')
      }
    }
  }

  // Handle refresh
  const handleRefresh = useCallback(() => {
    if (gridRef.current?.refreshGrid) {
      gridRef.current.refreshGrid()
    }
  }, [])

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Data Siswa</h1>
        <div className="flex flex-col sm:flex-row gap-3">
          <Button onClick={handleRefresh} variant="secondary" title="Refresh Data">
            <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="mr-2">
              <polyline points="23 4 23 10 17 10"/><polyline points="1 20 1 14 7 14"/><path d="M3.51 9a9 9 0 0 1 14.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0 0 20.49 15"/>
            </svg>
            Refresh
          </Button>
          <Button onClick={() => navigate('/siswa/create')}>
            <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="mr-2">
              <line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/>
            </svg>
            Tambah Siswa
          </Button>
        </div>
      </div>

      <Card>
        <InfiniteGrid
          ref={gridRef}
          endpoint="/siswa/"
          columnDefs={columnDefs}
          defaultColDef={defaultColDef}
          cacheBlockSize={20}
          paginationPageSize={20}
          paginationPageSizeSelector={[10, 20, 50, 100]}
          onRowClicked={handleRowClicked}
          height={600}
        />
      </Card>
    </div>
  )
}

export default SiswaList

import { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ArrowLeft, Edit, Trash2, BookOpen, HelpCircle, List, Star, CheckCircle } from 'lucide-react';
import Card from '../../../components/ui/Card';
import Button from '../../../components/ui/Button';
import { showSoal } from '../services/soalService';
import { showDeleteConfirm, showSuccess, showError } from '../../../utils/sweetalert';

const SoalDetail = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  
  const [loading, setLoading] = useState(true);
  const [soal, setSoal] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetchSoal();
  }, [id]);

  const fetchSoal = async () => {
    try {
      setLoading(true);
      const { data, error: apiError } = await showSoal(id);
      
      if (apiError) {
        setError('Gagal mengambil data soal');
        showError('Gagal mengambil data soal');
        navigate('/akademik/soals');
        return;
      }
      
      setSoal(data.data);
      setError(null);
    } catch (err) {
      setError('Terjadi kesalahan saat memuat data');
      showError('Terjadi kesalahan saat memuat data');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async () => {
    const result = await showDeleteConfirm(`Soal ID: ${soal.id}`);
    if (result.isConfirmed) {
      // Implement delete functionality if needed
      showSuccess('Soal berhasil dihapus!');
      navigate('/akademik/soals');
    }
  };

  const getTipeLabel = (tipe) => {
    const tipeMap = {
      1: 'Pilihan Ganda',
      2: 'Essay',
      3: 'Isian Singkat'
    };
    return tipeMap[tipe] || 'Tipe Tidak Diketahui';
  };

  const getKesulitanLabel = (tingkat) => {
    const tingkatMap = {
      1: 'Mudah',
      2: 'Sedang',
      3: 'Sulit'
    };
    return tingkatMap[tingkat] || tingkat;
  };

  const formatDate = (dateString) => {
    if (!dateString) return '-';
    const date = new Date(dateString);
    return date.toLocaleDateString('id-ID', {
      day: 'numeric',
      month: 'long',
      year: 'numeric'
    });
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex items-center justify-center h-64">
        <p className="text-red-500">{error}</p>
      </div>
    );
  }

  if (!soal) {
    return (
      <div className="flex items-center justify-center h-64">
        <p className="text-gray-500">Data soal tidak ditemukan</p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
        <div className="flex items-center gap-4">
          <Button variant="secondary" onClick={() => navigate('/akademik/soals')}>
            <ArrowLeft size={18} className="mr-2" />
            Kembali ke Daftar Soal
          </Button>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Detail Soal</h1>
        </div>
        <div className="flex gap-3">
          <Button variant="warning" onClick={() => navigate(`/akademik/soals/${id}/edit`)}>
            <Edit size={18} className="mr-2" />
            Edit Soal
          </Button>
          <Button variant="danger" onClick={handleDelete}>
            <Trash2 size={18} className="mr-2" />
            Hapus Soal
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left Column - Basic Info */}
        <div className="lg:col-span-1 space-y-6">
          <Card>
            <div className="p-6">
              <div className="flex items-center gap-4 mb-6">
                <div className="w-12 h-12 bg-indigo-100 dark:bg-indigo-900/30 rounded-lg flex items-center justify-center">
                  <HelpCircle size={24} className="text-indigo-600 dark:text-indigo-400" />
                </div>
                <div>
                  <h2 className="text-lg font-semibold text-gray-900 dark:text-white">Informasi Dasar</h2>
                  <p className="text-sm text-gray-500 dark:text-gray-400">Detail utama soal</p>
                </div>
              </div>
              
              <div className="space-y-4">
                <div>
                  <p className="text-xs text-gray-500 dark:text-gray-400">ID Soal</p>
                  <p className="font-medium text-gray-900 dark:text-white">{soal.id}</p>
                </div>
                
                <div>
                  <p className="text-xs text-gray-500 dark:text-gray-400">Tipe Soal</p>
                  <p className="font-medium text-gray-900 dark:text-white">
                    {getTipeLabel(soal.tipe)}
                  </p>
                </div>
                
                <div>
                  <p className="text-xs text-gray-500 dark:text-gray-400">Tingkat Kesulitan</p>
                  <div className="flex items-center gap-2">
                    <Star size={16} className={`${
                      soal.tingkat_kesulitan >= 1 
                        ? 'text-yellow-400 fill-yellow-400' 
                        : 'text-gray-300 dark:text-gray-600'
                    }`} />
                    <Star size={16} className={`${
                      soal.tingkat_kesulitan >= 2 
                        ? 'text-yellow-400 fill-yellow-400' 
                        : 'text-gray-300 dark:text-gray-600'
                    }`} />
                    <Star size={16} className={`${
                      soal.tingkat_kesulitan >= 3 
                        ? 'text-yellow-400 fill-yellow-400' 
                        : 'text-gray-300 dark:text-gray-600'
                    }`} />
                    <span className="font-medium text-gray-900 dark:text-white ml-1">
                      ({getKesulitanLabel(soal.tingkat_kesulitan)})
                    </span>
                  </div>
                </div>
                
                <div>
                  <p className="text-xs text-gray-500 dark:text-gray-400">Mata Pelajaran</p>
                  <p className="font-medium text-gray-900 dark:text-white">
                    {soal.mapel?.nama_mapel || '-'}
                  </p>
                </div>
              </div>
            </div>
          </Card>

          <Card>
            <div className="p-6">
              <div className="flex items-center gap-4 mb-6">
                <div className="w-12 h-12 bg-blue-100 dark:bg-blue-900/30 rounded-lg flex items-center justify-center">
                  <BookOpen size={24} className="text-blue-600 dark:text-blue-400" />
                </div>
                <div>
                  <h2 className="text-lg font-semibold text-gray-900 dark:text-white">Metadata</h2>
                  <p className="text-sm text-gray-500 dark:text-gray-400">Informasi tambahan</p>
                </div>
              </div>
              
              <div className="space-y-4">
                <div>
                  <p className="text-xs text-gray-500 dark:text-gray-400">Dibuat Pada</p>
                  <p className="font-medium text-gray-900 dark:text-white">
                    {formatDate(soal.created_at)}
                  </p>
                </div>
                
                <div>
                  <p className="text-xs text-gray-500 dark:text-gray-400">Terakhir Diperbarui</p>
                  <p className="font-medium text-gray-900 dark:text-white">
                    {formatDate(soal.updated_at)}
                  </p>
                </div>
              </div>
            </div>
          </Card>
        </div>

        {/* Right Column - Question and Options */}
        <div className="lg:col-span-2">
          <Card>
            <div className="p-6">
              <div className="flex items-center gap-4 mb-6">
                <div className="w-12 h-12 bg-purple-100 dark:bg-purple-900/30 rounded-lg flex items-center justify-center">
                  <HelpCircle size={24} className="text-purple-600 dark:text-purple-400" />
                </div>
                <div>
                  <h2 className="text-lg font-semibold text-gray-900 dark:text-white">Pertanyaan</h2>
                  <p className="text-sm text-gray-500 dark:text-gray-400">Detail pertanyaan soal</p>
                </div>
              </div>
              
              <div className="prose prose-sm max-w-none dark:prose-invert mb-8">
                <p className="text-gray-900 dark:text-white font-medium">{soal.pertanyaan}</p>
              </div>
              
              {/* Render options only for multiple choice */}
              {soal.tipe === 1 && soal.opsi && soal.opsi.length > 0 && (
                <div className="mt-8">
                  <div className="flex items-center gap-3 mb-4">
                    <List size={20} className="text-gray-500 dark:text-gray-400" />
                    <h3 className="text-md font-semibold text-gray-900 dark:text-white">Opsi Jawaban</h3>
                  </div>
                  
                  <div className="space-y-3">
                    {soal.opsi.map((opsi, index) => (
                      <div 
                        key={opsi.id} 
                        className={`p-4 rounded-lg border ${
                          opsi.is_benar
                            ? 'border-green-500 bg-green-50 dark:bg-green-900/20' 
                            : 'border-gray-200 dark:border-gray-700'
                        }`}
                      >
                        <div className="flex items-start gap-3">
                          <div className={`mt-0.5 flex-shrink-0 w-5 h-5 rounded-full flex items-center justify-center ${
                            opsi.is_benar
                              ? 'bg-green-500 text-white' 
                              : 'bg-gray-200 dark:bg-gray-700'
                          }`}>
                            {String.fromCharCode(65 + index)}
                          </div>
                          <div className="flex-1">
                            <p className="text-gray-900 dark:text-white">{opsi.opsi_teks}</p>
                            {opsi.is_benar && (
                              <div className="mt-2 flex items-center text-green-600 dark:text-green-400 text-sm">
                                <CheckCircle size={16} className="mr-1" />
                                Jawaban Benar
                              </div>
                            )}
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </Card>
        </div>
      </div>
    </div>
  );
};

export default SoalDetail;

import { useCallback, useEffect, useState } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ArrowLeft, Save, Plus, Trash2, Check } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import Input from '../../../components/ui/Input'
import SearchableSelect from '../../../components/ui/SearchableSelect'
import LexicalEditor from '../../../components/ui/LexicalEditor'
import '../../../components/ui/LexicalEditor.css'
import { showSoal, storeSoal, updateSoal } from '../services/soalService'
import { mapelService } from '../../mapel/services/mapelService'
import { ujianService } from '../../ujian/services/ujianService'
import { referenceService } from '../../../services/referenceService'
import { showSuccess, showError } from '../../../utils/sweetalert'

const TIPE_SOAL_FALLBACK = [
  { value: '1', label: 'Pilihan Ganda' },
  { value: '2', label: 'Essay' }
]

const TINGKAT_KESULITAN_FALLBACK = [
  { value: '1', label: 'Mudah' },
  { value: '2', label: 'Sedang' },
  { value: '3', label: 'Sulit' }
]

const SoalForm = () => {
  const { id } = useParams()
  const navigate = useNavigate()
  const isEditMode = !!id

  const [loading, setLoading] = useState(false)
  const [fetchingData, setFetchingData] = useState(false)
  const [selectedMapelOption, setSelectedMapelOption] = useState(null)
  const [selectedUjianOption, setSelectedUjianOption] = useState(null)
  const [tipeSoalOptions, setTipeSoalOptions] = useState(TIPE_SOAL_FALLBACK)
  const [tingkatKesulitanOptions, setTingkatKesulitanOptions] = useState(TINGKAT_KESULITAN_FALLBACK)
  
  const [formData, setFormData] = useState({
    pertanyaan: '',
    tipe: '',
    tingkat_kesulitan: '',
    mst_mapel_id: '',
    trx_ujian_id: '',
    bobot: 1,
    options: [
      { teks_opsi: '', is_jawaban: false },
      { teks_opsi: '', is_jawaban: false }
    ]
  })

  const [errors, setErrors] = useState({})

  const buildMapelOption = useCallback((mapel) => ({
    value: String(mapel.id),
    label: `${mapel.kode_mapel || mapel.kode || '-'} - ${mapel.nama_mapel || mapel.nama || `Mapel #${mapel.id}`}`
  }), [])

  const buildUjianOption = useCallback((ujian) => ({
    value: String(ujian.id),
    label: ujian.nama || `Ujian #${ujian.id}`
  }), [])

  useEffect(() => {
    fetchTipeSoalOptions()
    fetchTingkatKesulitanOptions()

    if (isEditMode) {
      fetchSoal()
    }
  }, [id])

  const searchMapelOptions = useCallback(async (keyword = '') => {
    try {
      const { data, error } = await mapelService.getMapel({
        search: keyword || undefined,
        per_page: 20
      })

      if (data?.data) {
        return data.data.map(buildMapelOption)
      }

      console.error('Failed to fetch mapel:', error)
      return []
    } catch (err) {
      console.error('Error fetching mapel options:', err)
      return []
    }
  }, [buildMapelOption])

  const searchUjianOptions = useCallback(async (keyword = '') => {
    try {
      const { data, error } = await ujianService.getAll({
        search: keyword || undefined,
        per_page: 20
      })

      if (data?.data) {
        const ujianList = Array.isArray(data.data) ? data.data : (data.data.data || [])
        return ujianList.map(buildUjianOption)
      }

      console.error('Failed to fetch ujian:', error)
      return []
    } catch (err) {
      console.error('Error fetching ujian options:', err)
      return []
    }
  }, [buildUjianOption])

  const fetchTipeSoalOptions = async () => {
    try {
      const { data, error } = await referenceService.getReferencesByCategory('tipe_soal')
      if (data && data.data) {
        const refs = Array.isArray(data.data) ? data.data : []
        if (refs.length > 0) {
          setTipeSoalOptions(refs.map(ref => ({
            value: String(ref.value ?? ref.id),
            label: ref.label ?? ref.nama ?? ref.name ?? String(ref.value ?? ref.id)
          })))
        }
      } else {
        console.error('Failed to fetch tipe_soal references:', error)
      }
    } catch (err) {
      console.error('Error fetching tipe_soal options:', err)
    }
  }

  const fetchTingkatKesulitanOptions = async () => {
    try {
      const { data, error } = await referenceService.getReferencesByCategory('tingkat_kesulitan')
      if (data && data.data) {
        const refs = Array.isArray(data.data) ? data.data : []
        if (refs.length > 0) {
          setTingkatKesulitanOptions(refs.map(ref => ({
            value: String(ref.value ?? ref.id),
            label: ref.label ?? ref.nama ?? ref.name ?? String(ref.value ?? ref.id)
          })))
        }
      } else {
        console.error('Failed to fetch tingkat_kesulitan references:', error)
      }
    } catch (err) {
      console.error('Error fetching tingkat_kesulitan options:', err)
    }
  }

  const fetchSoal = async () => {
    setFetchingData(true)
    const { data, error } = await showSoal(id)
    if (data) {
      const soal = data.data
      const mapelId = soal.mst_mapel_id ? String(soal.mst_mapel_id) : ''
      const ujianId = soal.trx_ujian_id ? String(soal.trx_ujian_id) : ''

      setFormData({
        pertanyaan: soal.pertanyaan || '',
        tipe: soal.tipe || '',
        tingkat_kesulitan: soal.tingkat_kesulitan || '',
        mst_mapel_id: mapelId,
        trx_ujian_id: ujianId,
        bobot: soal.bobot || 1,
        options: soal.opsi?.length > 0
          ? soal.opsi
          : [
              { teks_opsi: '', is_jawaban: false },
              { teks_opsi: '', is_jawaban: false }
            ]
      })

      if (soal.mapel?.id) {
        setSelectedMapelOption(buildMapelOption(soal.mapel))
      }

      if (soal.ujian?.id) {
        setSelectedUjianOption(buildUjianOption(soal.ujian))
      }
    } else {
      showError('Gagal mengambil data soal')
      navigate('/akademik/soals')
    }
    setFetchingData(false)
  }

  const handleChange = (e) => {
    const { name, value } = e.target
    setFormData(prev => ({ ...prev, [name]: value }))
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: null }))
    }
  }

  const handleMapelChange = (e) => {
    handleChange(e)
  }

  const handleOptionChange = (index, field, value) => {
    setFormData(prev => {
      const newOptions = [...prev.options]
      newOptions[index] = { ...newOptions[index], [field]: value }
      return { ...prev, options: newOptions }
    })
  }

  const addOption = () => {
    setFormData(prev => ({
      ...prev,
      options: [...prev.options, { teks_opsi: '', is_jawaban: false }]
    }))
  }

  const removeOption = (index) => {
    if (formData.options.length <= 2) return
    
    setFormData(prev => {
      const newOptions = [...prev.options]
      newOptions.splice(index, 1)
      return { ...prev, options: newOptions }
    })
  }

  const toggleJawaban = (index) => {
    setFormData(prev => {
      const newOptions = prev.options.map((option, i) => ({
        ...option,
        is_jawaban: i === index
      }))
      return { ...prev, options: newOptions }
    })
  }

  const validate = () => {
    const newErrors = {}
    
    if (!formData.pertanyaan.trim()) newErrors.pertanyaan = 'Pertanyaan wajib diisi'
    if (!formData.tipe) newErrors.tipe = 'Tipe soal wajib dipilih'
    if (!formData.tingkat_kesulitan) newErrors.tingkat_kesulitan = 'Tingkat kesulitan wajib dipilih'
    if (!formData.mst_mapel_id) newErrors.mst_mapel_id = 'Mata pelajaran wajib dipilih'
    if (!formData.trx_ujian_id) newErrors.trx_ujian_id = 'Ujian wajib dipilih'
    if (!formData.bobot && formData.bobot !== 0) newErrors.bobot = 'Bobot wajib diisi'
    
    // Validate options only for multiple choice
    if (formData.tipe === '1') {
      formData.options.forEach((option, index) => {
        if (!option.teks_opsi.trim()) {
          newErrors[`option_${index}`] = 'Teks opsi tidak boleh kosong'
        }
      })
      
      const hasJawaban = formData.options.some(opt => opt.is_jawaban)
      if (!hasJawaban) {
        newErrors.options = 'Pilih setidaknya satu jawaban yang benar'
      }
    }
    
    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    
    if (!validate()) return

    setLoading(true)
    
    const submitData = {
      pertanyaan: formData.pertanyaan,
      tipe: formData.tipe,
      tingkat_kesulitan: formData.tingkat_kesulitan,
      mst_mapel_id: formData.mst_mapel_id,
      trx_ujian_id: formData.trx_ujian_id,
      bobot: formData.bobot,
      options: formData.tipe === '1' ? formData.options : []
    }

    let result
    
    if (isEditMode) {
      result = await updateSoal(id, submitData)
    } else {
      result = await storeSoal(submitData)
    }

    const { error } = result

    if (!error) {
      showSuccess(`Soal berhasil ${isEditMode ? 'diperbarui' : 'ditambahkan'}!`)
      navigate('/akademik/soals')
    } else {
      if (error.errors) {
        setErrors(error.errors)
      } else {
        showError(`Gagal ${isEditMode ? 'memperbarui' : 'menambahkan'} soal`)
      }
    }
    setLoading(false)
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="secondary" onClick={() => navigate('/akademik/soals')}>
          <ArrowLeft size={18} className="mr-2" />
          Kembali
        </Button>
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
          {isEditMode ? 'Edit Soal' : 'Tambah Soal Baru'}
        </h1>
      </div>

      <Card>
        {fetchingData ? (
          <div className="flex items-center justify-center h-64">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="p-6 space-y-6">
            <div className="grid grid-cols-1 gap-6">
              {/* Pertanyaan */}
              <div>
                <LexicalEditor
                  label="Pertanyaan"
                  required
                  value={formData.pertanyaan}
                  onChange={(html) => setFormData(prev => ({ ...prev, pertanyaan: html }))}
                  placeholder="Tulis pertanyaan..."
                  minHeight="150px"
                />
                {errors.pertanyaan && <p className="mt-1 text-sm text-red-500">{errors.pertanyaan}</p>}
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {/* Tipe Soal */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Tipe Soal <span className="text-red-500">*</span>
                  </label>
                  <select
                    name="tipe"
                    value={formData.tipe}
                    onChange={handleChange}
                    className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm focus:border-primary-500 focus:outline-none focus:ring-1 focus:ring-primary-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
                  >
                    <option value="">Pilih tipe soal</option>
                    {tipeSoalOptions.map(option => (
                      <option key={option.value} value={option.value}>
                        {option.label}
                      </option>
                    ))}
                  </select>
                  {errors.tipe && <p className="mt-1 text-sm text-red-500">{errors.tipe}</p>}
                </div>

                {/* Tingkat Kesulitan */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Tingkat Kesulitan <span className="text-red-500">*</span>
                  </label>
                  <select
                    name="tingkat_kesulitan"
                    value={formData.tingkat_kesulitan}
                    onChange={handleChange}
                    className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm focus:border-primary-500 focus:outline-none focus:ring-1 focus:ring-primary-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
                  >
                    <option value="">Pilih tingkat kesulitan</option>
                    {tingkatKesulitanOptions.map(option => (
                      <option key={option.value} value={option.value}>
                        {option.label}
                      </option>
                    ))}
                  </select>
                  {errors.tingkat_kesulitan && <p className="mt-1 text-sm text-red-500">{errors.tingkat_kesulitan}</p>}
                </div>

                {/* Mata Pelajaran */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Mata Pelajaran <span className="text-red-500">*</span>
                  </label>
                  <SearchableSelect
                    options={selectedMapelOption ? [selectedMapelOption] : []}
                    value={formData.mst_mapel_id}
                    name="mst_mapel_id"
                    onChange={handleMapelChange}
                    loadOptions={searchMapelOptions}
                    placeholder="Pilih mata pelajaran"
                    searchPlaceholder="Cari mata pelajaran..."
                    noOptionsText="Tidak ada mata pelajaran yang cocok"
                    error={errors.mst_mapel_id}
                  />
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* Ujian */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Ujian <span className="text-red-500">*</span>
                  </label>
                  <SearchableSelect
                    options={selectedUjianOption ? [selectedUjianOption] : []}
                    value={formData.trx_ujian_id}
                    name="trx_ujian_id"
                    onChange={handleChange}
                    loadOptions={searchUjianOptions}
                    placeholder="Pilih ujian"
                    searchPlaceholder="Cari ujian..."
                    noOptionsText="Tidak ada ujian yang cocok"
                    error={errors.trx_ujian_id}
                  />
                </div>

                {/* Bobot */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Bobot <span className="text-red-500">*</span>
                  </label>
                  <Input
                    type="number"
                    name="bobot"
                    value={formData.bobot}
                    onChange={handleChange}
                    placeholder="Masukkan bobot soal"
                    min="0"
                    error={errors.bobot}
                  />
                </div>
              </div>

              {/* Options Section - Only for Multiple Choice */}
              {(formData.tipe === '1' || formData.tipe === 1) && (
                <div className="pt-4 border-t border-gray-200 dark:border-gray-700">
                  <div className="flex justify-between items-center mb-4">
                    <h3 className="text-lg font-medium text-gray-900 dark:text-white">
                      Opsi Jawaban
                    </h3>
                    <Button 
                      type="button" 
                      size="sm"
                      onClick={addOption}
                    >
                      <Plus size={16} className="mr-1" />
                      Tambah Opsi
                    </Button>
                  </div>
                  
                  {errors.options && (
                    <p className="mb-3 text-sm text-red-500">{errors.options}</p>
                  )}
                  
                  <div className="space-y-3">
                    {formData.options.map((option, index) => (
                      <div key={index} className="flex items-start gap-3">
                        <div className="flex-1">
                          <div className="flex items-center gap-2 mb-1">
                            <span className="text-sm font-medium text-gray-700 dark:text-gray-300">
                              Opsi {index + 1}
                            </span>
                            {errors[`option_${index}`] && (
                              <span className="text-sm text-red-500">
                                {errors[`option_${index}`]}
                              </span>
                            )}
                          </div>
                          <div className="flex gap-2">
                            <Input
                              value={option.teks_opsi}
                              onChange={(e) => handleOptionChange(index, 'teks_opsi', e.target.value)}
                              placeholder="Teks opsi"
                              className="flex-1"
                            />
                            <button
                              type="button"
                              onClick={() => toggleJawaban(index)}
                              className={`flex items-center justify-center w-10 h-10 rounded-md border ${
                                option.is_jawaban 
                                  ? 'bg-green-100 border-green-500 text-green-700 dark:bg-green-900/30 dark:border-green-600 dark:text-green-400'
                                  : 'border-gray-300 dark:border-gray-600'
                              }`}
                              title={option.is_jawaban ? 'Jawaban benar' : 'Tandai sebagai jawaban benar'}
                            >
                              <Check size={18} />
                            </button>
                            <button
                              type="button"
                              onClick={() => removeOption(index)}
                              disabled={formData.options.length <= 2}
                              className="flex items-center justify-center w-10 h-10 rounded-md border border-gray-300 text-gray-500 hover:bg-red-50 hover:text-red-600 hover:border-red-300 dark:border-gray-600 dark:text-gray-400 dark:hover:bg-red-900/20 dark:hover:border-red-500 disabled:opacity-50 disabled:cursor-not-allowed"
                              title="Hapus opsi"
                            >
                              <Trash2 size={18} />
                            </button>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>

            <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
              <Button type="button" variant="secondary" onClick={() => navigate('/akademik/soals')}>
                Batal
              </Button>
              <Button type="submit" disabled={loading}>
                <Save size={18} className="mr-2" />
                {loading ? 'Menyimpan...' : 'Simpan'}
              </Button>
            </div>
          </form>
        )}
      </Card>
    </div>
  )
}

export default SoalForm

import { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ArrowLeft, Save } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import Input from '../../../components/ui/Input'
import SearchableSelect from '../../../components/ui/SearchableSelect'
import { kriteriaService } from '../services/spkService'
import { showSuccess, showError } from '../../../utils/sweetalert'

const TIPE_OPTIONS = [
  { value: 'benefit', label: 'Benefit' },
  { value: 'cost', label: 'Cost' },
]

const KriteriaForm = () => {
  const { id } = useParams()
  const navigate = useNavigate()
  const isEditMode = !!id

  const [loading, setLoading] = useState(false)
  const [fetchingData, setFetchingData] = useState(false)

  const [formData, setFormData] = useState({
    kode_kriteria: '',
    nama_kriteria: '',
    bobot: '',
    tipe: 'benefit',
  })

  const [errors, setErrors] = useState({})

  useEffect(() => {
    if (isEditMode) {
      fetchKriteria()
    }
  }, [id])

  const fetchKriteria = async () => {
    setFetchingData(true)
    const { data, error } = await kriteriaService.getById(id)
    if (data) {
      const kriteria = data.data
      setFormData({
        kode_kriteria: kriteria.kode_kriteria || '',
        nama_kriteria: kriteria.nama_kriteria || '',
        bobot: kriteria.bobot != null ? String(kriteria.bobot) : '',
        tipe: kriteria.tipe || 'benefit',
      })
    } else {
      showError('Gagal mengambil data kriteria')
      navigate('/spk/kriteria')
    }
    setFetchingData(false)
  }

  const handleChange = (e) => {
    const { name, value } = e.target
    setFormData(prev => ({ ...prev, [name]: value }))
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: null }))
    }
  }

  const validate = () => {
    const newErrors = {}
    if (!formData.kode_kriteria.trim()) newErrors.kode_kriteria = 'Kode kriteria wajib diisi'
    if (!formData.nama_kriteria.trim()) newErrors.nama_kriteria = 'Nama kriteria wajib diisi'
    if (!formData.bobot) newErrors.bobot = 'Bobot wajib diisi'
    if (!formData.tipe) newErrors.tipe = 'Tipe wajib dipilih'
    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    if (!validate()) return

    setLoading(true)

    const submitData = {
      kode_kriteria: formData.kode_kriteria,
      nama_kriteria: formData.nama_kriteria,
      bobot: parseFloat(formData.bobot),
      tipe: formData.tipe,
    }

    let result
    if (isEditMode) {
      result = await kriteriaService.update(id, submitData)
    } else {
      result = await kriteriaService.create(submitData)
    }

    const { error } = result

    if (!error) {
      showSuccess(`Kriteria berhasil ${isEditMode ? 'diperbarui' : 'ditambahkan'}!`)
      navigate('/spk/kriteria')
    } else {
      if (error.errors) {
        setErrors(error.errors)
      } else {
        showError(`Gagal ${isEditMode ? 'memperbarui' : 'menambahkan'} kriteria`)
      }
    }
    setLoading(false)
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="secondary" onClick={() => navigate('/spk/kriteria')}>
          <ArrowLeft size={18} className="mr-2" />
          Kembali
        </Button>
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
          {isEditMode ? 'Edit Kriteria' : 'Tambah Kriteria Baru'}
        </h1>
      </div>

      <Card>
        {fetchingData ? (
          <div className="flex items-center justify-center h-64">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="p-6 space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Kode Kriteria <span className="text-red-500">*</span>
                </label>
                <Input
                  type="text"
                  name="kode_kriteria"
                  value={formData.kode_kriteria}
                  onChange={handleChange}
                  placeholder="Masukkan kode kriteria (cth: C1)"
                  error={errors.kode_kriteria}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Nama Kriteria <span className="text-red-500">*</span>
                </label>
                <Input
                  type="text"
                  name="nama_kriteria"
                  value={formData.nama_kriteria}
                  onChange={handleChange}
                  placeholder="Masukkan nama kriteria"
                  error={errors.nama_kriteria}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Bobot <span className="text-red-500">*</span>
                </label>
                <Input
                  type="number"
                  name="bobot"
                  value={formData.bobot}
                  onChange={handleChange}
                  placeholder="Masukkan bobot (cth: 0.25)"
                  step="0.01"
                  error={errors.bobot}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Tipe <span className="text-red-500">*</span>
                </label>
                <SearchableSelect
                  name="tipe"
                  value={formData.tipe}
                  onChange={handleChange}
                  options={TIPE_OPTIONS}
                  placeholder="Pilih tipe kriteria"
                  error={errors.tipe}
                />
              </div>
            </div>

            <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
              <Button type="button" variant="secondary" onClick={() => navigate('/spk/kriteria')}>
                Batal
              </Button>
              <Button type="submit" disabled={loading}>
                <Save size={18} className="mr-2" />
                {loading ? 'Menyimpan...' : 'Simpan'}
              </Button>
            </div>
          </form>
        )}
      </Card>
    </div>
  )
}

export default KriteriaForm

import { useCallback, useEffect, useState } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ArrowLeft, Save } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import Input from '../../../components/ui/Input'
import SearchableSelect from '../../../components/ui/SearchableSelect'
import { penilaianService, kriteriaService } from '../services/spkService'
import { siswaService } from '../../siswa/services/siswaService'
import { showSuccess, showError } from '../../../utils/sweetalert'

const PenilaianForm = () => {
  const { id } = useParams()
  const navigate = useNavigate()
  const isEditMode = !!id

  const [loading, setLoading] = useState(false)
  const [fetchingData, setFetchingData] = useState(false)

  const [formData, setFormData] = useState({
    mst_siswa_id: '',
    spk_kriteria_id: '',
    nilai: '',
    tahun_ajaran_id: '',
  })

  const [errors, setErrors] = useState({})
  const [selectedSiswaOption, setSelectedSiswaOption] = useState(null)
  const [kriteriaOptions, setKriteriaOptions] = useState([])
  const [selectedKriteriaOption, setSelectedKriteriaOption] = useState(null)

  const buildSiswaOption = useCallback((siswa) => ({
    value: String(siswa.id),
    label: `${siswa.nis || '-'} - ${siswa.nama || `Siswa #${siswa.id}`}`
  }), [])

  const buildKriteriaOption = useCallback((kriteria) => ({
    value: String(kriteria.id),
    label: `${kriteria.kode_kriteria || '-'} - ${kriteria.nama_kriteria || `Kriteria #${kriteria.id}`}`
  }), [])

  const searchSiswaOptions = useCallback(async (keyword = '') => {
    const { data } = await siswaService.getAll({
      search: keyword || undefined,
      per_page: 20
    })

    const list = data?.data || []
    return list.map(buildSiswaOption)
  }, [buildSiswaOption])

  const fetchKriteriaOptions = useCallback(async () => {
    const { data } = await kriteriaService.getAll({ per_page: 20 })
    const list = data?.data || []
    setKriteriaOptions(list.map(buildKriteriaOption))
  }, [buildKriteriaOption])

  const hydrateSelectedSiswaOption = useCallback(async (siswaId) => {
    if (!siswaId) {
      setSelectedSiswaOption(null)
      return
    }

    const { data } = await siswaService.getById(siswaId)
    const siswa = data?.data

    if (siswa) {
      setSelectedSiswaOption(buildSiswaOption(siswa))
    }
  }, [buildSiswaOption])

  const hydrateSelectedKriteriaOption = useCallback(async (kriteriaId) => {
    if (!kriteriaId) {
      setSelectedKriteriaOption(null)
      return
    }

    const { data } = await kriteriaService.getById(kriteriaId)
    const kriteria = data?.data

    if (kriteria) {
      const option = buildKriteriaOption(kriteria)
      setSelectedKriteriaOption(option)
      setKriteriaOptions((prev) => {
        const exists = prev.some((item) => String(item.value) === String(option.value))
        return exists ? prev : [option, ...prev]
      })
    }
  }, [buildKriteriaOption])

  useEffect(() => {
    fetchKriteriaOptions()
    if (isEditMode) {
      fetchPenilaian()
    }
  }, [id])

  useEffect(() => {
    if (formData.mst_siswa_id) {
      hydrateSelectedSiswaOption(formData.mst_siswa_id)
    } else {
      setSelectedSiswaOption(null)
    }
  }, [formData.mst_siswa_id, hydrateSelectedSiswaOption])

  useEffect(() => {
    if (formData.spk_kriteria_id) {
      hydrateSelectedKriteriaOption(formData.spk_kriteria_id)
    } else {
      setSelectedKriteriaOption(null)
    }
  }, [formData.spk_kriteria_id, hydrateSelectedKriteriaOption])

  const fetchPenilaian = async () => {
    setFetchingData(true)
    const { data, error } = await penilaianService.getById(id)
    if (data) {
      const penilaian = data.data
      setFormData({
        mst_siswa_id: penilaian.mst_siswa_id ? String(penilaian.mst_siswa_id) : '',
        spk_kriteria_id: penilaian.spk_kriteria_id ? String(penilaian.spk_kriteria_id) : '',
        nilai: penilaian.nilai != null ? String(penilaian.nilai) : '',
        tahun_ajaran_id: penilaian.tahun_ajaran_id ? String(penilaian.tahun_ajaran_id) : '',
      })
    } else {
      showError('Gagal mengambil data penilaian')
      navigate('/spk/penilaian')
    }
    setFetchingData(false)
  }

  const handleChange = (e) => {
    const { name, value } = e.target
    setFormData(prev => ({ ...prev, [name]: value }))
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: null }))
    }
  }

  const validate = () => {
    const newErrors = {}
    if (!formData.mst_siswa_id) newErrors.mst_siswa_id = 'Siswa wajib dipilih'
    if (!formData.spk_kriteria_id) newErrors.spk_kriteria_id = 'Kriteria wajib dipilih'
    if (!formData.nilai) newErrors.nilai = 'Nilai wajib diisi'
    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    if (!validate()) return

    setLoading(true)

    const submitData = {
      mst_siswa_id: parseInt(formData.mst_siswa_id),
      spk_kriteria_id: parseInt(formData.spk_kriteria_id),
      nilai: parseFloat(formData.nilai),
      ...(formData.tahun_ajaran_id && { tahun_ajaran_id: parseInt(formData.tahun_ajaran_id) }),
    }

    let result
    if (isEditMode) {
      result = await penilaianService.update(id, submitData)
    } else {
      result = await penilaianService.create(submitData)
    }

    const { error } = result

    if (!error) {
      showSuccess(`Penilaian berhasil ${isEditMode ? 'diperbarui' : 'ditambahkan'}!`)
      navigate('/spk/penilaian')
    } else {
      if (error.errors) {
        setErrors(error.errors)
      } else {
        showError(`Gagal ${isEditMode ? 'memperbarui' : 'menambahkan'} penilaian`)
      }
    }
    setLoading(false)
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="secondary" onClick={() => navigate('/spk/penilaian')}>
          <ArrowLeft size={18} className="mr-2" />
          Kembali
        </Button>
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
          {isEditMode ? 'Edit Penilaian' : 'Tambah Penilaian Baru'}
        </h1>
      </div>

      <Card>
        {fetchingData ? (
          <div className="flex items-center justify-center h-64">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="p-6 space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Siswa <span className="text-red-500">*</span>
                </label>
                <SearchableSelect
                  name="mst_siswa_id"
                  value={formData.mst_siswa_id}
                  onChange={handleChange}
                  options={selectedSiswaOption ? [selectedSiswaOption] : []}
                  loadOptions={searchSiswaOptions}
                  placeholder="Pilih siswa"
                  searchPlaceholder="Cari siswa berdasarkan nama atau NIS..."
                  noOptionsText="Tidak ada siswa yang cocok"
                  error={errors.mst_siswa_id}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Kriteria <span className="text-red-500">*</span>
                </label>
                <SearchableSelect
                  name="spk_kriteria_id"
                  value={formData.spk_kriteria_id}
                  onChange={handleChange}
                  options={selectedKriteriaOption ? [selectedKriteriaOption, ...kriteriaOptions] : kriteriaOptions}
                  placeholder="Pilih kriteria"
                  searchPlaceholder="Cari kriteria..."
                  error={errors.spk_kriteria_id}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Nilai <span className="text-red-500">*</span>
                </label>
                <Input
                  type="number"
                  name="nilai"
                  value={formData.nilai}
                  onChange={handleChange}
                  placeholder="Masukkan nilai"
                  step="0.01"
                  error={errors.nilai}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Tahun Ajaran ID
                </label>
                <Input
                  type="number"
                  name="tahun_ajaran_id"
                  value={formData.tahun_ajaran_id}
                  onChange={handleChange}
                  placeholder="ID Tahun Ajaran (opsional)"
                  error={errors.tahun_ajaran_id}
                />
              </div>
            </div>

            <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
              <Button type="button" variant="secondary" onClick={() => navigate('/spk/penilaian')}>
                Batal
              </Button>
              <Button type="submit" disabled={loading}>
                <Save size={18} className="mr-2" />
                {loading ? 'Menyimpan...' : 'Simpan'}
              </Button>
            </div>
          </form>
        )}
      </Card>
    </div>
  )
}

export default PenilaianForm

import { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ArrowLeft, Save } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import Input from '../../../components/ui/Input'
import SearchableSelect from '../../../components/ui/SearchableSelect'
import { tarifSppService } from '../services/sppService'
import { kelasService } from '../../kelas/services/kelasService'
import { tahunAjaranService } from '../../tahun-ajaran/services/tahunAjaranService'
import { showSuccess, showError } from '../../../utils/sweetalert'

const TarifSppForm = () => {
  const { id } = useParams()
  const navigate = useNavigate()
  const isEditMode = !!id

  const [loading, setLoading] = useState(false)
  const [fetchingData, setFetchingData] = useState(false)

  const [formData, setFormData] = useState({
    mst_kelas_id: '',
    tahun_ajaran_id: '',
    nominal: '',
    keterangan: ''
  })

  const [errors, setErrors] = useState({})
  const [kelasOptions, setKelasOptions] = useState([])
  const [tahunAjaranOptions, setTahunAjaranOptions] = useState([])

  useEffect(() => {
    fetchOptions()
    if (isEditMode) {
      fetchTarifSpp()
    }
  }, [id])

  const fetchOptions = async () => {
    const [kelasRes, tahunAjaranRes] = await Promise.all([
      kelasService.getAll({ per_page: 100 }),
      tahunAjaranService.getAll({ per_page: 100 })
    ])

    const kelasList = kelasRes.data?.data || []
    setKelasOptions(kelasList.map(k => ({
      value: String(k.id),
      label: k.nama_kelas || `Kelas ${k.id}`
    })))

    const tahunAjaranList = tahunAjaranRes.data?.data || []
    setTahunAjaranOptions(tahunAjaranList.map(ta => ({
      value: String(ta.id),
      label: ta.nama || ta.tahun_ajaran || `${ta.id}`
    })))
  }

  const fetchTarifSpp = async () => {
    setFetchingData(true)
    const { data, error } = await tarifSppService.getById(id)
    if (data) {
      const tarif = data.data
      setFormData({
        mst_kelas_id: tarif.kelas?.id ? String(tarif.kelas.id) : '',
        tahun_ajaran_id: tarif.tahun_ajaran_id ? String(tarif.tahun_ajaran_id) : '',
        nominal: tarif.nominal !== null && tarif.nominal !== undefined ? String(tarif.nominal) : '',
        keterangan: tarif.keterangan || ''
      })
    } else {
      showError('Gagal mengambil data tarif SPP')
      navigate('/keuangan/tarif-spp')
    }
    setFetchingData(false)
  }

  const handleChange = (e) => {
    const { name, value } = e.target
    setFormData(prev => ({ ...prev, [name]: value }))
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: null }))
    }
  }

  const validate = () => {
    const newErrors = {}
    if (!formData.mst_kelas_id) newErrors.mst_kelas_id = 'Kelas wajib dipilih'
    if (!formData.tahun_ajaran_id) newErrors.tahun_ajaran_id = 'Tahun ajaran wajib dipilih'
    if (!formData.nominal || parseFloat(formData.nominal) < 0) newErrors.nominal = 'Nominal wajib diisi dan tidak boleh negatif'
    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    if (!validate()) return

    setLoading(true)

    const submitData = {
      mst_kelas_id: parseInt(formData.mst_kelas_id),
      tahun_ajaran_id: parseInt(formData.tahun_ajaran_id),
      nominal: parseFloat(formData.nominal),
      keterangan: formData.keterangan || null
    }

    let result
    if (isEditMode) {
      result = await tarifSppService.update(id, submitData)
    } else {
      result = await tarifSppService.create(submitData)
    }

    const { error } = result

    if (!error) {
      showSuccess(`Tarif SPP berhasil ${isEditMode ? 'diperbarui' : 'ditambahkan'}!`)
      navigate('/keuangan/tarif-spp')
    } else {
      if (error.errors) {
        setErrors(error.errors)
      } else {
        showError(`Gagal ${isEditMode ? 'memperbarui' : 'menambahkan'} tarif SPP`)
      }
    }
    setLoading(false)
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="secondary" onClick={() => navigate('/keuangan/tarif-spp')}>
          <ArrowLeft size={18} className="mr-2" />
          Kembali
        </Button>
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
          {isEditMode ? 'Edit Tarif SPP' : 'Tambah Tarif SPP Baru'}
        </h1>
      </div>

      <Card>
        {fetchingData ? (
          <div className="flex items-center justify-center h-64">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="p-6 space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Kelas <span className="text-red-500">*</span>
                </label>
                <SearchableSelect
                  name="mst_kelas_id"
                  value={formData.mst_kelas_id}
                  onChange={handleChange}
                  options={kelasOptions}
                  placeholder="Pilih kelas"
                  error={errors.mst_kelas_id}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Tahun Ajaran <span className="text-red-500">*</span>
                </label>
                <SearchableSelect
                  name="tahun_ajaran_id"
                  value={formData.tahun_ajaran_id}
                  onChange={handleChange}
                  options={tahunAjaranOptions}
                  placeholder="Pilih tahun ajaran"
                  error={errors.tahun_ajaran_id}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Nominal (Rp) <span className="text-red-500">*</span>
                </label>
                <Input
                  type="number"
                  name="nominal"
                  value={formData.nominal}
                  onChange={handleChange}
                  placeholder="Masukkan nominal SPP"
                  min="0"
                  step="1000"
                  error={errors.nominal}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Keterangan
                </label>
                <Input
                  type="text"
                  name="keterangan"
                  value={formData.keterangan}
                  onChange={handleChange}
                  placeholder="Keterangan (opsional)"
                  error={errors.keterangan}
                />
              </div>
            </div>

            <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
              <Button type="button" variant="secondary" onClick={() => navigate('/keuangan/tarif-spp')}>
                Batal
              </Button>
              <Button type="submit" disabled={loading}>
                <Save size={18} className="mr-2" />
                {loading ? 'Menyimpan...' : 'Simpan'}
              </Button>
            </div>
          </form>
        )}
      </Card>
    </div>
  )
}

export default TarifSppForm

import { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ArrowLeft, Save } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import Input from '../../../components/ui/Input'
import SearchableSelect from '../../../components/ui/SearchableSelect'
import { tahunAjaranService } from '../services/tahunAjaranService'
import { showSuccess, showError } from '../../../utils/sweetalert'

const STATUS_OPTIONS = [
  { value: '1', label: 'Aktif' },
  { value: '0', label: 'Nonaktif' },
]

const TahunAjaranForm = () => {
  const { id } = useParams()
  const navigate = useNavigate()
  const isEditMode = !!id

  const [loading, setLoading] = useState(false)
  const [fetchingData, setFetchingData] = useState(false)

  const [formData, setFormData] = useState({
    kode: '',
    nama: '',
    tanggal_mulai: '',
    tanggal_selesai: '',
    is_active: '0',
  })

  const [errors, setErrors] = useState({})

  useEffect(() => {
    if (isEditMode) {
      fetchTahunAjaran()
    }
  }, [id])

  const fetchTahunAjaran = async () => {
    setFetchingData(true)
    const { data, error } = await tahunAjaranService.getById(id)
    if (data) {
      const item = data.data
      setFormData({
        kode: item.kode || '',
        nama: item.nama || '',
        tanggal_mulai: item.tanggal_mulai || '',
        tanggal_selesai: item.tanggal_selesai || '',
        is_active: item.is_active !== null && item.is_active !== undefined ? String(Number(item.is_active)) : '0',
      })
    } else {
      showError('Gagal mengambil data tahun ajaran')
      navigate('/admin/tahun-ajaran')
    }
    setFetchingData(false)
  }

  const handleChange = (e) => {
    const { name, value } = e.target
    setFormData(prev => ({ ...prev, [name]: value }))
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: null }))
    }
  }

  const validate = () => {
    const newErrors = {}
    if (!formData.kode.trim()) newErrors.kode = 'Kode wajib diisi'
    if (!formData.nama.trim()) newErrors.nama = 'Nama wajib diisi'
    if (!formData.tanggal_mulai) newErrors.tanggal_mulai = 'Tanggal mulai wajib diisi'
    if (!formData.tanggal_selesai) newErrors.tanggal_selesai = 'Tanggal selesai wajib diisi'

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    if (!validate()) return

    setLoading(true)

    const submitData = {
      kode: formData.kode,
      nama: formData.nama,
      tanggal_mulai: formData.tanggal_mulai,
      tanggal_selesai: formData.tanggal_selesai,
      is_active: parseInt(formData.is_active) === 1,
    }

    let result
    if (isEditMode) {
      result = await tahunAjaranService.update(id, submitData)
    } else {
      result = await tahunAjaranService.create(submitData)
    }

    const { error } = result

    if (!error) {
      showSuccess(`Tahun Ajaran berhasil ${isEditMode ? 'diperbarui' : 'ditambahkan'}!`)
      navigate('/admin/tahun-ajaran')
    } else {
      console.error(error)
      if (error.errors) {
        setErrors(error.errors)
      } else {
        showError(`Gagal ${isEditMode ? 'memperbarui' : 'menambahkan'} tahun ajaran`)
      }
    }
    setLoading(false)
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="secondary" onClick={() => navigate('/admin/tahun-ajaran')}>
          <ArrowLeft size={18} className="mr-2" />
          Kembali
        </Button>
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
          {isEditMode ? 'Edit Tahun Ajaran' : 'Tambah Tahun Ajaran Baru'}
        </h1>
      </div>

      <Card>
        {fetchingData ? (
          <div className="flex items-center justify-center h-64">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="p-6 space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Kode <span className="text-red-500">*</span>
                </label>
                <Input
                  type="text"
                  name="kode"
                  value={formData.kode}
                  onChange={handleChange}
                  placeholder="Masukkan kode (cth: 2024/2025)"
                  error={errors.kode}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Nama <span className="text-red-500">*</span>
                </label>
                <Input
                  type="text"
                  name="nama"
                  value={formData.nama}
                  onChange={handleChange}
                  placeholder="Masukkan nama tahun ajaran"
                  error={errors.nama}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Tanggal Mulai <span className="text-red-500">*</span>
                </label>
                <Input
                  type="date"
                  name="tanggal_mulai"
                  value={formData.tanggal_mulai}
                  onChange={handleChange}
                  error={errors.tanggal_mulai}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Tanggal Selesai <span className="text-red-500">*</span>
                </label>
                <Input
                  type="date"
                  name="tanggal_selesai"
                  value={formData.tanggal_selesai}
                  onChange={handleChange}
                  error={errors.tanggal_selesai}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Status
                </label>
                <SearchableSelect
                  name="is_active"
                  value={formData.is_active}
                  onChange={handleChange}
                  options={STATUS_OPTIONS}
                  placeholder="Pilih status"
                  error={errors.is_active}
                />
              </div>
            </div>

            <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
              <Button type="button" variant="secondary" onClick={() => navigate('/admin/tahun-ajaran')}>
                Batal
              </Button>
              <Button type="submit" disabled={loading}>
                <Save size={18} className="mr-2" />
                {loading ? 'Menyimpan...' : 'Simpan'}
              </Button>
            </div>
          </form>
        )}
      </Card>
    </div>
  )
}

export default TahunAjaranForm

import { useState, useEffect } from 'react'
import { useParams, useNavigate, useLocation } from 'react-router-dom'
import { ArrowLeft, Edit, Trash2, User, BookOpen, Calendar, FileText, Hash, Star, Save, MessageSquare } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import Input from '../../../components/ui/Input'
import { tugasSiswaService } from '../services/tugasService'
import { showDeleteConfirm, showSuccess, showError } from '../../../utils/sweetalert'

// Submission status mapping
const STATUS_MAP = {
  sudah: { label: 'Sudah Dikumpulkan', bg: 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400' },
  belum: { label: 'Belum Dikumpulkan', bg: 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400' },
  terlambat: { label: 'Terlambat', bg: 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-400' },
  1: { label: 'Sudah Dikumpulkan', bg: 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400' },
  0: { label: 'Belum Dikumpulkan', bg: 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400' },
}

const TugasSiswaDetail = () => {
  const { id } = useParams()
  const navigate = useNavigate()
  const location = useLocation()
  
  const [loading, setLoading] = useState(false)
  const [tugasSiswa, setTugasSiswa] = useState(null)
  const [showGradeForm, setShowGradeForm] = useState(location.state?.openGrade || false)
  const [gradeData, setGradeData] = useState({ nilai: '', catatan: '' })
  const [gradeLoading, setGradeLoading] = useState(false)
  const [gradeErrors, setGradeErrors] = useState({})

  useEffect(() => {
    fetchTugasSiswa()
  }, [id])

  const fetchTugasSiswa = async () => {
    setLoading(true)
    const { data, error } = await tugasSiswaService.getById(id)
    if (data) {
      const ts = data.data
      setTugasSiswa(ts)
      setGradeData({
        nilai: ts.nilai !== null && ts.nilai !== undefined ? String(ts.nilai) : '',
        catatan: ts.catatan || ''
      })
    } else {
      showError('Gagal mengambil data tugas siswa')
      navigate('/akademik/tugas-siswa')
    }
    setLoading(false)
  }

  const handleDelete = async () => {
    const label = `Pengumpulan tugas #${tugasSiswa.id}`
    const result = await showDeleteConfirm(label)
    if (result.isConfirmed) {
      const { error } = await tugasSiswaService.delete(tugasSiswa.id)
      if (!error) {
        showSuccess(`${label} berhasil dihapus!`)
        navigate('/akademik/tugas-siswa')
      } else {
        showError('Gagal menghapus data')
      }
    }
  }

  const handleGradeSubmit = async (e) => {
    e.preventDefault()
    
    const newErrors = {}
    if (gradeData.nilai === '' || gradeData.nilai === null) {
      newErrors.nilai = 'Nilai wajib diisi'
    } else if (parseFloat(gradeData.nilai) < 0 || parseFloat(gradeData.nilai) > 100) {
      newErrors.nilai = 'Nilai harus antara 0-100'
    }
    
    if (Object.keys(newErrors).length > 0) {
      setGradeErrors(newErrors)
      return
    }

    setGradeLoading(true)
    const submitData = {
      nilai: parseFloat(gradeData.nilai),
      catatan: gradeData.catatan || null
    }

    const { error } = await tugasSiswaService.nilai(id, submitData)
    if (!error) {
      showSuccess('Nilai berhasil disimpan!')
      setShowGradeForm(false)
      fetchTugasSiswa()
    } else {
      console.error(error)
      if (error.errors) {
        setGradeErrors(error.errors)
      } else {
        showError('Gagal menyimpan nilai')
      }
    }
    setGradeLoading(false)
  }

  const formatDate = (dateString) => {
    if (!dateString) return '-'
    const date = new Date(dateString)
    return date.toLocaleDateString('id-ID', {
      day: 'numeric',
      month: 'long',
      year: 'numeric'
    })
  }

  const formatDateTime = (dateString) => {
    if (!dateString) return '-'
    const date = new Date(dateString)
    return date.toLocaleDateString('id-ID', {
      day: 'numeric',
      month: 'long',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    })
  }

  const getStatusBadge = (status) => {
    if (status === null || status === undefined) return '-'
    const statusKey = String(status).toLowerCase()
    const statusInfo = STATUS_MAP[status] || STATUS_MAP[statusKey] || { label: String(status), bg: 'bg-gray-100 text-gray-800 dark:bg-gray-900/30 dark:text-gray-400' }
    return (
      <span className={`px-2 py-1 rounded-full text-xs font-medium ${statusInfo.bg}`}>
        {statusInfo.label}
      </span>
    )
  }

  if (loading || !tugasSiswa) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
        <div className="flex items-center gap-4">
          <Button variant="secondary" onClick={() => navigate('/akademik/tugas-siswa')}>
            <ArrowLeft size={18} className="mr-2" />
            Kembali
          </Button>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Detail Tugas Siswa</h1>
        </div>
        <div className="flex gap-3">
          <Button variant="primary" onClick={() => setShowGradeForm(!showGradeForm)}>
            <Star size={18} className="mr-2" />
            {showGradeForm ? 'Tutup Penilaian' : 'Beri Nilai'}
          </Button>
          <Button variant="warning" onClick={() => navigate(`/akademik/tugas-siswa/${id}/edit`)}>
            <Edit size={18} className="mr-2" />
            Edit
          </Button>
          <Button variant="danger" onClick={handleDelete}>
            <Trash2 size={18} className="mr-2" />
            Hapus
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {/* Summary Card */}
        <div className="md:col-span-1">
          <Card>
            <div className="p-6 text-center">
              <div className="w-24 h-24 bg-gray-200 dark:bg-gray-700 rounded-full mx-auto mb-4 flex items-center justify-center">
                <User size={48} className="text-gray-400" />
              </div>
              <h2 className="text-lg font-bold text-gray-900 dark:text-white mb-2">
                {tugasSiswa.siswa?.nama || tugasSiswa.siswa?.name || '-'}
              </h2>
              <p className="text-sm text-gray-500 dark:text-gray-400 mb-2">
                {tugasSiswa.siswa?.nis ? `NIS: ${tugasSiswa.siswa.nis}` : ''}
              </p>
              <div className="flex justify-center gap-2 mb-2">
                {getStatusBadge(tugasSiswa.status_kumpl)}
              </div>

              <div className="mt-6 border-t border-gray-200 dark:border-gray-700 pt-4 text-left space-y-3">
                <div className="flex justify-between">
                  <span className="text-gray-500 dark:text-gray-400">ID</span>
                  <span className="font-medium text-gray-900 dark:text-white">{tugasSiswa.id}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-gray-500 dark:text-gray-400">Nilai</span>
                  <span className="font-medium text-gray-900 dark:text-white text-lg">
                    {tugasSiswa.nilai !== null && tugasSiswa.nilai !== undefined ? tugasSiswa.nilai : '-'}
                  </span>
                </div>
              </div>
            </div>
          </Card>
        </div>

        {/* Detail Info */}
        <div className="md:col-span-2">
          <Card>
            <div className="p-6">
              <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-6">Informasi Lengkap</h3>
              
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="flex items-start gap-3">
                  <div className="w-10 h-10 bg-blue-50 dark:bg-blue-900/20 rounded-lg flex items-center justify-center flex-shrink-0">
                    <BookOpen size={20} className="text-blue-600" />
                  </div>
                  <div>
                    <p className="text-xs text-gray-500 dark:text-gray-400">Tugas</p>
                    <p className="font-medium text-gray-900 dark:text-white">
                      {tugasSiswa.tugas?.judul || '-'}
                    </p>
                    {tugasSiswa.tugas?.guru_mapel && (
                      <p className="text-xs text-gray-500 dark:text-gray-400">
                        {tugasSiswa.tugas.guru_mapel.guru?.nama || ''} - {tugasSiswa.tugas.guru_mapel.mapel?.nama || ''}
                      </p>
                    )}
                  </div>
                </div>

                <div className="flex items-start gap-3">
                  <div className="w-10 h-10 bg-purple-50 dark:bg-purple-900/20 rounded-lg flex items-center justify-center flex-shrink-0">
                    <User size={20} className="text-purple-600" />
                  </div>
                  <div>
                    <p className="text-xs text-gray-500 dark:text-gray-400">Siswa</p>
                    <p className="font-medium text-gray-900 dark:text-white">
                      {tugasSiswa.siswa?.nama || tugasSiswa.siswa?.name || '-'}
                    </p>
                    {tugasSiswa.siswa?.nis && (
                      <p className="text-xs text-gray-500 dark:text-gray-400">
                        NIS: {tugasSiswa.siswa.nis}
                      </p>
                    )}
                  </div>
                </div>

                <div className="flex items-start gap-3">
                  <div className="w-10 h-10 bg-orange-50 dark:bg-orange-900/20 rounded-lg flex items-center justify-center flex-shrink-0">
                    <Calendar size={20} className="text-orange-600" />
                  </div>
                  <div>
                    <p className="text-xs text-gray-500 dark:text-gray-400">Tanggal Kumpul</p>
                    <p className="font-medium text-gray-900 dark:text-white">
                      {formatDateTime(tugasSiswa.waktu_kumpl)}
                    </p>
                  </div>
                </div>

                <div className="flex items-start gap-3">
                  <div className="w-10 h-10 bg-green-50 dark:bg-green-900/20 rounded-lg flex items-center justify-center flex-shrink-0">
                    <Hash size={20} className="text-green-600" />
                  </div>
                  <div>
                    <p className="text-xs text-gray-500 dark:text-gray-400">Status Kumpul</p>
                    <div className="mt-1">{getStatusBadge(tugasSiswa.status_kumpl)}</div>
                  </div>
                </div>

                <div className="flex items-start gap-3">
                  <div className="w-10 h-10 bg-yellow-50 dark:bg-yellow-900/20 rounded-lg flex items-center justify-center flex-shrink-0">
                    <Star size={20} className="text-yellow-600" />
                  </div>
                  <div>
                    <p className="text-xs text-gray-500 dark:text-gray-400">Nilai</p>
                    <p className="font-medium text-gray-900 dark:text-white text-lg">
                      {tugasSiswa.nilai !== null && tugasSiswa.nilai !== undefined ? tugasSiswa.nilai : '-'}
                    </p>
                  </div>
                </div>

                <div className="flex items-start gap-3">
                  <div className="w-10 h-10 bg-indigo-50 dark:bg-indigo-900/20 rounded-lg flex items-center justify-center flex-shrink-0">
                    <FileText size={20} className="text-indigo-600" />
                  </div>
                  <div>
                    <p className="text-xs text-gray-500 dark:text-gray-400">File Path</p>
                    <p className="font-medium text-gray-900 dark:text-white">{tugasSiswa.file_path || '-'}</p>
                  </div>
                </div>
              </div>

              {/* Jawaban Section */}
              {tugasSiswa.jawaban && (
                <div className="mt-6 border-t border-gray-200 dark:border-gray-700 pt-6">
                  <h4 className="text-sm font-semibold text-gray-900 dark:text-white mb-2">Jawaban</h4>
                  <div className="p-4 bg-gray-50 dark:bg-gray-800 rounded-lg">
                    <p className="text-gray-700 dark:text-gray-300 whitespace-pre-wrap">{tugasSiswa.jawaban}</p>
                  </div>
                </div>
              )}

              {/* Catatan Section */}
              {tugasSiswa.catatan && (
                <div className="mt-6 border-t border-gray-200 dark:border-gray-700 pt-6">
                  <div className="flex items-center gap-2 mb-2">
                    <MessageSquare size={16} className="text-gray-500" />
                    <h4 className="text-sm font-semibold text-gray-900 dark:text-white">Catatan Guru</h4>
                  </div>
                  <div className="p-4 bg-blue-50 dark:bg-blue-900/20 rounded-lg">
                    <p className="text-gray-700 dark:text-gray-300 whitespace-pre-wrap">{tugasSiswa.catatan}</p>
                  </div>
                </div>
              )}

              {/* Timestamps */}
              <div className="mt-8 border-t border-gray-200 dark:border-gray-700 pt-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-sm">
                  <div>
                    <p className="text-xs text-gray-500 dark:text-gray-400">Dibuat pada</p>
                    <p className="text-gray-700 dark:text-gray-300">{formatDate(tugasSiswa.created_at)}</p>
                  </div>
                  <div>
                    <p className="text-xs text-gray-500 dark:text-gray-400">Terakhir diperbarui</p>
                    <p className="text-gray-700 dark:text-gray-300">{formatDate(tugasSiswa.updated_at)}</p>
                  </div>
                </div>
              </div>
            </div>
          </Card>
        </div>
      </div>

      {/* Inline Grade Form */}
      {showGradeForm && (
        <Card>
          <div className="p-6">
            <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
              <Star size={20} className="inline mr-2 text-yellow-500" />
              Penilaian Tugas
            </h3>
            <form onSubmit={handleGradeSubmit} className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Nilai (0-100) <span className="text-red-500">*</span>
                  </label>
                  <Input
                    type="number"
                    name="nilai"
                    value={gradeData.nilai}
                    onChange={(e) => {
                      setGradeData(prev => ({ ...prev, nilai: e.target.value }))
                      if (gradeErrors.nilai) setGradeErrors(prev => ({ ...prev, nilai: null }))
                    }}
                    placeholder="Masukkan nilai"
                    min="0"
                    max="100"
                    error={gradeErrors.nilai}
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Catatan
                  </label>
                  <textarea
                    name="catatan"
                    value={gradeData.catatan}
                    onChange={(e) => setGradeData(prev => ({ ...prev, catatan: e.target.value }))}
                    placeholder="Catatan untuk siswa (opsional)"
                    rows={3}
                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white focus:ring-2 focus:ring-primary-500 focus:outline-none resize-y"
                  />
                </div>
              </div>
              <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
                <Button type="button" variant="secondary" onClick={() => setShowGradeForm(false)}>
                  Batal
                </Button>
                <Button type="submit" disabled={gradeLoading}>
                  <Save size={18} className="mr-2" />
                  {gradeLoading ? 'Menyimpan...' : 'Simpan Nilai'}
                </Button>
              </div>
            </form>
          </div>
        </Card>
      )}
    </div>
  )
}

export default TugasSiswaDetail

import { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ArrowLeft, Save } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import Input from '../../../components/ui/Input'
import SearchableSelect from '../../../components/ui/SearchableSelect'
import { tugasService, tugasSiswaService } from '../services/tugasService'
import { siswaService } from '../../siswa/services/siswaService'
import { showSuccess, showError } from '../../../utils/sweetalert'

const STATUS_KUMPUL_OPTIONS = [
  { value: 'sudah', label: 'Sudah Dikumpulkan' },
  { value: 'belum', label: 'Belum Dikumpulkan' },
  { value: 'terlambat', label: 'Terlambat' },
]

const TugasSiswaForm = () => {
  const { id } = useParams()
  const navigate = useNavigate()
  const isEditMode = !!id

  const [loading, setLoading] = useState(false)
  const [fetchingData, setFetchingData] = useState(false)
  
  const [formData, setFormData] = useState({
    mst_tugas_id: '',
    mst_siswa_id: '',
    jawaban: '',
    file_path: '',
    waktu_kumpl: '',
    status_kumpl: '',
    nilai: '',
    catatan: ''
  })

  const [errors, setErrors] = useState({})
  const [tugasOptions, setTugasOptions] = useState([])
  const [siswaOptions, setSiswaOptions] = useState([])

  useEffect(() => {
    fetchTugasOptions()
    fetchSiswaOptions()
    if (isEditMode) {
      fetchTugasSiswa()
    }
  }, [id])

  const fetchTugasOptions = async () => {
    const { data, error } = await tugasService.getAll({ per_page: 100 })
    if (data?.data) {
      const options = data.data.map(tugas => ({
        value: String(tugas.id),
        label: tugas.judul || `Tugas #${tugas.id}`
      }))
      setTugasOptions(options)
    }
  }

  const fetchSiswaOptions = async () => {
    const { data, error } = await siswaService.getAll({ per_page: 100 })
    if (data?.data) {
      const options = data.data.map(siswa => ({
        value: String(siswa.id),
        label: `${siswa.nis ? siswa.nis + ' - ' : ''}${siswa.nama || siswa.name || `Siswa #${siswa.id}`}`
      }))
      setSiswaOptions(options)
    }
  }

  const fetchTugasSiswa = async () => {
    setFetchingData(true)
    const { data, error } = await tugasSiswaService.getById(id)
    if (data) {
      const ts = data.data
      // Format datetime for datetime-local input
      let waktuKumpl = ''
      if (ts.waktu_kumpl) {
        const dt = new Date(ts.waktu_kumpl)
        waktuKumpl = dt.toISOString().slice(0, 16)
      }
      setFormData({
        mst_tugas_id: ts.tugas?.id ? String(ts.tugas.id) : (ts.mst_tugas_id ? String(ts.mst_tugas_id) : ''),
        mst_siswa_id: ts.siswa?.id ? String(ts.siswa.id) : (ts.mst_siswa_id ? String(ts.mst_siswa_id) : ''),
        jawaban: ts.jawaban || '',
        file_path: ts.file_path || '',
        waktu_kumpl: waktuKumpl,
        status_kumpl: ts.status_kumpl !== null && ts.status_kumpl !== undefined ? String(ts.status_kumpl) : '',
        nilai: ts.nilai !== null && ts.nilai !== undefined ? String(ts.nilai) : '',
        catatan: ts.catatan || ''
      })
    } else {
      showError('Gagal mengambil data tugas siswa')
      navigate('/akademik/tugas-siswa')
    }
    setFetchingData(false)
  }

  const handleChange = (e) => {
    const { name, value } = e.target
    setFormData(prev => ({ ...prev, [name]: value }))
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: null }))
    }
  }

  const validate = () => {
    const newErrors = {}
    if (!formData.mst_tugas_id) newErrors.mst_tugas_id = 'Tugas wajib dipilih'
    if (!formData.mst_siswa_id) newErrors.mst_siswa_id = 'Siswa wajib dipilih'

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    
    if (!validate()) return

    setLoading(true)
    
    const submitData = {
      mst_tugas_id: parseInt(formData.mst_tugas_id),
      mst_siswa_id: parseInt(formData.mst_siswa_id),
      jawaban: formData.jawaban || null,
      file_path: formData.file_path || null,
      waktu_kumpl: formData.waktu_kumpl || null,
      status_kumpl: formData.status_kumpl || null,
      nilai: formData.nilai !== '' ? parseFloat(formData.nilai) : null,
      catatan: formData.catatan || null
    }

    let result
    
    if (isEditMode) {
      result = await tugasSiswaService.update(id, submitData)
    } else {
      result = await tugasSiswaService.create(submitData)
    }

    const { error } = result

    if (!error) {
      showSuccess(`Tugas siswa berhasil ${isEditMode ? 'diperbarui' : 'ditambahkan'}!`)
      navigate('/akademik/tugas-siswa')
    } else {
      console.error(error)
      if (error.errors) {
        setErrors(error.errors)
      } else {
        showError(`Gagal ${isEditMode ? 'memperbarui' : 'menambahkan'} tugas siswa`)
      }
    }
    setLoading(false)
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="secondary" onClick={() => navigate('/akademik/tugas-siswa')}>
          <ArrowLeft size={18} className="mr-2" />
          Kembali
        </Button>
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
          {isEditMode ? 'Edit Tugas Siswa' : 'Tambah Pengumpulan Tugas'}
        </h1>
      </div>

      <Card>
        {fetchingData ? (
          <div className="flex items-center justify-center h-64">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="p-6 space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Tugas */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Tugas <span className="text-red-500">*</span>
                </label>
                <SearchableSelect
                  name="mst_tugas_id"
                  value={formData.mst_tugas_id}
                  onChange={handleChange}
                  options={tugasOptions}
                  placeholder="Pilih tugas"
                  error={errors.mst_tugas_id}
                />
              </div>

              {/* Siswa */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Siswa <span className="text-red-500">*</span>
                </label>
                <SearchableSelect
                  name="mst_siswa_id"
                  value={formData.mst_siswa_id}
                  onChange={handleChange}
                  options={siswaOptions}
                  placeholder="Pilih siswa"
                  error={errors.mst_siswa_id}
                />
              </div>

              {/* Jawaban */}
              <div className="md:col-span-2">
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Jawaban
                </label>
                <textarea
                  name="jawaban"
                  value={formData.jawaban}
                  onChange={handleChange}
                  placeholder="Masukkan jawaban siswa"
                  rows={4}
                  className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white focus:ring-2 focus:ring-primary-500 focus:outline-none resize-y"
                />
                {errors.jawaban && (
                  <p className="mt-1 text-sm text-red-500">{errors.jawaban}</p>
                )}
              </div>

              {/* File Path */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  File Path
                </label>
                <Input
                  type="text"
                  name="file_path"
                  value={formData.file_path}
                  onChange={handleChange}
                  placeholder="Path file (opsional)"
                  error={errors.file_path}
                />
              </div>

              {/* Tanggal Kumpul */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Tanggal Kumpul
                </label>
                <input
                  type="datetime-local"
                  name="waktu_kumpl"
                  value={formData.waktu_kumpl}
                  onChange={handleChange}
                  className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white focus:ring-2 focus:ring-primary-500 focus:outline-none"
                />
                {errors.waktu_kumpl && (
                  <p className="mt-1 text-sm text-red-500">{errors.waktu_kumpl}</p>
                )}
              </div>

              {/* Status Kumpul */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Status Kumpul
                </label>
                <SearchableSelect
                  name="status_kumpl"
                  value={formData.status_kumpl}
                  onChange={handleChange}
                  options={STATUS_KUMPUL_OPTIONS}
                  placeholder="Pilih status"
                  error={errors.status_kumpl}
                />
              </div>

              {/* Nilai - only shown in edit mode */}
              {isEditMode && (
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Nilai (0-100)
                  </label>
                  <Input
                    type="number"
                    name="nilai"
                    value={formData.nilai}
                    onChange={handleChange}
                    placeholder="Masukkan nilai"
                    min="0"
                    max="100"
                    error={errors.nilai}
                  />
                </div>
              )}

              {/* Catatan */}
              <div className={isEditMode ? '' : 'md:col-span-2'}>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Catatan Guru
                </label>
                <textarea
                  name="catatan"
                  value={formData.catatan}
                  onChange={handleChange}
                  placeholder="Catatan dari guru (opsional)"
                  rows={3}
                  className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white focus:ring-2 focus:ring-primary-500 focus:outline-none resize-y"
                />
                {errors.catatan && (
                  <p className="mt-1 text-sm text-red-500">{errors.catatan}</p>
                )}
              </div>
            </div>

            <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
              <Button type="button" variant="secondary" onClick={() => navigate('/akademik/tugas-siswa')}>
                Batal
              </Button>
              <Button type="submit" disabled={loading}>
                <Save size={18} className="mr-2" />
                {loading ? 'Menyimpan...' : 'Simpan'}
              </Button>
            </div>
          </form>
        )}
      </Card>
    </div>
  )
}

export default TugasSiswaForm

import { useState, useEffect } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import { Save, ArrowLeft } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import Input from '../../../components/ui/Input'
import { ujianJawabanService } from '../services/ujianJawabanService'
import { showSuccess, showError } from '../../../utils/sweetalert'

const UjianJawabanForm = () => {
  const navigate = useNavigate()
  const { id } = useParams()
  const isEdit = Boolean(id)

  const [formData, setFormData] = useState({
    trx_ujian_user_id: '',
    mst_soal_id: '',
    mst_soal_opsi_id: '',
    jawaban_teks: '',
    ragu_ragu: false,
  })
  const [loading, setLoading] = useState(false)
  const [saving, setSaving] = useState(false)
  const [errors, setErrors] = useState({})

  useEffect(() => { if (isEdit) fetchData() }, [id])

  const fetchData = async () => {
    setLoading(true)
    const { data, error } = await ujianJawabanService.getById(id)
    if (data?.data) {
      const d = data.data
      setFormData({
        trx_ujian_user_id: d.trx_ujian_user_id || '',
        mst_soal_id: d.mst_soal_id || '',
        mst_soal_opsi_id: d.mst_soal_opsi_id || '',
        jawaban_teks: d.jawaban_teks || '',
        ragu_ragu: Boolean(d.ragu_ragu),
      })
    } else {
      showError('Gagal mengambil data')
      navigate('/akademik/ujian-jawaban')
    }
    setLoading(false)
  }

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target
    setFormData(prev => ({ ...prev, [name]: type === 'checkbox' ? checked : value }))
    if (errors[name]) setErrors(prev => ({ ...prev, [name]: null }))
  }

  const validate = () => {
    const errs = {}
    if (!formData.trx_ujian_user_id) errs.trx_ujian_user_id = 'Ujian User ID wajib diisi'
    if (!formData.mst_soal_id) errs.mst_soal_id = 'Soal ID wajib diisi'
    setErrors(errs)
    return Object.keys(errs).length === 0
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    if (!validate()) return
    setSaving(true)
    const payload = { ...formData }
    const { data, error } = isEdit
      ? await ujianJawabanService.update(id, payload)
      : await ujianJawabanService.create(payload)
    if (data) {
      showSuccess(`Jawaban berhasil ${isEdit ? 'diperbarui' : 'ditambahkan'}!`)
      navigate('/akademik/ujian-jawaban')
    } else {
      if (error?.errors) setErrors(error.errors)
      else showError(error?.message || 'Gagal menyimpan data')
    }
    setSaving(false)
  }

  if (loading) return <div className="flex items-center justify-center h-64"><div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div></div>

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="secondary" onClick={() => navigate('/akademik/ujian-jawaban')}><ArrowLeft size={18} /></Button>
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">{isEdit ? 'Edit' : 'Tambah'} Jawaban Ujian</h1>
      </div>
      <Card>
        <form onSubmit={handleSubmit} className="p-6 space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <Input label="Ujian User ID *" name="trx_ujian_user_id" type="number" value={formData.trx_ujian_user_id} onChange={handleChange} error={errors.trx_ujian_user_id} placeholder="ID ujian user" />
            <Input label="Soal ID *" name="mst_soal_id" type="number" value={formData.mst_soal_id} onChange={handleChange} error={errors.mst_soal_id} placeholder="ID soal" />
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <Input label="Opsi ID" name="mst_soal_opsi_id" type="number" value={formData.mst_soal_opsi_id} onChange={handleChange} error={errors.mst_soal_opsi_id} placeholder="ID opsi jawaban" />
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Jawaban Teks</label>
              <textarea name="jawaban_teks" value={formData.jawaban_teks} onChange={handleChange} rows={3}
                className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-sm focus:ring-2 focus:ring-primary-500 focus:outline-none"
                placeholder="Jawaban dalam bentuk teks (untuk soal essay)" />
            </div>
          </div>
          <label className="flex items-center gap-2 cursor-pointer">
            <input type="checkbox" name="ragu_ragu" checked={formData.ragu_ragu} onChange={handleChange}
              className="w-4 h-4 text-primary-600 border-gray-300 rounded focus:ring-primary-500" />
            <span className="text-sm text-gray-700 dark:text-gray-300">Ragu-ragu</span>
          </label>
          <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
            <Button type="button" variant="secondary" onClick={() => navigate('/akademik/ujian-jawaban')}>Batal</Button>
            <Button type="submit" disabled={saving}><Save size={18} className="mr-2" />{saving ? 'Menyimpan...' : 'Simpan'}</Button>
          </div>
        </form>
      </Card>
    </div>
  )
}

export default UjianJawabanForm

import { useCallback, useEffect, useState } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ArrowLeft, Save } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import SearchableSelect from '../../../components/ui/SearchableSelect'
import { ujianUserService } from '../services/ujianUserService'
import { ujianService } from '../../ujian/services/ujianService'
import { siswaService } from '../../siswa/services/siswaService'
import { showSuccess, showError } from '../../../utils/sweetalert'

const UjianUserForm = () => {
  const { id } = useParams()
  const navigate = useNavigate()
  const isEditMode = !!id

  const [loading, setLoading] = useState(false)
  const [fetchingData, setFetchingData] = useState(false)
  
  const [selectedUjianOption, setSelectedUjianOption] = useState(null)
  const [selectedSiswaOption, setSelectedSiswaOption] = useState(null)
  
  const [formData, setFormData] = useState({
    trx_ujian_id: '',
    mst_siswa_id: ''
  })

  const [errors, setErrors] = useState({})

  const buildUjianOption = useCallback((ujian) => ({
    value: String(ujian.id),
    label: ujian.nama || `Ujian #${ujian.id} - ${ujian.mapel?.nama || 'Unknown'}`
  }), [])

  const buildSiswaOption = useCallback((siswa) => ({
    value: String(siswa.id),
    label: `${siswa.nama || `Siswa #${siswa.id}`} (${siswa.nis || '-'}) - ${siswa.kelas?.nama_kelas || 'No Class'}`
  }), [])

  const searchUjianOptions = useCallback(async (keyword = '') => {
    const { data, error } = await ujianService.getAll({
      search: keyword || undefined,
      per_page: 20
    })

    if (data?.data) {
      return data.data.map(buildUjianOption)
    }

    console.error('Error fetching ujian:', error)
    return []
  }, [buildUjianOption])

  const searchSiswaOptions = useCallback(async (keyword = '') => {
    const { data, error } = await siswaService.getAll({
      search: keyword || undefined,
      per_page: 20
    })

    if (data?.data) {
      return data.data.map(buildSiswaOption)
    }

    console.error('Error fetching siswa:', error)
    return []
  }, [buildSiswaOption])

  // Fetch existing data if in edit mode
  useEffect(() => {
    if (isEditMode) {
      fetchUjianUser()
    }
  }, [id])

  const fetchUjianUser = async () => {
    setFetchingData(true)
    const { data, error } = await ujianUserService.getById(id)
    if (data) {
      const ujianUser = data.data
      const ujianId = ujianUser.trx_ujian_id?.toString() || ujianUser.ujian?.id?.toString() || ''
      const siswaId = ujianUser.mst_siswa_id?.toString() || ujianUser.siswa?.id?.toString() || ''

      setFormData({
        trx_ujian_id: ujianId,
        mst_siswa_id: siswaId
      })

      if (ujianUser.ujian?.id) {
        setSelectedUjianOption(buildUjianOption(ujianUser.ujian))
      }

      if (ujianUser.siswa?.id) {
        setSelectedSiswaOption(buildSiswaOption(ujianUser.siswa))
      }
    } else {
      showError('Gagal mengambil data ujian user')
      navigate('/akademik/ujian-user')
    }
    setFetchingData(false)
  }

  const hydrateSelectedUjianOption = useCallback(async (ujianId) => {
    if (!ujianId) {
      setSelectedUjianOption(null)
      return
    }

    const { data } = await ujianService.getById(ujianId)
    const ujian = data?.data

    if (ujian) {
      setSelectedUjianOption(buildUjianOption(ujian))
      return
    }

    setSelectedUjianOption({
      value: String(ujianId),
      label: `Ujian #${ujianId}`
    })
  }, [buildUjianOption])

  const hydrateSelectedSiswaOption = useCallback(async (siswaId) => {
    if (!siswaId) {
      setSelectedSiswaOption(null)
      return
    }

    const { data } = await siswaService.getById(siswaId)
    const siswa = data?.data

    if (siswa) {
      setSelectedSiswaOption(buildSiswaOption(siswa))
      return
    }

    setSelectedSiswaOption({
      value: String(siswaId),
      label: `Siswa #${siswaId}`
    })
  }, [buildSiswaOption])

  useEffect(() => {
    if (formData.trx_ujian_id) {
      hydrateSelectedUjianOption(formData.trx_ujian_id)
    } else {
      setSelectedUjianOption(null)
    }
  }, [formData.trx_ujian_id, hydrateSelectedUjianOption])

  useEffect(() => {
    if (formData.mst_siswa_id) {
      hydrateSelectedSiswaOption(formData.mst_siswa_id)
    } else {
      setSelectedSiswaOption(null)
    }
  }, [formData.mst_siswa_id, hydrateSelectedSiswaOption])

  const handleChange = (e) => {
    const { name, value } = e.target
    setFormData(prev => ({ ...prev, [name]: value }))
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: null }))
    }
  }

  const validate = () => {
    const newErrors = {}
    if (!formData.trx_ujian_id) newErrors.trx_ujian_id = 'Ujian wajib dipilih'
    if (!formData.mst_siswa_id) newErrors.mst_siswa_id = 'Siswa wajib dipilih'

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    
    if (!validate()) return

    setLoading(true)
    
    const submitData = {
      trx_ujian_id: parseInt(formData.trx_ujian_id),
      mst_siswa_id: parseInt(formData.mst_siswa_id)
    }

    let result
    
    if (isEditMode) {
      result = await ujianUserService.update(id, submitData)
    } else {
      result = await ujianUserService.create(submitData)
    }

    const { error } = result

    if (!error) {
      showSuccess(`Ujian user berhasil ${isEditMode ? 'diperbarui' : 'ditambahkan'}!`)
      navigate('/akademik/ujian-user')
    } else {
      console.error(error)
      if (error.errors) {
        setErrors(error.errors)
      } else {
        showError(`Gagal ${isEditMode ? 'memperbarui' : 'menambahkan'} ujian user`)
      }
    }
    setLoading(false)
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="secondary" onClick={() => navigate('/akademik/ujian-user')}>
          <ArrowLeft size={18} className="mr-2" />
          Kembali
        </Button>
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
          {isEditMode ? 'Edit Ujian User' : 'Tambah Ujian User Baru'}
        </h1>
      </div>

      <Card>
        {fetchingData ? (
          <div className="flex items-center justify-center h-64">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="p-6 space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Ujian Select */}
              <div className="md:col-span-2">
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Ujian <span className="text-red-500">*</span>
                </label>
                <SearchableSelect
                  name="trx_ujian_id"
                  value={formData.trx_ujian_id}
                  onChange={handleChange}
                  options={selectedUjianOption ? [selectedUjianOption] : []}
                  loadOptions={searchUjianOptions}
                  placeholder="Pilih Ujian"
                  searchPlaceholder="Cari ujian berdasarkan nama..."
                  noOptionsText="Tidak ada ujian yang cocok"
                  error={errors.trx_ujian_id}
                />
                {errors.trx_ujian_id && (
                  <p className="mt-1 text-sm text-red-500">
                    {Array.isArray(errors.trx_ujian_id) ? errors.trx_ujian_id[0] : errors.trx_ujian_id}
                  </p>
                )}
              </div>

              {/* Siswa Select */}
              <div className="md:col-span-2">
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Siswa <span className="text-red-500">*</span>
                </label>
                <SearchableSelect
                  name="mst_siswa_id"
                  value={formData.mst_siswa_id}
                  onChange={handleChange}
                  options={selectedSiswaOption ? [selectedSiswaOption] : []}
                  loadOptions={searchSiswaOptions}
                  placeholder="Pilih Siswa"
                  searchPlaceholder="Cari siswa berdasarkan nama atau NIS..."
                  noOptionsText="Tidak ada siswa yang cocok"
                  error={errors.mst_siswa_id}
                />
                {errors.mst_siswa_id && (
                  <p className="mt-1 text-sm text-red-500">
                    {Array.isArray(errors.mst_siswa_id) ? errors.mst_siswa_id[0] : errors.mst_siswa_id}
                  </p>
                )}
              </div>
            </div>

            {/* Info Card */}
            <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg p-4">
              <h4 className="text-sm font-medium text-blue-800 dark:text-blue-400 mb-2">Informasi</h4>
              <ul className="text-sm text-blue-700 dark:text-blue-300 space-y-1 list-disc list-inside">
                <li>Pastikan ujian dan siswa sudah benar sebelum menyimpan</li>
                <li>Setelah disimpan, status ujian user akan menjadi "Belum Mulai"</li>
                <li>Siswa dapat memulai ujian setelah data ini dibuat</li>
              </ul>
            </div>

            <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
              <Button type="button" variant="secondary" onClick={() => navigate('/akademik/ujian-user')}>
                Batal
              </Button>
              <Button type="submit" disabled={loading}>
                <Save size={18} className="mr-2" />
                {loading ? 'Menyimpan...' : 'Simpan'}
              </Button>
            </div>
          </form>
        )}
      </Card>
    </div>
  )
}

export default UjianUserForm

import { useState, useEffect, useCallback } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { Clock, AlertCircle, ChevronLeft, ChevronRight, Flag, Send, BookOpen, User } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import { ujianUserService } from '../services/ujianUserService'
import { showSuccess, showError, showConfirm, showWarning } from '../../../utils/sweetalert'

const UjianUserMulai = () => {
  const { id } = useParams()
  const navigate = useNavigate()
  
  const [loading, setLoading] = useState(true)
  const [submitting, setSubmitting] = useState(false)
  const [ujianUser, setUjianUser] = useState(null)
  const [soalList, setSoalList] = useState([])
  const [currentSoalIndex, setCurrentSoalIndex] = useState(0)
  const [jawaban, setJawaban] = useState({})
  const [sisaWaktu, setSisaWaktu] = useState(0)
  const [isTimerRunning, setIsTimerRunning] = useState(false)

  // Fetch ujian user data and soal
  useEffect(() => {
    fetchUjianUserData()
  }, [id])

  const fetchUjianUserData = async () => {
    setLoading(true)
    const { data, error } = await ujianUserService.getById(id)
    if (data) {
      const ujianUserData = data.data
      setUjianUser(ujianUserData)
      
      // Set sisa waktu from API or default to 3600 seconds (1 hour)
      const initialSisaWaktu = ujianUserData.sisa_waktu || 3600
      setSisaWaktu(initialSisaWaktu > 0 ? initialSisaWaktu : 3600)
      setIsTimerRunning(true)
      
      // Initialize jawaban from existing data
      if (ujianUserData.jawaban && ujianUserData.jawaban.length > 0) {
        const initialJawaban = {}
        ujianUserData.jawaban.forEach(j => {
          initialJawaban[j.soal_id] = j.jawaban
        })
        setJawaban(initialJawaban)
      }
      
      // Mock soal data - in real implementation, this should come from API
      // For now, we'll create placeholder soal based on ujian data
      const mockSoal = generateMockSoal(ujianUserData)
      setSoalList(mockSoal)
    } else {
      showError('Gagal mengambil data ujian')
      navigate('/akademik/ujian-user')
    }
    setLoading(false)
  }

  // Generate mock soal for demo purposes
  // In real implementation, soal should come from API endpoint
  const generateMockSoal = (ujianUserData) => {
    // This is a placeholder - replace with actual API call to get soal
    return Array.from({ length: 10 }, (_, i) => ({
      id: i + 1,
      soal: `Soal nomor ${i + 1} untuk ujian ${ujianUserData.ujian?.nama || 'ini'}. Berikut adalah pertanyaan contoh yang akan ditampilkan kepada siswa.`,
      pilihan: [
        { id: 'A', teks: `Pilihan jawaban A untuk soal ${i + 1}` },
        { id: 'B', teks: `Pilihan jawaban B untuk soal ${i + 1}` },
        { id: 'C', teks: `Pilihan jawaban C untuk soal ${i + 1}` },
        { id: 'D', teks: `Pilihan jawaban D untuk soal ${i + 1}` },
      ],
      tipe: 'pilihan_ganda'
    }))
  }

  // Timer countdown
  useEffect(() => {
    let interval
    if (isTimerRunning && sisaWaktu > 0) {
      interval = setInterval(() => {
        setSisaWaktu(prev => {
          if (prev <= 1) {
            setIsTimerRunning(false)
            handleTimeUp()
            return 0
          }
          return prev - 1
        })
      }, 1000)
    }
    return () => clearInterval(interval)
  }, [isTimerRunning, sisaWaktu])

  const handleTimeUp = async () => {
    showWarning('Waktu ujian telah habis! Jawaban akan dikirim otomatis.', 'Waktu Habis')
    await handleSubmitUjian(true)
  }

  const formatTime = (seconds) => {
    const hours = Math.floor(seconds / 3600)
    const minutes = Math.floor((seconds % 3600) / 60)
    const secs = seconds % 60
    return `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`
  }

  const getTimerColorClass = () => {
    if (sisaWaktu < 300) return 'text-red-600 animate-pulse' // Less than 5 minutes
    if (sisaWaktu < 600) return 'text-yellow-600' // Less than 10 minutes
    return 'text-green-600'
  }

  const handleJawabanChange = (soalId, pilihanId) => {
    setJawaban(prev => ({
      ...prev,
      [soalId]: pilihanId
    }))
  }

  const handleNext = () => {
    if (currentSoalIndex < soalList.length - 1) {
      setCurrentSoalIndex(prev => prev + 1)
    }
  }

  const handlePrev = () => {
    if (currentSoalIndex > 0) {
      setCurrentSoalIndex(prev => prev - 1)
    }
  }

  const handleSoalClick = (index) => {
    setCurrentSoalIndex(index)
  }

  const handleSubmitUjian = async (isAutoSubmit = false) => {
    if (!isAutoSubmit) {
      const answeredCount = Object.keys(jawaban).length
      const unansweredCount = soalList.length - answeredCount
      
      let confirmMessage = `Anda telah menjawab ${answeredCount} dari ${soalList.length} soal.`
      if (unansweredCount > 0) {
        confirmMessage += `\n\nAda ${unansweredCount} soal yang belum dijawab.`
      }
      confirmMessage += `\n\nApakah Anda yakin ingin mengirim jawaban?`
      
      const result = await showConfirm(confirmMessage, 'Konfirmasi Pengiriman')
      if (!result.isConfirmed) return
    }

    setSubmitting(true)
    setIsTimerRunning(false)

    // Prepare jawaban data
    const jawabanArray = Object.entries(jawaban).map(([soalId, jawabanValue]) => ({
      soal_id: parseInt(soalId),
      jawaban: jawabanValue
    }))

    const submitData = {
      jawaban: jawabanArray
    }

    const { data, error } = await ujianUserService.selesaikanUjian(id, submitData)
    
    if (!error) {
      showSuccess('Ujian berhasil diselesaikan!', 'Selesai')
      navigate(`/akademik/ujian-user/${id}`)
    } else {
      showError('Gagal mengirim jawaban. Silakan coba lagi.')
      setSubmitting(false)
      setIsTimerRunning(true)
    }
  }

  const getAnsweredCount = () => {
    return Object.keys(jawaban).length
  }

  const getUnansweredCount = () => {
    return soalList.length - getAnsweredCount()
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center h-screen">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
      </div>
    )
  }

  if (!ujianUser || soalList.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-screen">
        <AlertCircle size={48} className="text-red-500 mb-4" />
        <p className="text-lg text-gray-700 dark:text-gray-300">Tidak dapat memuat data ujian</p>
        <Button variant="secondary" onClick={() => navigate('/akademik/ujian-user')} className="mt-4">
          Kembali
        </Button>
      </div>
    )
  }

  const currentSoal = soalList[currentSoalIndex]
  const progressPercentage = ((currentSoalIndex + 1) / soalList.length) * 100

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900">
      {/* Header */}
      <header className="bg-white dark:bg-gray-800 shadow-sm border-b border-gray-200 dark:border-gray-700 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            <div className="flex items-center gap-4">
              <BookOpen size={24} className="text-primary-600" />
              <div>
                <h1 className="text-lg font-semibold text-gray-900 dark:text-white">
                  {ujianUser.ujian?.nama || 'Ujian'}
                </h1>
                <p className="text-sm text-gray-500 dark:text-gray-400 flex items-center gap-1">
                  <User size={14} />
                  {ujianUser.siswa?.nama || 'Siswa'}
                </p>
              </div>
            </div>
            
            {/* Timer */}
            <div className={`flex items-center gap-2 px-4 py-2 rounded-lg bg-gray-100 dark:bg-gray-700 ${getTimerColorClass()}`}>
              <Clock size={20} />
              <span className="font-mono font-bold text-lg">
                {formatTime(sisaWaktu)}
              </span>
            </div>
          </div>
        </div>
        
        {/* Progress Bar */}
        <div className="w-full bg-gray-200 dark:bg-gray-700 h-1">
          <div 
            className="bg-primary-600 h-1 transition-all duration-300"
            style={{ width: `${progressPercentage}%` }}
          />
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
          {/* Soal Navigation Sidebar */}
          <div className="lg:col-span-1 order-2 lg:order-1">
            <Card className="sticky top-24">
              <div className="p-4">
                <h3 className="text-sm font-semibold text-gray-700 dark:text-gray-300 mb-3">
                  Navigasi Soal
                </h3>
                <div className="grid grid-cols-5 gap-2">
                  {soalList.map((soal, index) => {
                    const isAnswered = jawaban[soal.id] !== undefined
                    const isCurrent = index === currentSoalIndex
                    
                    return (
                      <button
                        key={soal.id}
                        onClick={() => handleSoalClick(index)}
                        className={`
                          w-10 h-10 rounded-lg text-sm font-medium transition-colors
                          ${isCurrent 
                            ? 'bg-primary-600 text-white' 
                            : isAnswered
                              ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400 border border-green-300 dark:border-green-700'
                              : 'bg-gray-100 text-gray-700 dark:bg-gray-700 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600'
                          }
                        `}
                      >
                        {index + 1}
                      </button>
                    )
                  })}
                </div>
                
                <div className="mt-4 pt-4 border-t border-gray-200 dark:border-gray-700 space-y-2">
                  <div className="flex items-center gap-2 text-sm">
                    <div className="w-4 h-4 bg-green-100 dark:bg-green-900/30 border border-green-300 dark:border-green-700 rounded"></div>
                    <span className="text-gray-600 dark:text-gray-400">Sudah dijawab ({getAnsweredCount()})</span>
                  </div>
                  <div className="flex items-center gap-2 text-sm">
                    <div className="w-4 h-4 bg-gray-100 dark:bg-gray-700 rounded"></div>
                    <span className="text-gray-600 dark:text-gray-400">Belum dijawab ({getUnansweredCount()})</span>
                  </div>
                  <div className="flex items-center gap-2 text-sm">
                    <div className="w-4 h-4 bg-primary-600 rounded"></div>
                    <span className="text-gray-600 dark:text-gray-400">Soal aktif</span>
                  </div>
                </div>
              </div>
            </Card>
          </div>

          {/* Soal Content */}
          <div className="lg:col-span-3 order-1 lg:order-2">
            <Card>
              <div className="p-6">
                {/* Soal Header */}
                <div className="flex items-center justify-between mb-6">
                  <span className="text-sm text-gray-500 dark:text-gray-400">
                    Soal {currentSoalIndex + 1} dari {soalList.length}
                  </span>
                  {jawaban[currentSoal.id] && (
                    <span className="flex items-center gap-1 text-sm text-green-600">
                      <Flag size={14} />
                      Sudah dijawab
                    </span>
                  )}
                </div>

                {/* Soal Text */}
                <div className="mb-8">
                  <h3 className="text-lg font-medium text-gray-900 dark:text-white mb-4">
                    {currentSoal.soal}
                  </h3>
                </div>

                {/* Pilihan Jawaban */}
                <div className="space-y-3">
                  {currentSoal.pilihan.map((pilihan) => (
                    <label
                      key={pilihan.id}
                      className={`
                        flex items-start gap-3 p-4 rounded-lg border-2 cursor-pointer transition-all
                        ${jawaban[currentSoal.id] === pilihan.id
                          ? 'border-primary-500 bg-primary-50 dark:bg-primary-900/20'
                          : 'border-gray-200 dark:border-gray-700 hover:border-gray-300 dark:hover:border-gray-600'
                        }
                      `}
                    >
                      <input
                        type="radio"
                        name={`soal-${currentSoal.id}`}
                        value={pilihan.id}
                        checked={jawaban[currentSoal.id] === pilihan.id}
                        onChange={() => handleJawabanChange(currentSoal.id, pilihan.id)}
                        className="mt-1 w-4 h-4 text-primary-600 border-gray-300 focus:ring-primary-500"
                      />
                      <div className="flex-1">
                        <span className="font-medium text-gray-900 dark:text-white">
                          {pilihan.id}.
                        </span>
                        <span className="ml-2 text-gray-700 dark:text-gray-300">
                          {pilihan.teks}
                        </span>
                      </div>
                    </label>
                  ))}
                </div>

                {/* Navigation Buttons */}
                <div className="flex items-center justify-between mt-8 pt-6 border-t border-gray-200 dark:border-gray-700">
                  <Button
                    variant="secondary"
                    onClick={handlePrev}
                    disabled={currentSoalIndex === 0}
                  >
                    <ChevronLeft size={18} className="mr-2" />
                    Sebelumnya
                  </Button>
                  
                  {currentSoalIndex === soalList.length - 1 ? (
                    <Button
                      variant="primary"
                      onClick={() => handleSubmitUjian(false)}
                      disabled={submitting}
                      className="bg-green-600 hover:bg-green-700"
                    >
                      <Send size={18} className="mr-2" />
                      {submitting ? 'Mengirim...' : 'Kirim Jawaban'}
                    </Button>
                  ) : (
                    <Button
                      variant="primary"
                      onClick={handleNext}
                    >
                      Selanjutnya
                      <ChevronRight size={18} className="ml-2" />
                    </Button>
                  )}
                </div>
              </div>
            </Card>

            {/* Submit Button (Mobile) */}
            <div className="mt-4 lg:hidden">
              <Button
                variant="primary"
                onClick={() => handleSubmitUjian(false)}
                disabled={submitting}
                className="w-full bg-green-600 hover:bg-green-700"
              >
                <Send size={18} className="mr-2" />
                {submitting ? 'Mengirim...' : 'Kirim Jawaban'}
              </Button>
            </div>
          </div>
        </div>
      </main>
    </div>
  )
}

export default UjianUserMulai

import { useCallback, useEffect, useState } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ArrowLeft, Save } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import Input from '../../../components/ui/Input'
import SearchableSelect from '../../../components/ui/SearchableSelect'
import { ujianService } from '../services/ujianService'
import { mapelService } from '../../mapel/services/mapelService'
import { kelasService } from '../../kelas/services/kelasService'
import { showSuccess, showError } from '../../../utils/sweetalert'
import { useReferenceOptions } from '../../../hooks/useReferenceOptions'
import { normalizeReferenceCode, safeParseInt } from '../../../utils/referenceUtils'

const UjianForm = () => {
  const { id } = useParams()
  const navigate = useNavigate()
  const isEditMode = !!id

  const { options: jenisUjianOptions } = useReferenceOptions('jenis_ujian', [
    { value: '1', label: 'Harian' },
    { value: '2', label: 'Penilaian Tengah Semester' },
  ])
  const { options: semesterOptions } = useReferenceOptions('kategori_semester', [
    { value: '1', label: 'Ganjil' },
    { value: '2', label: 'Genap' },
  ])

  const [loading, setLoading] = useState(false)
  const [fetchingData, setFetchingData] = useState(false)
  
  const [formData, setFormData] = useState({
    mst_mapel_id: '',
    mst_kelas_id: '',
    jenis: '',
    nama: '',
    tanggal: '',
    semester: '',
    tahun_ajaran: '',
    keterangan: ''
  })

  const [errors, setErrors] = useState({})
  const [selectedMapelOption, setSelectedMapelOption] = useState(null)
  const [selectedKelasOption, setSelectedKelasOption] = useState(null)

  const buildMapelOption = useCallback((mapel) => ({
    value: String(mapel.id),
    label: `${mapel.kode ? `${mapel.kode} - ` : ''}${mapel.nama || `Mapel #${mapel.id}`}`
  }), [])

  const buildKelasOption = useCallback((kelas) => ({
    value: String(kelas.id),
    label: kelas.nama_kelas || `Kelas #${kelas.id}`
  }), [])

  const searchMapelOptions = useCallback(async (keyword = '') => {
    const { data, error } = await mapelService.getMapel({
      search: keyword || undefined,
      per_page: 20
    })

    if (data?.data) {
      return data.data.map(buildMapelOption)
    }

    console.error('Failed to fetch mapel:', error)
    return []
  }, [buildMapelOption])

  const searchKelasOptions = useCallback(async (keyword = '') => {
    const { data, error } = await kelasService.getAll({
      search: keyword || undefined,
      per_page: 20
    })

    if (data?.data) {
      return data.data.map(buildKelasOption)
    }

    console.error('Failed to fetch kelas:', error)
    return []
  }, [buildKelasOption])

  const fetchUjian = useCallback(async () => {
    setFetchingData(true)
    const { data, error } = await ujianService.getById(id)
    if (data) {
      const ujian = data.data
      const mapelId = ujian.mst_mapel_id ? String(ujian.mst_mapel_id) : ''
      const kelasId = ujian.mst_kelas_id ? String(ujian.mst_kelas_id) : ''

      setFormData({
        mst_mapel_id: mapelId,
        mst_kelas_id: kelasId,
        // API kadang mengembalikan label ("Harian") bukan kode ("1").
        jenis: normalizeReferenceCode(ujian.jenis, jenisUjianOptions),
        nama: ujian.nama || '',
        tanggal: ujian.tanggal || '',
        semester: normalizeReferenceCode(ujian.semester, semesterOptions),
        tahun_ajaran: ujian.tahun_ajaran || '',
        keterangan: ujian.keterangan || ''
      })

      if (ujian.mapel?.id) {
        setSelectedMapelOption(buildMapelOption(ujian.mapel))
      } else if (mapelId) {
        setSelectedMapelOption({
          value: mapelId,
          label: `Mapel #${mapelId}`
        })
      } else {
        setSelectedMapelOption(null)
      }

      if (ujian.kelas?.id) {
        setSelectedKelasOption(buildKelasOption(ujian.kelas))
      } else if (kelasId) {
        setSelectedKelasOption({
          value: kelasId,
          label: `Kelas #${kelasId}`
        })
      } else {
        setSelectedKelasOption(null)
      }
    } else {
      showError('Gagal mengambil data ujian')
      navigate('/akademik/ujian')
    }
    setFetchingData(false)
  }, [buildKelasOption, buildMapelOption, id, navigate])

  useEffect(() => {
    if (isEditMode) {
      fetchUjian()
    }
  }, [fetchUjian, isEditMode])

  const handleChange = (e) => {
    const { name, value } = e.target
    setFormData(prev => ({ ...prev, [name]: value }))
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: null }))
    }
  }

  const validate = () => {
    const newErrors = {}
  
    if (!safeParseInt(formData.mst_mapel_id)) newErrors.mst_mapel_id = 'Mata pelajaran wajib dipilih'
    if (!safeParseInt(formData.mst_kelas_id)) newErrors.mst_kelas_id = 'Kelas wajib dipilih'
    if (!safeParseInt(formData.jenis)) newErrors.jenis = 'Jenis ujian wajib dipilih'
    if (!formData.nama) newErrors.nama = 'Nama ujian wajib diisi'
    if (!formData.tanggal) newErrors.tanggal = 'Tanggal ujian wajib diisi'
    if (!safeParseInt(formData.semester)) newErrors.semester = 'Semester wajib dipilih'
    if (!formData.tahun_ajaran) newErrors.tahun_ajaran = 'Tahun ajaran wajib diisi'
  
    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    
    if (!validate()) return

    setLoading(true)
    
    const submitData = {
      ...formData,
      mst_mapel_id: safeParseInt(formData.mst_mapel_id),
      mst_kelas_id: safeParseInt(formData.mst_kelas_id),
      jenis: safeParseInt(formData.jenis),
      semester: safeParseInt(formData.semester),
      keterangan: formData.keterangan || null
    }

    let result
    
    if (isEditMode) {
      result = await ujianService.update(id, submitData)
    } else {
      result = await ujianService.create(submitData)
    }

    const { error } = result

    if (!error) {
      showSuccess(`Ujian berhasil ${isEditMode ? 'diperbarui' : 'ditambahkan'}!`)
      navigate('/akademik/ujian')
    } else {
      console.error(error)
      if (error.errors) {
        setErrors(error.errors)
      } else {
        showError(`Gagal ${isEditMode ? 'memperbarui' : 'menambahkan'} ujian`)
      }
    }
    setLoading(false)
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="secondary" onClick={() => navigate('/akademik/ujian')}>
          <ArrowLeft size={18} className="mr-2" />
          Kembali
        </Button>
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
          {isEditMode ? 'Edit Ujian' : 'Tambah Ujian Baru'}
        </h1>
      </div>

      <Card>
        {fetchingData ? (
          <div className="flex items-center justify-center h-64">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="p-6 space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Mapel */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Mata Pelajaran <span className="text-red-500">*</span>
                </label>
                <SearchableSelect
                  name="mst_mapel_id"
                  value={formData.mst_mapel_id}
                  onChange={handleChange}
                  options={selectedMapelOption ? [selectedMapelOption] : []}
                  loadOptions={searchMapelOptions}
                  placeholder="Pilih mata pelajaran"
                  searchPlaceholder="Cari mata pelajaran berdasarkan kode atau nama..."
                  noOptionsText="Tidak ada mata pelajaran yang cocok"
                  error={errors.mst_mapel_id}
                />
              </div>

              {/* Kelas */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Kelas <span className="text-red-500">*</span>
                </label>
                <SearchableSelect
                  name="mst_kelas_id"
                  value={formData.mst_kelas_id}
                  onChange={handleChange}
                  options={selectedKelasOption ? [selectedKelasOption] : []}
                  loadOptions={searchKelasOptions}
                  placeholder="Pilih kelas"
                  searchPlaceholder="Cari kelas berdasarkan nama..."
                  noOptionsText="Tidak ada kelas yang cocok"
                  error={errors.mst_kelas_id}
                />
              </div>

              {/* Jenis Ujian */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Jenis Ujian <span className="text-red-500">*</span>
                </label>
                <select
                  name="jenis"
                  value={formData.jenis}
                  onChange={handleChange}
                  className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm focus:border-primary-500 focus:outline-none focus:ring-1 focus:ring-primary-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
                >
                  <option value="">Pilih jenis ujian</option>
                  {jenisUjianOptions.map(option => (
                    <option key={option.value} value={option.value}>
                      {option.label}
                    </option>
                  ))}
                </select>
                {errors.jenis && (
                  <p className="mt-1 text-sm text-red-500">
                    {Array.isArray(errors.jenis) ? errors.jenis[0] : errors.jenis}
                  </p>
                )}
              </div>

              {/* Nama Ujian */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Nama Ujian <span className="text-red-500">*</span>
                </label>
                <Input
                  name="nama"
                  value={formData.nama}
                  onChange={handleChange}
                  placeholder="Nama ujian"
                  maxLength={100}
                  error={errors.nama}
                />
              </div>

              {/* Tanggal */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Tanggal Ujian <span className="text-red-500">*</span>
                </label>
                <Input
                  type="date"
                  name="tanggal"
                  value={formData.tanggal}
                  onChange={handleChange}
                  error={errors.tanggal}
                />
              </div>

              {/* Semester */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Semester <span className="text-red-500">*</span>
                </label>
                <select
                  name="semester"
                  value={formData.semester}
                  onChange={handleChange}
                  className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm focus:border-primary-500 focus:outline-none focus:ring-1 focus:ring-primary-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
                >
                  <option value="">Pilih semester</option>
                  {semesterOptions.map(option => (
                    <option key={option.value} value={option.value}>
                      {option.label}
                    </option>
                  ))}
                </select>
                {errors.semester && (
                  <p className="mt-1 text-sm text-red-500">
                    {Array.isArray(errors.semester) ? errors.semester[0] : errors.semester}
                  </p>
                )}
              </div>

              {/* Tahun Ajaran */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Tahun Ajaran <span className="text-red-500">*</span>
                </label>
                <Input
                  name="tahun_ajaran"
                  value={formData.tahun_ajaran}
                  onChange={handleChange}
                  placeholder="Contoh: 2025/2026"
                  maxLength={20}
                  error={errors.tahun_ajaran}
                />
              </div>

              {/* Keterangan */}
              <div className="md:col-span-2">
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Keterangan
                </label>
                <textarea
                  name="keterangan"
                  value={formData.keterangan}
                  onChange={handleChange}
                  rows={3}
                  className="w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-sm focus:border-primary-500 focus:outline-none focus:ring-1 focus:ring-primary-500 dark:border-gray-600 dark:bg-gray-800 dark:text-white"
                  placeholder="Keterangan tambahan (opsional)"
                />
                {errors.keterangan && (
                  <p className="mt-1 text-sm text-red-500">
                    {Array.isArray(errors.keterangan) ? errors.keterangan[0] : errors.keterangan}
                  </p>
                )}
              </div>
            </div>

            <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-gray-700">
              <Button type="button" variant="secondary" onClick={() => navigate('/akademik/ujian')}>
                Batal
              </Button>
              <Button type="submit" disabled={loading}>
                <Save size={18} className="mr-2" />
                {loading ? 'Menyimpan...' : 'Simpan'}
              </Button>
            </div>
          </form>
        )}
      </Card>
    </div>
  )
}

export default UjianForm

import { useState, useEffect, useMemo, useCallback } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { AgGridReact } from 'ag-grid-react'
import { ArrowLeft, Save, RefreshCw, FileText, Users, BookOpen, GraduationCap, Award, TrendingUp, TrendingDown, BarChart3 } from 'lucide-react'
import Card from '../../../components/ui/Card'
import Button from '../../../components/ui/Button'
import { ujianService } from '../services/ujianService'
import { showSuccess, showError, showConfirm } from '../../../utils/sweetalert'

// Editable cell component for nilai
const NilaiCellEditor = (props) => {
  const [value, setValue] = useState(props.value || '')

  const onChange = (e) => {
    const newValue = e.target.value
    // Only allow numbers and decimal point
    if (newValue === '' || /^\d*\.?\d*$/.test(newValue)) {
      const numValue = parseFloat(newValue)
      if (newValue === '' || (numValue >= 0 && numValue <= 100)) {
        setValue(newValue)
      }
    }
  }

  const onBlur = () => {
    props.stopEditing()
  }

  const onKeyDown = (e) => {
    if (e.key === 'Enter') {
      props.stopEditing()
    } else if (e.key === 'Escape') {
      props.stopEditing(true)
    }
  }

  useEffect(() => {
    props.eGridCell.addEventListener('keydown', onKeyDown)
    return () => {
      props.eGridCell.removeEventListener('keydown', onKeyDown)
    }
  }, [])

  return (
    <input
      type="text"
      value={value}
      onChange={onChange}
      onBlur={onBlur}
      className="w-full h-full px-2 py-1 border-0 outline-none bg-transparent text-center"
      autoFocus
    />
  )
}

// Editable cell component for keterangan
const KeteranganCellEditor = (props) => {
  const [value, setValue] = useState(props.value || '')

  const onChange = (e) => {
    setValue(e.target.value)
  }

  const onBlur = () => {
    props.stopEditing()
  }

  const onKeyDown = (e) => {
    if (e.key === 'Enter') {
      props.stopEditing()
    } else if (e.key === 'Escape') {
      props.stopEditing(true)
    }
  }

  useEffect(() => {
    props.eGridCell.addEventListener('keydown', onKeyDown)
    return () => {
      props.eGridCell.removeEventListener('keydown', onKeyDown)
    }
  }, [])

  return (
    <input
      type="text"
      value={value}
      onChange={onChange}
      onBlur={onBlur}
      className="w-full h-full px-2 py-1 border-0 outline-none bg-transparent"
      autoFocus
    />
  )
}

const UjianNilai = () => {
  const { id } = useParams()
  const navigate = useNavigate()
  
  const [loading, setLoading] = useState(false)
  const [saving, setSaving] = useState(false)
  const [ujianData, setUjianData] = useState(null)
  const [nilaiData, setNilaiData] = useState([])
  const [hasChanges, setHasChanges] = useState(false)

  useEffect(() => {
    fetchNilaiData()
  }, [id])

  const fetchNilaiData = async () => {
    setLoading(true)
    const { data, error } = await ujianService.getNilaiByUjian(id)
    if (data) {
      setUjianData(data.data.ujian)
      // Add row index for "No" column
      const nilaiWithIndex = data.data.nilai.map((item, index) => ({
        ...item,
        rowIndex: index + 1
      }))
      setNilaiData(nilaiWithIndex)
      setHasChanges(false)
    } else {
      showError('Gagal mengambil data nilai')
      navigate('/akademik/ujian')
    }
    setLoading(false)
  }

  const getJenisLabel = (value) => {
    if (!value) return '-'
    const jenisMap = {
      1: 'PTS (Penilaian Tengah Semester)',
      2: 'PAS (Penilaian Akhir Semester)',
      3: 'PH (Penilaian Harian)',
      4: 'Try Out',
      5: 'Ujian Sekolah',
    }
    return jenisMap[value] || `Jenis ${value}`
  }

  const getJenisShortLabel = (value) => {
    if (!value) return '-'
    const jenisMap = {
      1: 'PTS',
      2: 'PAS',
      3: 'PH',
      4: 'Try Out',
      5: 'Ujian Sekolah',
    }
    return jenisMap[value] || `Jenis ${value}`
  }

  // Calculate statistics
  const statistics = useMemo(() => {
    if (!nilaiData || nilaiData.length === 0) {
      return { average: 0, highest: 0, lowest: 0, count: 0 }
    }

    const scores = nilaiData
      .map(item => parseFloat(item.nilai))
      .filter(score => !isNaN(score))

    if (scores.length === 0) {
      return { average: 0, highest: 0, lowest: 0, count: nilaiData.length }
    }

    const sum = scores.reduce((acc, score) => acc + score, 0)
    const average = sum / scores.length
    const highest = Math.max(...scores)
    const lowest = Math.min(...scores)

    return {
      average: average.toFixed(2),
      highest: highest.toFixed(2),
      lowest: lowest.toFixed(2),
      count: nilaiData.length
    }
  }, [nilaiData])

  // Handle cell value changes
  const onCellValueChanged = useCallback((params) => {
    setHasChanges(true)
    // Update the local data
    const updatedData = nilaiData.map(item => {
      if (item.id === params.data.id) {
        return { ...item, [params.colDef.field]: params.newValue }
      }
      return item
    })
    setNilaiData(updatedData)
  }, [nilaiData])

  // Handle save all changes
  const handleSave = async () => {
    if (!hasChanges) {
      showSuccess('Tidak ada perubahan untuk disimpan')
      return
    }

    const result = await showConfirm(
      'Simpan Perubahan',
      'Apakah Anda yakin ingin menyimpan semua perubahan nilai?'
    )

    if (result.isConfirmed) {
      setSaving(true)
      
      // Prepare data for bulk update
      const updateData = nilaiData.map(item => ({
        id: item.id,
        nilai: item.nilai,
        keterangan: item.keterangan
      }))

      // Note: The API endpoint for bulk update might need to be added to ujianService
      // For now, we'll simulate the success and show the data that would be sent
      console.log('Data to save:', updateData)
      
      // TODO: Implement actual bulk save API call when available
      // const { error } = await ujianService.saveNilaiBulk(id, updateData)
      
      setTimeout(() => {
        setSaving(false)
        setHasChanges(false)
        showSuccess('Nilai berhasil disimpan!')
      }, 500)
    }
  }

  const handleRefresh = () => {
    fetchNilaiData()
  }

  const columnDefs = useMemo(() => [
    {
      field: 'rowIndex',
      headerName: 'No',
      width: 70,
      sortable: false,
      filter: false,
      editable: false,
      cellStyle: { textAlign: 'center' }
    },
    {
      field: 'siswa.nis',
      headerName: 'NIS',
      sortable: true,
      filter: true,
      width: 120,
      editable: false,
      valueGetter: (params) => params.data.siswa?.nis || '-'
    },
    {
      field: 'siswa.nama',
      headerName: 'Nama Siswa',
      sortable: true,
      filter: true,
      flex: 1,
      minWidth: 200,
      editable: false,
      valueGetter: (params) => params.data.siswa?.nama || '-'
    },
    {
      field: 'nilai',
      headerName: 'Nilai',
      sortable: true,
      filter: true,
      width: 100,
      editable: true,
      cellStyle: { textAlign: 'center' },
      cellEditor: NilaiCellEditor,
      valueFormatter: (params) => {
        if (!params.value || params.value === '') return '-'
        return parseFloat(params.value).toFixed(2)
      }
    },
    {
      field: 'keterangan',
      headerName: 'Keterangan',
      sortable: true,
      filter: true,
      flex: 1,
      minWidth: 150,
      editable: true,
      cellEditor: KeteranganCellEditor,
      cellRenderer: (params) => params.value || '-'
    }
  ], [])

  const defaultColDef = useMemo(() => ({
    resizable: true,
    sortable: true,
    filter: true,
  }), [])

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      {/* Header Section */}
      <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
        <div className="flex items-center gap-4">
          <Button variant="secondary" onClick={() => navigate('/akademik/ujian')}>
            <ArrowLeft size={18} className="mr-2" />
            Kembali
          </Button>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Input Nilai Ujian</h1>
        </div>
        <div className="flex flex-wrap gap-3">
          <Button 
            variant="secondary" 
            onClick={handleRefresh}
            disabled={saving}
          >
            <RefreshCw size={18} className="mr-2" />
            Refresh
          </Button>
          <Button 
            onClick={handleSave} 
            variant={hasChanges ? 'primary' : 'secondary'}
            loading={saving}
            disabled={!hasChanges}
          >
            <Save size={18} className="mr-2" />
            Simpan Perubahan
          </Button>
        </div>
      </div>

      {/* Exam Info Card */}
      {ujianData && (
        <Card>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            <div className="flex items-start gap-3">
              <div className="w-10 h-10 bg-blue-50 dark:bg-blue-900/20 rounded-lg flex items-center justify-center flex-shrink-0">
                <BookOpen size={20} className="text-blue-600" />
              </div>
              <div>
                <p className="text-xs text-gray-500 dark:text-gray-400">Mata Pelajaran</p>
                <p className="font-medium text-gray-900 dark:text-white">
                  {ujianData.mapel?.nama || '-'}
                </p>
              </div>
            </div>

            <div className="flex items-start gap-3">
              <div className="w-10 h-10 bg-green-50 dark:bg-green-900/20 rounded-lg flex items-center justify-center flex-shrink-0">
                <GraduationCap size={20} className="text-green-600" />
              </div>
              <div>
                <p className="text-xs text-gray-500 dark:text-gray-400">Kelas</p>
                <p className="font-medium text-gray-900 dark:text-white">
                  {ujianData.kelas?.nama_kelas || '-'}
                </p>
              </div>
            </div>

            <div className="flex items-start gap-3">
              <div className="w-10 h-10 bg-purple-50 dark:bg-purple-900/20 rounded-lg flex items-center justify-center flex-shrink-0">
                <FileText size={20} className="text-purple-600" />
              </div>
